/**
 * Admin.gs
 * Products (with photos), Users and Settings management. Every change is written to Audit_Log.
 * Note: edits made directly in the Google Sheet are NOT recorded in Audit_Log
 * (except PINs typed in the Users sheet).
 */

// ---------------- Products ----------------

function apiGetProducts(token) {
  return run_(function () {
    const user = requirePerm_(token, 'products.view');
    const canSeeCost = hasPerm_(user.role, 'products.view_cost');
    const products = readTable_('Products').rows.map(function (r) {
      const price = moneyNum_(r.Selling_Price);
      const cost = moneyNum_(r.Cost);
      const p = {
        id: String(r.Product_ID).trim(), name: String(r.Product_Name).trim(), category: String(r.Category).trim(),
        price: isFinite(price) ? price : null, active: isTrue_(r.Active),
        recipeGroup: String(r.Recipe_Group || '').trim().toUpperCase() || 'NONE',
        image: normalizeImageUrl_(r.Image_URL)
      };
      if (canSeeCost) p.cost = isFinite(cost) ? cost : null;
      return p;
    }).filter(function (p) { return p.id; });
    const cats = categoryOrder_();
    products.forEach(function (p) { if (p.category && cats.indexOf(p.category) < 0) cats.push(p.category); });
    return { products: products, categories: cats, canEdit: hasPerm_(user.role, 'products.manage'), canSeeCost: canSeeCost };
  });
}

function apiSaveProduct(token, data) {
  return run_(function () {
    const user = requirePerm_(token, 'products.manage');
    data = data || {};
    const name = cleanText_(data.name, 60);
    const category = cleanText_(data.category, 30);
    const price = Number(data.price);
    const cost = Number(data.cost || 0);
    const group = String(data.recipeGroup || 'NONE').toUpperCase();
    const active = data.active === true;
    if (!name) throw new Error('Nama produk wajib diisi.');
    if (!category) throw new Error('Kategori wajib diisi.');
    if (!Number.isInteger(price) || price < 0 || price > 100000000) throw new Error('Harga jual harus angka Rupiah bulat.');
    if (!Number.isInteger(cost) || cost < 0 || cost > 100000000) throw new Error('Harga pokok harus angka Rupiah bulat.');
    if (RECIPE_GROUPS.indexOf(group) < 0) throw new Error('Grup resep tidak dikenal.');

    return withLock_(function () {
      const table = readTable_('Products');
      const fields = { Product_Name: name, Category: category, Selling_Price: price, Cost: cost, Active: active,
                       Recipe_Group: group, Updated_At: nowStamp_() };
      if (data.id) {
        const row = table.rows.filter(function (r) { return String(r.Product_ID).trim() === String(data.id); })[0];
        if (!row) throw new Error('Produk tidak ditemukan: ' + data.id);
        const before = { name: String(row.Product_Name), category: String(row.Category), price: moneyNum_(row.Selling_Price),
                         cost: moneyNum_(row.Cost), active: isTrue_(row.Active), group: String(row.Recipe_Group) };
        updateRow_('Products', row._row, fields);
        const priceChanged = before.price !== price || before.cost !== cost;
        audit_(user, priceChanged ? 'PRODUCT_PRICE_CHANGE' : 'PRODUCT_UPDATE', 'Product', data.id,
               { before: before, after: { name: name, category: category, price: price, cost: cost, active: active, group: group } });
        return { id: data.id };
      }
      const id = nextId_(table.rows.map(function (r) { return r.Product_ID; }), 'P', 3);
      fields.Product_ID = id;
      appendObjects_('Products', [fields]);
      audit_(user, 'PRODUCT_CREATE', 'Product', id, { name: name, category: category, price: price, cost: cost });
      return { id: id };
    });
  });
}

/** The Drive folder where product photos are kept. Created the first time. */
function photoFolder_() {
  const props = PropertiesService.getScriptProperties();
  const id = props.getProperty('PHOTO_FOLDER_ID');
  if (id) {
    try { return DriveApp.getFolderById(id); } catch (e) { /* folder deleted: make a new one */ }
  }
  const folder = DriveApp.createFolder('JayaPOS Product Photos');
  props.setProperty('PHOTO_FOLDER_ID', folder.getId());
  return folder;
}

function driveIdFromUrl_(url) {
  const m = String(url || '').match(/[?&]id=([A-Za-z0-9_-]{20,})/) || String(url || '').match(/\/d\/([A-Za-z0-9_-]{20,})/);
  return m ? m[1] : '';
}

/**
 * Saves a product photo. dataUrl is a resized JPEG made by the phone ("data:image/jpeg;base64,...").
 * Pass an empty dataUrl to remove the photo.
 */
function apiSetProductImage(token, productId, dataUrl) {
  return run_(function () {
    const user = requirePerm_(token, 'products.manage');
    const row = readTable_('Products').rows.filter(function (r) { return String(r.Product_ID).trim() === String(productId); })[0];
    if (!row) throw new Error('Produk tidak ditemukan: ' + productId);
    const oldUrl = String(row.Image_URL || '');
    let url = '';
    if (dataUrl) {
      const m = String(dataUrl).match(/^data:(image\/(?:jpeg|png|webp));base64,([A-Za-z0-9+/=]+)$/);
      if (!m) throw new Error('File ini bukan gambar yang didukung (pakai JPG atau PNG).');
      if (m[2].length > 8 * 1024 * 1024) throw new Error('Gambar terlalu besar. Pilih foto yang lebih kecil.');
      const bytes = Utilities.base64Decode(m[2]);
      const ext = m[1] === 'image/png' ? '.png' : (m[1] === 'image/webp' ? '.webp' : '.jpg');
      const file = photoFolder_().createFile(Utilities.newBlob(bytes, m[1], String(productId) + '_' + Date.now() + ext));
      try {
        file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
      } catch (e) {
        file.setTrashed(true);
        throw new Error('Google Drive tidak mengizinkan foto dibagikan lewat link, jadi tidak bisa tampil di kasir. (' + e.message + ')');
      }
      url = 'https://drive.google.com/thumbnail?id=' + file.getId() + '&sz=w600';
    }
    updateRow_('Products', row._row, { Image_URL: url, Updated_At: nowStamp_() });
    const oldId = driveIdFromUrl_(oldUrl);
    if (oldId && oldUrl.indexOf('drive.google.com') >= 0) {
      try {
        const f = DriveApp.getFileById(oldId);
        if (f.getParents().hasNext() && f.getParents().next().getId() === photoFolder_().getId()) f.setTrashed(true);
      } catch (e) { /* old photo not ours or already gone */ }
    }
    audit_(user, url ? 'PRODUCT_PHOTO_SET' : 'PRODUCT_PHOTO_REMOVE', 'Product', String(productId), '');
    return { id: productId, image: url };
  });
}

// ---------------- Users ----------------

function createUser_(data, actor) {
  const name = cleanText_(data.name, 60);
  if (!name) throw new Error('Nama lengkap wajib diisi.');
  const username = String(data.username || '').trim().toLowerCase();
  if (!/^[a-z0-9._-]{3,30}$/.test(username)) {
    throw new Error('Username harus 3–30 karakter: huruf, angka, titik atau strip. Tanpa spasi.');
  }
  const role = String(data.role || '').toUpperCase();
  if (ROLES.indexOf(role) < 0) throw new Error('Role tidak dikenal.');
  checkPinFormat_(data.pin);
  const users = getUsers_();
  if (users.some(function (u) { return u.username === username; })) throw new Error('Username "' + username + '" sudah dipakai.');
  const id = nextId_(users.map(function (u) { return u.id; }), 'U', 3);
  const salt = newSalt_();
  appendObjects_('Users', [{
    User_ID: id, Full_Name: name, Username: username, Role: role, New_PIN: '',
    PIN_Hash: hashPin_(String(data.pin), salt), PIN_Salt: salt, Active_Status: true,
    Created_At: nowStamp_(), Updated_At: nowStamp_()
  }]);
  audit_(actor, 'USER_CREATE', 'User', id, { username: username, role: role });
  return id;
}

function apiListUsers(token) {
  return run_(function () {
    requirePerm_(token, 'users.manage');
    return {
      roles: ROLES,
      users: getUsers_().map(function (u) {
        return { id: u.id, name: u.name, username: u.username, role: u.role, active: u.active, hasPin: !!u.hash };
      })
    };
  });
}

function apiSaveUser(token, data) {
  return run_(function () {
    const actor = requirePerm_(token, 'users.manage');
    data = data || {};
    return withLock_(function () {
      if (!data.id) return { id: createUser_(data, actor) };

      const users = getUsers_();
      const u = users.filter(function (x) { return x.id === String(data.id); })[0];
      if (!u) throw new Error('Pengguna tidak ditemukan.');
      const name = cleanText_(data.name, 60);
      const role = String(data.role || '').toUpperCase();
      const active = data.active === true;
      if (!name) throw new Error('Nama lengkap wajib diisi.');
      if (ROLES.indexOf(role) < 0) throw new Error('Role tidak dikenal.');
      if (u.id === actor.id && (role !== 'ADMIN' || !active)) {
        throw new Error('Anda tidak bisa mencabut role admin Anda sendiri atau menonaktifkan diri sendiri.');
      }
      const otherAdmins = users.filter(function (x) { return x.id !== u.id && x.role === 'ADMIN' && x.active; });
      if (u.role === 'ADMIN' && (role !== 'ADMIN' || !active) && !otherAdmins.length) {
        throw new Error('Harus selalu ada minimal satu admin yang aktif.');
      }
      updateRow_('Users', u.row, { Full_Name: name, Role: role, Active_Status: active, Updated_At: nowStamp_() });
      audit_(actor, 'USER_UPDATE', 'User', u.id,
             { before: { name: u.name, role: u.role, active: u.active }, after: { name: name, role: role, active: active } });
      return { id: u.id };
    });
  });
}

function apiResetUserPin(token, userId, pin) {
  return run_(function () {
    const actor = requirePerm_(token, 'users.manage');
    checkPinFormat_(pin);
    return withLock_(function () {
      const u = getUsers_().filter(function (x) { return x.id === String(userId); })[0];
      if (!u) throw new Error('Pengguna tidak ditemukan.');
      setUserPin_(u, String(pin), actor);
      return true;
    });
  });
}

// ---------------- Settings ----------------

function apiGetSettings(token) {
  return run_(function () {
    requirePerm_(token, 'settings.manage');
    const map = getSettingsMap_();
    return SETTINGS_DEFAULTS.map(function (d) { return { key: d[0], label: SETTING_LABELS[d[0]] || d[0], value: map[d[0]], description: d[2] }; });
  });
}

function apiSaveSetting(token, key, value) {
  return run_(function () {
    const user = requirePerm_(token, 'settings.manage');
    key = String(key || '');
    const def = SETTINGS_DEFAULTS.filter(function (d) { return d[0] === key; })[0];
    if (!def) throw new Error('Pengaturan tidak dikenal.');
    const label = SETTING_LABELS[key] || key;
    let v = cleanText_(value, 300);
    const bools = ['Allow_Discount', 'Service_On_Takeaway', 'Tax_On_Takeaway', 'Show_Product_Images', 'Deduct_Stock_On_Sale', 'Require_Shift'];
    if (key === 'Costing_Method') {
      v = v.toUpperCase();
      if (v !== 'AVERAGE' && v !== 'LAST') throw new Error(label + ' harus AVERAGE atau LAST.');
    }
    if (key === 'Cash_Rounding_Mode') {
      v = v.toUpperCase();
      if (['NEAREST', 'DOWN', 'UP'].indexOf(v) < 0) throw new Error(label + ' harus NEAREST, DOWN atau UP.');
    }
    if (key === 'Tx_Prefix') {
      v = v.toUpperCase();
      if (!/^[A-Z]{1,5}$/.test(v)) throw new Error(label + ' harus 1–5 huruf (A–Z).');
    }
    if (key === 'Receipt_Width_mm' && v !== '58' && v !== '80') throw new Error(label + ' harus 58 atau 80.');
    if ((key === 'Cashier_History_Days' || key === 'Cashier_Void_Days') && !/^\d{1,3}$/.test(v)) throw new Error(label + ' harus berupa angka.');
    if (key === 'Cash_Rounding') {
      v = v.replace(/[^0-9]/g, '');
      if (v === '' || Number(v) > 100000) throw new Error(label + ' harus angka Rupiah, contoh 1000 (0 = tanpa pembulatan).');
      v = String(Number(v));
    }
    if (key === 'Max_Cash_In_Drawer' || key === 'Cash_Diff_Tolerance') {
      v = v.replace(/[^0-9]/g, '');
      if (v === '' || Number(v) > 1000000000) throw new Error(label + ' harus angka Rupiah (0 = mati).');
      v = String(Number(v));
    }
    if (key === 'Quick_Notes') {
      v = v.split(',').map(function (x) { return x.trim().slice(0, 30); }).filter(String).slice(0, 20).join(',');
    }
    if (key === 'Max_Discount_Percent') {
      const n = Number(v.replace(',', '.').replace('%', ''));
      if (!isFinite(n) || n < 0 || n > 100) throw new Error(label + ' harus angka 0 sampai 100.');
      v = String(n);
    }
    if (key === 'Service_Percent' || key === 'Tax_Percent') {
      v = v.replace(',', '.').replace('%', '').trim();
      const n = Number(v);
      if (v === '' || !isFinite(n) || n < 0 || n > 50) throw new Error(label + ' harus angka 0 sampai 50.');
      v = String(n);
    }
    if (bools.indexOf(key) >= 0) {
      v = v.toUpperCase();
      if (v !== 'TRUE' && v !== 'FALSE') throw new Error(label + ' harus TRUE atau FALSE.');
    }
    return withLock_(function () {
      const row = readTable_('Settings').rows.filter(function (r) { return String(r.Setting).trim() === key; })[0];
      const before = row ? cellText_(row.Value) : '';
      if (row) updateRow_('Settings', row._row, { Value: v });
      else appendObjects_('Settings', [{ Setting: key, Value: v, Description: def[2] }]);
      SETTINGS_CACHE_ = null;
      audit_(user, 'SETTING_UPDATE', 'Setting', key, { before: before, after: v });
      return { key: key, value: v };
    });
  });
}

/**
 * Auth.gs
 * Login with username + PIN, sessions, permission checks, audit log,
 * and adding users / PINs straight from the Users sheet.
 *
 * How it works:
 *  - PINs are never kept. Only a salted SHA-256 "fingerprint" (PIN_Hash) is saved.
 *  - In the Users sheet you may type a PIN in the New_PIN column. JayaPOS turns it
 *    into a fingerprint right away and clears the cell.
 *  - After login the phone gets a random session token. Every server call sends it.
 *  - Every server call re-reads the user from the Users sheet, so deactivating
 *    a user or changing their role takes effect immediately.
 *  - Permissions are checked HERE on the server, not only by hiding buttons.
 *
 * Functions whose names end with "_" cannot be called from the browser
 * (Apps Script rule). Browser-callable functions all start with "api".
 */

function run_(fn) {
  try {
    return { ok: true, data: fn() };
  } catch (e) {
    console.error(e && e.stack ? e.stack : e);
    return { ok: false, error: (e && e.message) ? e.message : String(e), code: (e && e.jayaCode) || '' };
  }
}

function jayaError_(message, code) {
  const e = new Error(message);
  e.jayaCode = code;
  return e;
}

// ---------------- PIN hashing ----------------

function bytesToHex_(bytes) {
  return bytes.map(function (b) { return ('0' + (b & 0xff).toString(16)).slice(-2); }).join('');
}

function hashPin_(pin, salt) {
  let h = salt + ':' + pin;
  for (let i = 0; i < 100; i++) {
    h = bytesToHex_(Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, h + ':' + salt, Utilities.Charset.UTF_8));
  }
  return h;
}

function newSalt_() { return Utilities.getUuid().replace(/-/g, ''); }

function checkPinFormat_(pin) {
  if (!/^\d{4,8}$/.test(String(pin == null ? '' : pin))) throw new Error('PIN harus 4 sampai 8 angka.');
}

// ---------------- Users ----------------

function getUsers_() {
  let rows = readTable_('Users').rows;
  const pending = rows.some(function (r) {
    return String(r.New_PIN == null ? '' : r.New_PIN).trim() !== '' ||
           (!String(r.User_ID || '').trim() && String(r.Username || '').trim() !== '');
  });
  if (pending) {           // someone typed in the Users sheet and the edit trigger did not run
    processUserSheet_();
    rows = readTable_('Users').rows;
  }
  return rows.map(function (r) {
    return {
      row: r._row,
      id: String(r.User_ID).trim(),
      name: String(r.Full_Name).trim(),
      username: String(r.Username).trim().toLowerCase(),
      role: String(r.Role).trim().toUpperCase(),
      hash: String(r.PIN_Hash || '').trim(),
      salt: String(r.PIN_Salt || '').trim(),
      active: isTrue_(r.Active_Status)
    };
  }).filter(function (u) { return u.id && u.username; });
}

function setUserPin_(user, pin, actor) {
  checkPinFormat_(pin);
  const salt = newSalt_();
  updateRow_('Users', user.row, { PIN_Hash: hashPin_(String(pin), salt), PIN_Salt: salt, Updated_At: nowStamp_() });
  CacheService.getScriptCache().remove('fail_' + user.username);
  audit_(actor, 'USER_PIN_RESET', 'User', user.id, { username: user.username });
}

/**
 * Tidies the Users sheet after someone types in it:
 *  - new row with a Username gets a User_ID, Role CASHIER and Active TRUE if left empty
 *  - a PIN typed in New_PIN becomes PIN_Hash/PIN_Salt and the cell is cleared
 *  - problems are shown as a note on the cell (hover to read)
 */
function processUserSheet_() {
  const t = readTable_('Users');
  const sh = t.sheet;
  const H = t.headers;
  if (H.indexOf('New_PIN') < 0) return 0;
  const ids = t.rows.map(function (r) { return String(r.User_ID || '').trim(); }).filter(String);
  const usernames = {};
  t.rows.forEach(function (r) {
    const u = String(r.Username || '').trim().toLowerCase();
    if (u) usernames[u] = (usernames[u] || 0) + 1;
  });
  let changed = 0;

  t.rows.forEach(function (r) {
    const fields = {};
    const note = function (header, msg) { sh.getRange(r._row, H.indexOf(header) + 1).setNote(msg); };
    let id = String(r.User_ID || '').trim();
    const rawName = String(r.Username || '').trim();
    const uname = rawName.toLowerCase();
    const pin = String(r.New_PIN == null ? '' : r.New_PIN).trim();
    const nameOk = /^[a-z0-9._-]{3,30}$/.test(uname);

    if (rawName && rawName !== uname && nameOk) fields.Username = uname;
    const role = String(r.Role || '').trim().toUpperCase();
    if (role && role !== String(r.Role)) fields.Role = role;
    if (role && ROLES.indexOf(role) < 0) note('Role', 'Role tidak dikenal. Pilih salah satu: ' + ROLES.join(', '));

    if (!id && uname) {
      if (!nameOk) {
        note('Username', 'Username harus 3–30 karakter: huruf, angka, titik atau strip. Tanpa spasi.');
      } else if (usernames[uname] > 1) {
        note('Username', 'Username ini sudah dipakai di baris lain.');
      } else {
        id = nextId_(ids, 'U', 3);
        ids.push(id);
        fields.User_ID = id;
        fields.Created_At = nowStamp_();
        if (!role) fields.Role = 'CASHIER';
        if (String(r.Active_Status == null ? '' : r.Active_Status).trim() === '') fields.Active_Status = true;
        if (!String(r.Full_Name || '').trim()) fields.Full_Name = rawName;
        sh.getRange(r._row, H.indexOf('Username') + 1).clearNote();
      }
    }

    if (pin) {
      fields.New_PIN = '';                     // never leave a typed PIN in the sheet
      if (!id) {
        note('New_PIN', 'PIN tidak tersimpan: isi Username yang benar dulu, lalu ketik PIN lagi.');
      } else if (!/^\d{4,8}$/.test(pin)) {
        note('New_PIN', 'PIN tidak tersimpan: harus 4 sampai 8 angka. Ketik lagi.');
      } else {
        const salt = newSalt_();
        fields.PIN_Hash = hashPin_(pin, salt);
        fields.PIN_Salt = salt;
        fields.Updated_At = nowStamp_();
        note('New_PIN', 'PIN diset ' + nowStamp_() + '. Ketik di sini lagi kapan saja untuk menggantinya.');
        CacheService.getScriptCache().remove('fail_' + uname);
        audit_(null, 'USER_PIN_SET_IN_SHEET', 'User', id, { username: uname });
      }
    }

    if (Object.keys(fields).length) {
      updateRow_('Users', r._row, fields);
      changed++;
    }
  });
  return changed;
}

// ---------------- Permissions ----------------

function hasPerm_(role, perm) {
  const list = ROLE_PERMISSIONS[role] || [];
  return list.indexOf('*') >= 0 || list.indexOf(perm) >= 0;
}
function hasAnyPerm_(role, perms) {
  return perms.some(function (p) { return hasPerm_(role, p); });
}

function navFor_(role) {
  return NAV.filter(function (n) { return hasAnyPerm_(role, n.perms); })
    .map(function (n) { return { id: n.id, label: n.label, section: n.section || '', ready: n.ready, phase: n.phase || null, about: n.about || '' }; });
}

function requireSession_(token) {
  if (!token || typeof token !== 'string' || token.length > 100) throw jayaError_('Silakan login.', 'AUTH');
  const cache = CacheService.getScriptCache();
  const raw = cache.get('sess_' + token);
  if (!raw) throw jayaError_('Sesi Anda sudah habis. Silakan login lagi.', 'AUTH');
  const s = JSON.parse(raw);
  const user = getUsers_().filter(function (u) { return u.id === s.u; })[0];
  if (!user || !user.active || ROLES.indexOf(user.role) < 0) {
    cache.remove('sess_' + token);
    throw jayaError_('Akun Anda tidak aktif. Hubungi admin.', 'AUTH');
  }
  cache.put('sess_' + token, raw, SESSION_SECONDS); // keep session alive while in use
  return user;
}

/** Throws unless the logged-in user has at least one of the permissions. */
function requirePerm_(token, perms) {
  const user = requireSession_(token);
  const list = Array.isArray(perms) ? perms : [perms];
  if (!hasAnyPerm_(user.role, list)) {
    throw jayaError_('Akses ditolak. Role Anda (' + (ROLE_LABELS[user.role] || user.role) + ') tidak boleh melakukan ini.', 'DENIED');
  }
  return user;
}

function sessionPayload_(user, token) {
  return {
    token: token,
    user: { id: user.id, name: user.name, username: user.username, role: user.role },
    permissions: ROLE_PERMISSIONS[user.role] || [],
    nav: navFor_(user.role),
    settings: getSettingsMap_(),
    paymentMethods: PAYMENT_METHODS,
    paymentOrder: PAYMENT_ORDER,
    roleLabels: ROLE_LABELS,
    unreadNotifications: hasPerm_(user.role, 'notifications.view') ? safeUnread_() : 0,
    version: APP_VERSION
  };
}

function safeUnread_() {
  try { return notifUnreadCount_(); } catch (e) { return 0; }
}

// ---------------- Audit log ----------------

function audit_(user, action, recordType, recordId, details) {
  try {
    appendObjects_('Audit_Log', [{
      Timestamp: nowStamp_(),
      User_ID: user ? user.id : 'SYSTEM',
      Username: user ? user.username : 'system',
      Action: action,
      Record_Type: recordType || '',
      Record_ID: recordId || '',
      Details: typeof details === 'string' ? details : JSON.stringify(details || {})
    }]);
  } catch (e) {
    console.error('Audit log failed: ' + e);
  }
}

// ---------------- Browser-callable ----------------

function apiGetLoginUsers() {
  return run_(function () {
    const s = getSettingsMap_();
    const users = getUsers_()
      .filter(function (u) { return u.active && u.hash; })
      .map(function (u) { return { username: u.username, name: u.name }; })
      .sort(function (a, b) { return a.name.localeCompare(b.name); });
    return { users: users, businessName: s.Business_Name, appName: s.App_Name };
  });
}

function apiLogin(username, pin) {
  return run_(function () {
    const uname = String(username || '').trim().toLowerCase().slice(0, 40);
    const cache = CacheService.getScriptCache();
    const failKey = 'fail_' + uname;
    const fails = Number(cache.get(failKey) || 0);
    if (fails >= MAX_PIN_FAILS) throw new Error('Terlalu banyak PIN salah. Tunggu 5 menit lalu coba lagi.');

    const user = getUsers_().filter(function (u) { return u.username === uname; })[0];
    const ok = user && user.active && user.hash && /^\d{4,8}$/.test(String(pin || '')) &&
               hashPin_(String(pin), user.salt) === user.hash;
    if (!ok) {
      cache.put(failKey, String(fails + 1), PIN_LOCK_SECONDS);
      audit_(null, 'LOGIN_FAILED', 'User', user ? user.id : '', { username: uname });
      throw new Error('Username atau PIN salah.');
    }
    cache.remove(failKey);
    const token = Utilities.getUuid() + Utilities.getUuid().replace(/-/g, '');
    cache.put('sess_' + token, JSON.stringify({ u: user.id, t: Date.now() }), SESSION_SECONDS);
    audit_(user, 'LOGIN', 'User', user.id, '');
    return sessionPayload_(user, token);
  });
}

function apiResume(token) {
  return run_(function () { return sessionPayload_(requireSession_(token), token); });
}

function apiLogout(token) {
  return run_(function () {
    if (token && typeof token === 'string' && token.length <= 100) CacheService.getScriptCache().remove('sess_' + token);
    return true;
  });
}

/**
 * Code.gs
 *  - doGet(): opens the JayaPOS web app.
 *  - onOpen(): adds the "JayaPOS" menu to the Google Sheet.
 *  - onEdit(): when you type in the Users sheet, turns New_PIN into a safe fingerprint.
 *  - menu...(): actions in the JayaPOS menu. They only work from inside the Sheet.
 */

function doGet() {
  try { autoMigrate_(); } catch (e) { console.error('autoMigrate_: ' + e); }
  let appName = 'JayaPOS';
  try { appName = getSettingsMap_().App_Name || appName; } catch (e) {}
  return HtmlService.createTemplateFromFile('Index')
    .evaluate()
    .setTitle(appName)
    .addMetaTag('viewport', 'width=device-width, initial-scale=1, maximum-scale=1')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);   // lets the JayaPOS home-screen launcher (Netlify) show the app
}

/** Used by Index.html to pull in the other HTML files. */
function include(name) {
  const allowed = ['Styles', 'AppJs', 'PosJs', 'TablesJs', 'HistoryJs', 'AdminJs', 'InventoryJs', 'PurchasingJs', 'ReportsJs', 'ShiftJs', 'KitchenJs'];
  if (allowed.indexOf(name) < 0) throw new Error('File tidak diizinkan: ' + name);
  return HtmlService.createHtmlOutputFromFile(name).getContent();
}

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu('JayaPOS')
    .addItem('1. Setup / perbaiki database', 'menuSetup')
    .addItem('2. Set / reset PIN pengguna', 'menuSetPin')
    .addItem('3. Terapkan perubahan sheet Users', 'menuApplyUsers')
    .addItem('4. Update aplikasi', 'menuUpdate')
    .addItem('5. Kembalikan ke backup terakhir', 'menuRollback')
    .addSeparator()
    .addItem('Tampilkan link aplikasi', 'menuShowLink')
    .addToUi();
}

/** Runs by itself whenever someone edits the Sheet. Only reacts to the Users tab. */
function onEdit(e) {
  try {
    if (!e || !e.range) return;
    if (e.range.getSheet().getName() !== 'Users') return;
    SS_CACHE_ = e.source;
    processUserSheet_();
  } catch (err) {
    console.error('onEdit Users: ' + err);
  }
}

/** Throws if not run from the Sheet menu (so nobody can trigger these from the web app). */
function sheetUi_() {
  try { return SpreadsheetApp.getUi(); }
  catch (e) { throw new Error('Perintah ini hanya bisa dijalankan dari menu JayaPOS di dalam Google Sheet.'); }
}

function askText_(ui, title, message) {
  const res = ui.prompt(title, message, ui.ButtonSet.OK_CANCEL);
  if (res.getSelectedButton() !== ui.Button.OK) return null;
  return res.getResponseText().trim();
}

function menuSetup() {
  const ui = sheetUi_();
  setupDatabase_();
  const users = getUsers_();
  const hasAdmin = users.some(function (u) { return u.role === 'ADMIN' && u.active && u.hash; });
  let msg = 'Database JayaPOS siap (versi ' + APP_VERSION + ').\n\n';
  if (!hasAdmin) {
    const pin = askText_(ui, 'Buat user ADMIN',
      'Pilih PIN 4–8 angka untuk user admin (username: admin).\nCatat di tempat yang aman.');
    if (!pin) {
      ui.alert('Setup selesai, tapi user admin BELUM dibuat.\nJalankan "1. Setup / perbaiki database" lagi untuk membuatnya.');
      return;
    }
    checkPinFormat_(pin);
    const existing = users.filter(function (u) { return u.username === 'admin'; })[0];
    if (existing) {
      setUserPin_(existing, pin, null);
      updateRow_('Users', existing.row, { Role: 'ADMIN', Active_Status: true });
    } else {
      createUser_({ name: 'Admin', username: 'admin', role: 'ADMIN', pin: pin }, null);
    }
    msg += 'User admin sudah dibuat.\nUsername: admin\nPIN: PIN yang baru Anda pilih.\n\n';
  }
  msg += 'Kalau kodenya diubah, jangan lupa: Deploy > Manage deployments > edit > New version.';
  ui.alert(msg);
}

function menuSetPin() {
  const ui = sheetUi_();
  const username = askText_(ui, 'Set / reset PIN', 'Username pengguna (contoh: admin):');
  if (!username) return;
  const user = getUsers_().filter(function (u) { return u.username === username.toLowerCase(); })[0];
  if (!user) { ui.alert('Tidak ada pengguna dengan username "' + username + '". Cek sheet Users.'); return; }
  const pin = askText_(ui, 'PIN baru untuk ' + user.name, 'Ketik PIN baru 4–8 angka:');
  if (!pin) return;
  checkPinFormat_(pin);
  setUserPin_(user, pin, null);
  ui.alert('PIN untuk ' + user.name + ' sudah diganti.');
}

function menuApplyUsers() {
  const ui = sheetUi_();
  const n = processUserSheet_();
  ui.alert(n ? n + ' baris pengguna diperbarui. Arahkan mouse ke sel yang ada segitiga hitam kecil untuk membaca catatannya.'
             : 'Tidak ada yang perlu diperbarui. Baris yang bermasalah punya catatan di selnya (segitiga hitam kecil).');
}

function menuShowLink() {
  const ui = sheetUi_();
  let url = '';
  try { url = ScriptApp.getService().getUrl(); } catch (e) {}
  ui.alert(url ? 'Link aplikasi JayaPOS:\n\n' + url : 'Aplikasi belum di-deploy. Ikuti Langkah 6 di setup kit.');
}

