/**
 * Database.gs
 * Reading and writing the Google Sheet. Other files use only these helpers.
 * Columns are found by their HEADER NAME, so you may reorder columns safely
 * (but do not rename headers).
 */

let SS_CACHE_ = null;
let SETTINGS_CACHE_ = null;

function getSpreadsheet_() {
  if (SS_CACHE_) return SS_CACHE_;
  const id = PropertiesService.getScriptProperties().getProperty('SPREADSHEET_ID');
  SS_CACHE_ = id ? SpreadsheetApp.openById(id) : SpreadsheetApp.getActiveSpreadsheet();
  if (!SS_CACHE_) {
    throw new Error('JayaPOS tidak menemukan Google Sheet-nya. Buka Sheet lalu jalankan JayaPOS > 1. Setup / perbaiki database.');
  }
  return SS_CACHE_;
}

function getSheet_(name) {
  const sh = getSpreadsheet_().getSheetByName(name);
  if (!sh) {
    throw new Error('Sheet "' + name + '" tidak ada. Buka Google Sheet lalu jalankan JayaPOS > 1. Setup / perbaiki database.');
  }
  return sh;
}

function getHeaders_(sh) {
  const lastCol = sh.getLastColumn();
  if (lastCol < 1) return [];
  return sh.getRange(1, 1, 1, lastCol).getValues()[0].map(function (h) { return String(h).trim(); });
}

/** Reads a whole sheet into objects keyed by header. Each object has _row (sheet row number). */
function readTable_(name) {
  const sh = getSheet_(name);
  const lastRow = sh.getLastRow();
  const lastCol = sh.getLastColumn();
  if (lastRow < 1 || lastCol < 1) return { sheet: sh, headers: [], rows: [] };
  const values = sh.getRange(1, 1, lastRow, lastCol).getValues();
  const headers = values[0].map(function (h) { return String(h).trim(); });
  const rows = [];
  for (let i = 1; i < values.length; i++) {
    const r = values[i];
    if (r.every(function (v) { return v === '' || v === null; })) continue;
    const o = { _row: i + 1 };
    headers.forEach(function (h, j) { if (h) o[h] = r[j]; });
    rows.push(o);
  }
  return { sheet: sh, headers: headers, rows: rows };
}

function rowObject_(sh, headers, rowNum) {
  const vals = sh.getRange(rowNum, 1, 1, headers.length).getValues()[0];
  const o = { _row: rowNum };
  headers.forEach(function (h, j) { if (h) o[h] = vals[j]; });
  return o;
}

/** Fast exact-match search in one column. Returns sheet row numbers. */
function findRowNumbers_(sh, headers, header, value) {
  const c = headers.indexOf(header);
  const lastRow = sh.getLastRow();
  if (c < 0 || lastRow < 2) return [];
  return sh.getRange(2, c + 1, lastRow - 1, 1)
    .createTextFinder(String(value))
    .matchEntireCell(true)
    .matchCase(true)
    .findAll()
    .map(function (r) { return r.getRow(); });
}

/** Appends rows (objects keyed by header) in ONE write, with correct number formats. */
function appendObjects_(name, objects) {
  if (!objects || !objects.length) return;
  const sh = getSheet_(name);
  const headers = getHeaders_(sh);
  const schema = SCHEMA[name] || {};
  const textCols = schema.text || [];
  const moneyCols = schema.money || [];
  const rows = objects.map(function (o) {
    return headers.map(function (h) { return (o[h] === undefined || o[h] === null) ? '' : o[h]; });
  });
  const formats = objects.map(function () {
    return headers.map(function (h) {
      if (textCols.indexOf(h) >= 0) return '@';
      if (moneyCols.indexOf(h) >= 0) return '#,##0';
      return 'General';
    });
  });
  const start = sh.getLastRow() + 1;
  const needed = start + rows.length - 1;
  if (needed > sh.getMaxRows()) sh.insertRowsAfter(sh.getMaxRows(), needed - sh.getMaxRows() + 200);
  const range = sh.getRange(start, 1, rows.length, headers.length);
  range.setNumberFormats(formats);
  range.setValues(rows);
}

/** Updates some cells of one row in a single write. fields = { Header: value } */
function updateRow_(name, rowNum, fields) {
  const sh = getSheet_(name);
  const headers = getHeaders_(sh);
  const textCols = (SCHEMA[name] || {}).text || [];
  const range = sh.getRange(rowNum, 1, 1, headers.length);
  const values = range.getValues()[0];
  const formats = range.getNumberFormats()[0];
  Object.keys(fields).forEach(function (k) {
    const c = headers.indexOf(k);
    if (c < 0) throw new Error('Kolom "' + k + '" tidak ada di sheet ' + name + '. Jalankan JayaPOS > 1. Setup / perbaiki database.');
    values[c] = fields[k];
    if (textCols.indexOf(k) >= 0) formats[c] = '@';
  });
  range.setNumberFormats([formats]);
  range.setValues([values]);
}

function getSettingsMap_() {
  if (SETTINGS_CACHE_) return SETTINGS_CACHE_;
  const map = {};
  SETTINGS_DEFAULTS.forEach(function (d) { map[d[0]] = d[1]; });
  try {
    readTable_('Settings').rows.forEach(function (r) {
      const k = String(r.Setting).trim();
      if (k) map[k] = cellText_(r.Value);
    });
  } catch (e) { /* Settings sheet missing: use defaults */ }
  SETTINGS_CACHE_ = map;
  return map;
}

/** Runs fn while holding the script lock, so two phones cannot write at the same moment. */
function withLock_(fn) {
  const lock = LockService.getScriptLock();
  if (!lock.tryLock(25000)) throw new Error('Sistem sedang sibuk. Tunggu beberapa detik lalu coba lagi.');
  try { return fn(); } finally { lock.releaseLock(); }
}

// ---------------- Small value helpers ----------------

function tz_() { return Session.getScriptTimeZone() || 'Asia/Makassar'; }
function fmt_(d, pattern) { return Utilities.formatDate(d, tz_(), pattern); }
function todayStr_() { return fmt_(new Date(), 'yyyy-MM-dd'); }
function nowStamp_() { return fmt_(new Date(), 'yyyy-MM-dd HH:mm:ss'); }

function cellText_(v) {
  if (v === null || v === undefined) return '';
  if (v instanceof Date) return fmt_(v, 'yyyy-MM-dd HH:mm:ss');
  return String(v).trim();
}
function dateText_(v) {
  if (v instanceof Date) return fmt_(v, 'yyyy-MM-dd');
  return String(v == null ? '' : v).trim().slice(0, 10);
}
function timeText_(v) {
  if (v instanceof Date) return fmt_(v, 'HH:mm');
  return String(v == null ? '' : v).trim().slice(0, 5);
}
/** Rupiah amounts are whole numbers. Returns NaN for an empty cell. */
function moneyNum_(v) {
  if (typeof v === 'number') return Math.round(v);
  const s = String(v == null ? '' : v).replace(/[^0-9-]/g, '');
  return (s === '' || s === '-') ? NaN : parseInt(s, 10);
}
/** Plain number (decimals allowed), with a default. */
function numOr_(v, d) {
  const n = typeof v === 'number' ? v : parseFloat(String(v == null ? '' : v).replace(',', '.'));
  return isFinite(n) ? n : d;
}
function isTrue_(v) {
  return v === true || /^(true|yes|ya|y|1|active|aktif)$/i.test(String(v == null ? '' : v).trim());
}
/** Cleans user-typed text: one line, length limit, cannot start a formula. */
function cleanText_(v, max) {
  return String(v == null ? '' : v).replace(/[\r\n\t]+/g, ' ').trim().replace(/^[=+@]+/, '').trim().slice(0, max || 100);
}
function nextId_(ids, prefix, pad) {
  let max = 0;
  ids.forEach(function (id) {
    const m = String(id).match(/(\d+)$/);
    if (m) max = Math.max(max, parseInt(m[1], 10));
  });
  return prefix + String(max + 1).padStart(pad, '0');
}
function isDateStr_(s) { return /^\d{4}-\d{2}-\d{2}$/.test(String(s || '')); }
function addDays_(ds, n) {
  const p = ds.split('-').map(Number);
  return Utilities.formatDate(new Date(Date.UTC(p[0], p[1] - 1, p[2] + n)), 'UTC', 'yyyy-MM-dd');
}
function dayOfWeek_(ds) { // 0 = Sunday
  const p = ds.split('-').map(Number);
  return new Date(Date.UTC(p[0], p[1] - 1, p[2])).getUTCDay();
}
function dateLabel_(ds) {
  if (!isDateStr_(ds)) return ds || '';
  const m = ['Jan', 'Feb', 'Mar', 'Apr', 'Mei', 'Jun', 'Jul', 'Agu', 'Sep', 'Okt', 'Nov', 'Des'];
  const p = ds.split('-');
  return p[2] + ' ' + m[parseInt(p[1], 10) - 1] + ' ' + p[0];
}
function listSetting_(key) {
  return String(getSettingsMap_()[key] || '').split(',').map(function (c) { return c.trim(); }).filter(String);
}

/** For recipes/inventory later: convert qty between units with the same base (kg->g ok, g->ml refused). */
function convertQty_(qty, fromUnit, toUnit) {
  const a = UNITS[String(fromUnit).toLowerCase()];
  const b = UNITS[String(toUnit).toLowerCase()];
  if (!a || !b) throw new Error('Satuan tidak dikenal: ' + (!a ? fromUnit : toUnit));
  if (a.base !== b.base) throw new Error('Tidak bisa mengubah ' + fromUnit + ' ke ' + toUnit + '.');
  return qty * a.factor / b.factor;
}

// ---------------- Setup ----------------

/** Creates / repairs all sheets. Safe to run again: it never deletes your data. */
function setupDatabase_() {
  const ss = SpreadsheetApp.getActiveSpreadsheet() || getSpreadsheet_();   // no active Sheet when called from the web app
  PropertiesService.getScriptProperties().setProperty('SPREADSHEET_ID', ss.getId());
  SS_CACHE_ = ss;
  SETTINGS_CACHE_ = null;
  ss.setSpreadsheetTimeZone(tz_());

  Object.keys(SCHEMA).forEach(function (name) { ensureSheet_(ss, name, SCHEMA[name]); });

  const settingRows = readTable_('Settings').rows;
  const existing = settingRows.map(function (r) { return String(r.Setting).trim(); });
  const descUpd = {};   // keep the Description column up to date (it is only an explanation)
  settingRows.forEach(function (r) {
    const d = SETTINGS_DEFAULTS.filter(function (x) { return x[0] === String(r.Setting).trim(); })[0];
    if (d && String(r.Description) !== d[2]) descUpd[r._row] = d[2];
  });
  setColumnValues_('Settings', 'Description', descUpd);
  appendObjects_('Settings', SETTINGS_DEFAULTS
    .filter(function (d) { return existing.indexOf(d[0]) < 0; })
    .map(function (d) { return { Setting: d[0], Value: d[1], Description: d[2] }; }));
  SETTINGS_CACHE_ = null;

  if (readTable_('Products').rows.length === 0) {
    appendObjects_('Products', SAMPLE_PRODUCTS.map(function (p) {
      return { Product_ID: p[0], Product_Name: p[1], Category: p[2], Selling_Price: p[3], Cost: p[4],
               Active: true, Recipe_Group: p[5], Updated_At: nowStamp_(), Image_URL: '' };
    }));
  }

  if (readTable_('Tables').rows.length === 0) {
    appendObjects_('Tables', SAMPLE_TABLES.map(function (t) {
      return { Table_ID: t[0], Table_Name: t[1], Area: t[2], Seats: t[3], Shape: t[4], Pos_X: t[5], Pos_Y: t[6],
               Width: t[7], Height: t[8], Active: true, Updated_At: nowStamp_() };
    }));
  }

  ['Sheet1', 'Lembar1', 'Sheet 1'].forEach(function (n) {
    const s = ss.getSheetByName(n);
    if (s && ss.getSheets().length > 1 && s.getLastRow() === 0 && s.getLastColumn() === 0) ss.deleteSheet(s);
  });

  audit_(null, 'SETUP', 'System', '', 'Database setup / repair, version ' + APP_VERSION);
  PropertiesService.getScriptProperties().setProperty('SCHEMA_VERSION', APP_VERSION);
}

function ensureSheet_(ss, name, schema) {
  let sh = ss.getSheetByName(name);
  if (!sh) sh = ss.insertSheet(name);
  let headers = getHeaders_(sh);
  if (!headers.length || headers.every(function (h) { return !h; })) {
    sh.getRange(1, 1, 1, schema.headers.length).setValues([schema.headers]);
  } else {
    schema.headers.forEach(function (h) {
      if (headers.indexOf(h) < 0) {
        sh.getRange(1, sh.getLastColumn() + 1).setValue(h);
        headers = getHeaders_(sh);
      }
    });
  }
  headers = getHeaders_(sh);
  const maxRows = sh.getMaxRows();
  (schema.text || []).forEach(function (h) {
    const c = headers.indexOf(h);
    if (c >= 0) sh.getRange(1, c + 1, maxRows, 1).setNumberFormat('@');
  });
  (schema.money || []).forEach(function (h) {
    const c = headers.indexOf(h);
    if (c >= 0 && maxRows > 1) sh.getRange(2, c + 1, maxRows - 1, 1).setNumberFormat('#,##0');
  });
  Object.keys(schema.lists || {}).forEach(function (h) {
    const c = headers.indexOf(h);
    if (c < 0 || maxRows < 2) return;
    const rule = SpreadsheetApp.newDataValidation()
      .requireValueInList(schema.lists[h], true)
      .setAllowInvalid(true)
      .build();
    sh.getRange(2, c + 1, maxRows - 1, 1).setDataValidation(rule);
  });
  sh.getRange(1, 1, 1, headers.length)
    .setFontWeight('bold')
    .setBackground(schema.planned ? '#9e9e9e' : '#3b2a20')
    .setFontColor('#ffffff');
  sh.setFrozenRows(1);
  if (schema.planned) sh.setTabColor('#9e9e9e');
  else if (['Ingredients', 'Recipes', 'Recipe_Details', 'Suppliers', 'Purchase_Orders', 'Purchase_Order_Details',
            'Inventory_Movements'].indexOf(name) >= 0) sh.setTabColor(null);   // v1 showed these as "planned" (grey)
}

/** Deletes every row whose column `header` equals value. Rows are removed bottom-up in blocks. */
function deleteRowsWhere_(name, header, value) {
  const sh = getSheet_(name);
  const rows = findRowNumbers_(sh, getHeaders_(sh), header, value).sort(function (a, b) { return b - a; });
  let i = 0;
  while (i < rows.length) {
    let end = rows[i];
    let start = end;
    while (i + 1 < rows.length && rows[i + 1] === start - 1) { i++; start = rows[i]; }
    sh.deleteRows(start, end - start + 1);
    i++;
  }
  return rows.length;
}

/** Writes one whole column (rows 2..n+1) in a single call. values = array in sheet row order. */
function writeColumn_(name, header, values) {
  if (!values.length) return;
  const sh = getSheet_(name);
  const c = getHeaders_(sh).indexOf(header);
  if (c < 0) throw new Error('Kolom "' + header + '" tidak ada di sheet ' + name + '. Jalankan JayaPOS > 1. Setup / perbaiki database.');
  sh.getRange(2, c + 1, values.length, 1).setValues(values.map(function (v) { return [v]; }));
}

function round4_(n) { return Math.round(n * 10000) / 10000; }

/**
 * Inventory.gs  (Phase 2 + stock part of Phase 3)
 * Ingredients, recipes, COGS per serving, stock levels, waste and stock counts.
 *
 * How costing works:
 *  - Every ingredient has ONE base unit: g, ml, pcs or portion.
 *  - It is bought in a Purchase_Unit (e.g. "kg", "bottle 1L", "box 24") with Purchase_To_Base
 *    = how many base units are in one purchase unit (kg = 1000 g, box = 24 pcs).
 *  - Goods receiving (Purchasing.gs) sets Cost_Per_Base_Unit from the REAL price paid
 *    (weighted average or last price, see Settings > Costing_Method).
 *  - A recipe line says e.g. "250 g pork belly". Its cost = 250 x cost per g.
 *    Recipe cost / Yield_Quantity (servings) = COGS per serving.
 *  - Units only convert inside the same base: kg<->g, l<->ml. g->ml is refused.
 *  - Each sale saves the COGS per serving at that moment (Transaction_Details.Unit_Cost)
 *    and, if Deduct_Stock_On_Sale is TRUE, takes the ingredients out of stock.
 */

// ---------------- Lists & access ----------------

function ingredientsList_() {
  return readTable_('Ingredients').rows.map(function (r) {
    const group = String(r.Ingredient_Group || '').trim().toUpperCase();
    const base = String(r.Base_Unit || '').trim().toLowerCase();
    const ptb = numOr_(r.Purchase_To_Base, 1);
    return {
      row: r._row,
      id: String(r.Ingredient_ID).trim(),
      name: String(r.Ingredient_Name).trim(),
      group: INGREDIENT_GROUPS.indexOf(group) >= 0 ? group : 'FOOD',
      baseUnit: BASE_UNITS.indexOf(base) >= 0 ? base : 'pcs',
      purchaseUnit: String(r.Purchase_Unit || '').trim() || base || 'pcs',
      purchaseToBase: ptb > 0 ? ptb : 1,
      cost: Math.max(0, numOr_(r.Cost_Per_Base_Unit, 0)),
      lastPrice: moneyNum_(r.Last_Purchase_Price) || 0,
      stock: numOr_(r.Stock_Qty_Base, 0),
      minStock: Math.max(0, numOr_(r.Min_Stock_Base, 0)),
      supplierId: String(r.Default_Supplier_ID || '').trim(),
      active: String(r.Active_Status == null ? '' : r.Active_Status).trim() === '' ? true : isTrue_(r.Active_Status)
    };
  }).filter(function (i) { return i.id && i.name; });
}

function groupWord_(g) { return { FOOD: 'makanan', BEVERAGE: 'minuman', SHARED: 'bersama' }[g] || String(g || '').toLowerCase(); }

function uniq_(arr) { return arr.filter(function (v, i) { return arr.indexOf(v) === i; }); }

/** Which ingredient groups a user may see / change. */
function ingredientAccess_(user) {
  const r = user.role;
  if (hasPerm_(r, '*') || hasPerm_(r, 'ingredients.purchasing')) return { view: INGREDIENT_GROUPS.slice(), edit: INGREDIENT_GROUPS.slice() };
  let view = [], edit = [];
  ['food', 'beverage'].forEach(function (g) {
    const G = g.toUpperCase();
    if (['ingredients.', 'recipes.', 'cogs.', 'stock.'].some(function (p) { return hasPerm_(r, p + g); })) view.push(G, 'SHARED');
    if (hasPerm_(r, 'ingredients.' + g)) edit.push(G, 'SHARED');
  });
  if (hasPerm_(r, 'inventory.view') || hasPerm_(r, 'purchasing.view')) view = INGREDIENT_GROUPS.slice();
  return { view: uniq_(view), edit: uniq_(edit) };
}

function canRecipe_(user, group, kind) {   // kind: 'edit' | 'view'
  const r = user.role;
  if (hasPerm_(r, '*')) return true;
  const g = group === 'BEVERAGE' ? 'beverage' : (group === 'FOOD' ? 'food' : '');
  if (!g) return false;
  if (kind === 'edit') return hasPerm_(r, 'recipes.' + g);
  return hasPerm_(r, 'recipes.' + g) || hasPerm_(r, 'cogs.' + g) || hasPerm_(r, 'reports.view');
}

function canStock_(user, group, kind) {    // kind: 'view' | 'waste'
  const r = user.role;
  if (hasPerm_(r, '*')) return true;
  if (kind === 'view' && hasPerm_(r, 'inventory.view')) return true;
  if (group === 'SHARED') return hasPerm_(r, 'stock.food') || hasPerm_(r, 'stock.beverage');
  return hasPerm_(r, 'stock.' + (group === 'BEVERAGE' ? 'beverage' : 'food'));
}

function unitsForBase_(base) {
  return Object.keys(UNITS).filter(function (u) { return UNITS[u].base === base; });
}

function publicUnits_() {
  const out = {};
  BASE_UNITS.forEach(function (b) { out[b] = unitsForBase_(b); });
  return out;
}

// ---------------- Recipe maths ----------------

/** All active recipes with live costs. productId -> recipe. */
function recipeData_() {
  const ings = {};
  ingredientsList_().forEach(function (i) { ings[i.id] = i; });
  const details = {};
  readTable_('Recipe_Details').rows.forEach(function (d) {
    const id = String(d.Recipe_ID).trim();
    (details[id] = details[id] || []).push(d);
  });
  const recipes = {};
  readTable_('Recipes').rows.forEach(function (r) {
    if (!isTrue_(r.Active_Status)) return;
    const recipeId = String(r.Recipe_ID).trim();
    const productId = String(r.Product_ID).trim();
    if (!recipeId || !productId) return;
    const yieldQty = numOr_(r.Yield_Quantity, 1) > 0 ? numOr_(r.Yield_Quantity, 1) : 1;
    const problems = [];
    const lines = (details[recipeId] || [])
      .sort(function (a, b) { return Number(a.Line_No) - Number(b.Line_No); })
      .map(function (d) {
        const ing = ings[String(d.Ingredient_ID).trim()];
        const qty = numOr_(d.Quantity_Required, 0);
        const unit = String(d.Unit || '').trim().toLowerCase();
        let baseQty = 0, unitCost = 0, problem = '';
        if (!ing) problem = 'Bahan ' + d.Ingredient_ID + ' tidak ditemukan';
        else {
          try { baseQty = convertQty_(qty, unit, ing.baseUnit); } catch (e) { problem = ing.name + ': ' + e.message; }
          unitCost = UNITS[unit] ? ing.cost * UNITS[unit].factor : 0;
          if (!problem && ing.cost === 0) problem = ing.name + ' belum punya harga pokok (belum ada pembelian)';
        }
        if (problem) problems.push(problem);
        return {
          ingredientId: String(d.Ingredient_ID).trim(), name: ing ? ing.name : '(missing)', qty: qty, unit: unit,
          baseQty: baseQty, baseUnit: ing ? ing.baseUnit : '', unitCost: round4_(unitCost), cost: baseQty * (ing ? ing.cost : 0)
        };
      });
    const total = lines.reduce(function (s, l) { return s + l.cost; }, 0);
    const consumption = {};
    lines.forEach(function (l) {
      if (l.baseQty > 0 && ings[l.ingredientId]) consumption[l.ingredientId] = (consumption[l.ingredientId] || 0) + l.baseQty / yieldQty;
    });
    recipes[productId] = {
      recipeId: recipeId, productId: productId, yieldQty: yieldQty, notes: String(r.Notes || ''),
      updatedAt: cellText_(r.Updated_At), updatedBy: String(r.Updated_By || ''), row: r._row,
      lines: lines, totalCost: Math.round(total), perServing: Math.round(total / yieldQty),
      consumption: consumption, problems: problems
    };
  });
  return { recipes: recipes, ingredients: ings };
}

/** Same data, cached for 5 minutes for the POS (faster sales). Cleared whenever costs or recipes change. */
function recipeDataCached_() {
  const cache = CacheService.getScriptCache();
  const raw = cache.get('recipeData');
  if (raw) { try { return JSON.parse(raw); } catch (e) {} }
  const d = recipeData_();
  try { cache.put('recipeData', JSON.stringify(d), 300); } catch (e) { /* too big for cache: fine */ }
  return d;
}
function clearRecipeCache_() { CacheService.getScriptCache().remove('recipeData'); }

/** Updates one column for some rows in a single read + write. updates = { sheetRow: value } */
function setColumnValues_(name, header, updates) {
  const rows = Object.keys(updates);
  if (!rows.length) return;
  const sh = getSheet_(name);
  const c = getHeaders_(sh).indexOf(header);
  if (c < 0) throw new Error('Kolom "' + header + '" tidak ada di sheet ' + name + '. Jalankan JayaPOS > 1. Setup / perbaiki database.');
  const lastRow = sh.getLastRow();
  if (lastRow < 2) return;
  const range = sh.getRange(2, c + 1, lastRow - 1, 1);
  const vals = range.getValues();
  rows.forEach(function (r) { const i = Number(r) - 2; if (i >= 0 && i < vals.length) vals[i][0] = updates[r]; });
  range.setValues(vals);
}

/** Keeps Products.Cost equal to the recipe COGS per serving (for products that have a recipe). */
function refreshProductCosts_(data) {
  data = data || recipeData_();
  const updates = {};
  readTable_('Products').rows.forEach(function (r) {
    const rc = data.recipes[String(r.Product_ID).trim()];
    if (rc && moneyNum_(r.Cost) !== rc.perServing) updates[r._row] = rc.perServing;
  });
  setColumnValues_('Products', 'Cost', updates);
  clearRecipeCache_();
}

// ---------------- Stock movements ----------------

function nextSeq_(key, count) {
  const props = PropertiesService.getScriptProperties();
  const start = Number(props.getProperty(key) || 0);
  props.setProperty(key, String(start + count));
  return start;
}

/**
 * Writes movements and updates stock (and costs) in a few sheet calls.
 * moves: [{ ing, type, qty, unit, baseQty (signed), unitCost (per base), ref, notes, supplierId }]
 * costUpdates: { ingredientId: { cost: perBase, lastPrice: perPurchaseUnit } }
 * Call inside withLock_.
 */
function applyMovements_(moves, user, costUpdates) {
  costUpdates = costUpdates || {};
  if (!moves.length && !Object.keys(costUpdates).length) return;
  const now = new Date();
  const dateKey = fmt_(now, 'yyyyMMdd');
  const stamp = fmt_(now, 'yyyy-MM-dd HH:mm:ss');
  const date = fmt_(now, 'yyyy-MM-dd');
  if (moves.length) {
    const start = nextSeq_('MVSEQ_' + dateKey, moves.length);
    appendObjects_('Inventory_Movements', moves.map(function (m, i) {
      return {
        Movement_ID: 'MV-' + dateKey + '-' + String(start + i + 1).padStart(4, '0'), Timestamp: stamp, Date: date,
        Ingredient_ID: m.ing.id, Ingredient_Name: m.ing.name, Movement_Type: m.type, Quantity: round4_(m.qty), Unit: m.unit,
        Quantity_Base: round4_(m.baseQty), Unit_Cost_Base: round4_(m.unitCost), Total_Cost: Math.round(m.baseQty * m.unitCost),
        Reference_ID: m.ref || '', User_ID: user ? user.id : 'SYSTEM', Notes: m.notes || '', Supplier_ID: m.supplierId || ''
      };
    }));
  }
  const current = {};
  ingredientsList_().forEach(function (i) { current[i.id] = i; });
  const stockUpd = {}, costUpd = {}, lastUpd = {}, stampUpd = {};
  moves.forEach(function (m) {
    const ing = current[m.ing.id];
    if (!ing) return;
    ing.stock = round4_(ing.stock + m.baseQty);
    stockUpd[ing.row] = ing.stock;
  });
  Object.keys(costUpdates).forEach(function (id) {
    const ing = current[id];
    if (!ing) return;
    const u = costUpdates[id];
    if (u.cost !== undefined) costUpd[ing.row] = round4_(u.cost);
    if (u.lastPrice !== undefined) lastUpd[ing.row] = u.lastPrice;
    stampUpd[ing.row] = stamp;
  });
  setColumnValues_('Ingredients', 'Stock_Qty_Base', stockUpd);
  setColumnValues_('Ingredients', 'Cost_Per_Base_Unit', costUpd);
  setColumnValues_('Ingredients', 'Last_Purchase_Price', lastUpd);
  setColumnValues_('Ingredients', 'Updated_At', stampUpd);
  if (Object.keys(costUpd).length) clearRecipeCache_();
}

/** Called after a sale is saved: takes recipe ingredients out of stock. Never blocks the sale. */
function inventoryOnSale_(txId, lines, user, rdata) {
  if (!isTrue_(getSettingsMap_().Deduct_Stock_On_Sale)) return;
  const totals = {};
  lines.forEach(function (l) {
    const rc = rdata.recipes[l.productId];
    if (!rc) return;
    Object.keys(rc.consumption).forEach(function (ingId) {
      totals[ingId] = (totals[ingId] || 0) + rc.consumption[ingId] * l.qty;
    });
  });
  const moves = Object.keys(totals).map(function (ingId) {
    const ing = rdata.ingredients[ingId];
    return { ing: ing, type: 'SALE', qty: -totals[ingId], unit: ing.baseUnit, baseQty: -totals[ingId], unitCost: ing.cost, ref: txId };
  }).filter(function (m) { return m.ing; });
  applyMovements_(moves, user, {});
}

// ---------------- Ingredients API ----------------

function apiGetIngredients(token) {
  return run_(function () {
    const user = requirePerm_(token, ['ingredients.food', 'ingredients.beverage', 'ingredients.purchasing', 'inventory.view',
      'recipes.food', 'recipes.beverage', 'stock.food', 'stock.beverage', 'cogs.food', 'cogs.beverage', 'purchasing.manage', 'purchasing.view']);
    const acc = ingredientAccess_(user);
    const sup = {};
    suppliersList_().forEach(function (s) { sup[s.id] = s; });
    return {
      ingredients: ingredientsList_().filter(function (i) { return acc.view.indexOf(i.group) >= 0; }).map(function (i) {
        return { id: i.id, name: i.name, group: i.group, baseUnit: i.baseUnit, purchaseUnit: i.purchaseUnit,
                 purchaseToBase: i.purchaseToBase, cost: round4_(i.cost), costPerPurchaseUnit: Math.round(i.cost * i.purchaseToBase),
                 lastPrice: i.lastPrice, stock: i.stock, minStock: i.minStock, supplierId: i.supplierId,
                 supplierName: sup[i.supplierId] ? sup[i.supplierId].name : '', active: i.active,
                 value: Math.round(Math.max(0, i.stock) * i.cost), low: i.active && i.minStock > 0 && i.stock < i.minStock };
      }),
      editGroups: acc.edit,
      canAdjust: hasPerm_(user.role, '*'),
      units: publicUnits_(),
      suppliers: suppliersList_().filter(function (s) { return s.active; }).map(function (s) { return { id: s.id, name: s.name }; })
    };
  });
}

function apiSaveIngredient(token, d) {
  return run_(function () {
    const user = requirePerm_(token, ['ingredients.food', 'ingredients.beverage', 'ingredients.purchasing']);
    const acc = ingredientAccess_(user);
    d = d || {};
    const name = cleanText_(d.name, 60);
    const group = String(d.group || '').toUpperCase();
    const base = String(d.baseUnit || '').toLowerCase();
    const pUnit = cleanText_(d.purchaseUnit, 20) || base;
    const ptb = Number(d.purchaseToBase);
    const minStock = Number(d.minStock || 0);
    const supplierId = String(d.supplierId || '').trim();
    if (!name) throw new Error('Nama bahan wajib diisi.');
    if (INGREDIENT_GROUPS.indexOf(group) < 0) throw new Error('Pilih grup: Makanan, Minuman atau Bersama.');
    if (acc.edit.indexOf(group) < 0) throw jayaError_('Akses ditolak. Role Anda tidak boleh mengelola bahan ' + groupWord_(group) + '.', 'DENIED');
    if (BASE_UNITS.indexOf(base) < 0) throw new Error('Satuan dasar harus g, ml, pcs atau portion.');
    if (!isFinite(ptb) || ptb <= 0 || ptb > 1000000) throw new Error('"Isi per satuan beli" harus angka di atas 0 (contoh 1000 untuk kg → g).');
    if (!isFinite(minStock) || minStock < 0) throw new Error('Stok minimum harus 0 atau lebih.');
    if (supplierId && !suppliersList_().some(function (s) { return s.id === supplierId; })) throw new Error('Supplier tidak ditemukan.');

    return withLock_(function () {
      const list = ingredientsList_();
      if (list.some(function (i) { return i.name.toLowerCase() === name.toLowerCase() && i.id !== String(d.id || ''); })) {
        throw new Error('Bahan bernama "' + name + '" sudah ada.');
      }
      const fields = { Ingredient_Name: name, Ingredient_Group: group, Base_Unit: base, Purchase_Unit: pUnit, Purchase_To_Base: ptb,
                       Min_Stock_Base: minStock, Default_Supplier_ID: supplierId, Active_Status: d.active !== false, Updated_At: nowStamp_() };
      let id = String(d.id || '');
      if (id) {
        const old = list.filter(function (i) { return i.id === id; })[0];
        if (!old) throw new Error('Bahan tidak ditemukan.');
        if (acc.edit.indexOf(old.group) < 0) throw jayaError_('Akses ditolak. Role Anda tidak boleh mengubah bahan ' + groupWord_(old.group) + '.', 'DENIED');
        if (old.baseUnit !== base) {
          const used = readTable_('Recipe_Details').rows.some(function (r) { return String(r.Ingredient_ID).trim() === id; });
          if (used || old.stock !== 0) throw new Error('Satuan dasar tidak bisa diubah selama bahan masih punya stok atau dipakai di resep.');
        }
        updateRow_('Ingredients', old.row, fields);
        audit_(user, 'INGREDIENT_UPDATE', 'Ingredient', id, { before: { name: old.name, group: old.group, base: old.baseUnit, purchaseUnit: old.purchaseUnit, purchaseToBase: old.purchaseToBase }, after: { name: name, group: group, base: base, purchaseUnit: pUnit, purchaseToBase: ptb } });
      } else {
        id = nextId_(list.map(function (i) { return i.id; }), 'I', 3);
        fields.Ingredient_ID = id;
        fields.Cost_Per_Base_Unit = 0;
        fields.Last_Purchase_Price = 0;
        fields.Stock_Qty_Base = 0;
        appendObjects_('Ingredients', [fields]);
        audit_(user, 'INGREDIENT_CREATE', 'Ingredient', id, { name: name, group: group, base: base });
      }
      clearRecipeCache_();
      return { id: id };
    });
  });
}

// ---------------- Recipes API ----------------

function apiGetRecipes(token, group) {
  return run_(function () {
    const user = requireSession_(token);
    group = String(group || '').toUpperCase();
    if (group !== 'FOOD' && group !== 'BEVERAGE') throw new Error('Grup resep tidak dikenal.');
    if (!canRecipe_(user, group, 'view')) throw jayaError_('Akses ditolak. Role Anda tidak boleh melihat resep ' + groupWord_(group) + '.', 'DENIED');
    const data = recipeData_();
    const products = readTable_('Products').rows.filter(function (r) {
      return String(r.Recipe_Group || '').trim().toUpperCase() === group && isTrue_(r.Active) && String(r.Product_ID).trim();
    }).map(function (r) {
      const id = String(r.Product_ID).trim();
      const price = moneyNum_(r.Selling_Price) || 0;
      const rc = data.recipes[id] || null;
      const cost = rc ? rc.perServing : (moneyNum_(r.Cost) || 0);
      return {
        id: id, name: String(r.Product_Name).trim(), category: String(r.Category).trim(), price: price,
        recipe: rc ? { recipeId: rc.recipeId, yieldQty: rc.yieldQty, notes: rc.notes, lines: rc.lines, totalCost: rc.totalCost,
                       perServing: rc.perServing, problems: rc.problems, updatedAt: rc.updatedAt, updatedBy: rc.updatedBy } : null,
        cost: cost, costPct: price > 0 ? Math.round(cost / price * 1000) / 10 : null
      };
    });
    const ingredients = Object.keys(data.ingredients).map(function (k) { return data.ingredients[k]; })
      .filter(function (i) { return i.active && (i.group === group || i.group === 'SHARED'); })
      .sort(function (a, b) { return a.name.localeCompare(b.name); })
      .map(function (i) { return { id: i.id, name: i.name, baseUnit: i.baseUnit, cost: round4_(i.cost), group: i.group }; });
    return { group: group, canEdit: canRecipe_(user, group, 'edit'), products: products, ingredients: ingredients, units: publicUnits_() };
  });
}

function apiSaveRecipe(token, d) {
  return run_(function () {
    const user = requireSession_(token);
    d = d || {};
    const prod = readTable_('Products').rows.filter(function (r) { return String(r.Product_ID).trim() === String(d.productId || ''); })[0];
    if (!prod) throw new Error('Produk tidak ditemukan.');
    const group = String(prod.Recipe_Group || '').trim().toUpperCase();
    if (!canRecipe_(user, group, 'edit')) throw jayaError_('Akses ditolak. Role Anda tidak boleh mengubah resep ' + (groupWord_(group) || 'ini') + '.', 'DENIED');
    const yieldQty = Number(d.yieldQty);
    if (!isFinite(yieldQty) || yieldQty <= 0 || yieldQty > 1000) throw new Error('Hasil (jumlah porsi) harus angka di atas 0.');
    if (!Array.isArray(d.lines) || !d.lines.length) throw new Error('Tambahkan minimal satu bahan.');
    if (d.lines.length > 60) throw new Error('Bahan terlalu banyak (maks. 60).');
    const ings = {};
    ingredientsList_().forEach(function (i) { ings[i.id] = i; });
    const seen = {};
    const lines = d.lines.map(function (l, idx) {
      const ing = ings[String(l && l.ingredientId || '')];
      if (!ing || !ing.active) throw new Error('Baris ' + (idx + 1) + ': pilih bahan.');
      if (!hasPerm_(user.role, '*') && ing.group !== group && ing.group !== 'SHARED') {
        throw new Error(ing.name + ' adalah bahan ' + groupWord_(ing.group) + ' dan tidak bisa dipakai di resep ' + groupWord_(group) + '.');
      }
      if (seen[ing.id]) throw new Error(ing.name + ' muncul dua kali. Tulis jumlah totalnya di satu baris.');
      seen[ing.id] = true;
      const qty = Number(l.qty);
      if (!isFinite(qty) || qty <= 0 || qty > 1000000) throw new Error(ing.name + ': jumlah harus di atas 0.');
      const unit = String(l.unit || '').toLowerCase();
      convertQty_(qty, unit, ing.baseUnit);   // throws for impossible conversions (e.g. g -> ml)
      const unitCost = ing.cost * UNITS[unit].factor;
      return { ing: ing, qty: qty, unit: unit, unitCost: round4_(unitCost), cost: Math.round(qty * unitCost) };
    });
    const notes = cleanText_(d.notes, 300);

    return withLock_(function () {
      const data = recipeData_();
      const existing = data.recipes[String(d.productId)];
      const stamp = nowStamp_();
      let recipeId;
      const fields = { Product_ID: String(d.productId), Recipe_Name: String(prod.Product_Name), Recipe_Group: group,
                       Yield_Quantity: yieldQty, Yield_Unit: 'portion', Active_Status: true, Updated_At: stamp,
                       Updated_By: user.name, Notes: notes };
      if (existing) {
        recipeId = existing.recipeId;
        updateRow_('Recipes', existing.row, fields);
        deleteRowsWhere_('Recipe_Details', 'Recipe_ID', recipeId);
      } else {
        recipeId = nextId_(readTable_('Recipes').rows.map(function (r) { return r.Recipe_ID; }), 'R', 3);
        fields.Recipe_ID = recipeId;
        appendObjects_('Recipes', [fields]);
      }
      appendObjects_('Recipe_Details', lines.map(function (l, i) {
        return { Recipe_ID: recipeId, Ingredient_ID: l.ing.id, Quantity_Required: l.qty, Unit: l.unit,
                 Cost_Per_Unit: l.unitCost, Ingredient_Cost: l.cost, Line_No: i + 1 };
      }));
      const fresh = recipeData_();
      refreshProductCosts_(fresh);
      const rc = fresh.recipes[String(d.productId)];
      audit_(user, existing ? 'RECIPE_UPDATE' : 'RECIPE_CREATE', 'Recipe', recipeId, {
        product: String(prod.Product_Name), yield: yieldQty, perServing: rc ? rc.perServing : 0,
        before: existing ? existing.lines.map(function (l) { return l.name + ' ' + l.qty + l.unit; }) : [],
        after: lines.map(function (l) { return l.ing.name + ' ' + l.qty + l.unit; })
      });
      return { recipeId: recipeId, perServing: rc ? rc.perServing : 0 };
    });
  });
}

function apiDeleteRecipe(token, productId) {
  return run_(function () {
    const user = requireSession_(token);
    return withLock_(function () {
      const data = recipeData_();
      const rc = data.recipes[String(productId)];
      if (!rc) throw new Error('Produk ini belum punya resep.');
      const prod = readTable_('Products').rows.filter(function (r) { return String(r.Product_ID).trim() === String(productId); })[0];
      const group = prod ? String(prod.Recipe_Group || '').trim().toUpperCase() : '';
      if (!canRecipe_(user, group, 'edit')) throw jayaError_('Akses ditolak.', 'DENIED');
      updateRow_('Recipes', rc.row, { Active_Status: false, Updated_At: nowStamp_(), Updated_By: user.name });
      clearRecipeCache_();
      audit_(user, 'RECIPE_DELETE', 'Recipe', rc.recipeId, { product: prod ? String(prod.Product_Name) : productId });
      return true;
    });
  });
}

// ---------------- Stock API ----------------

/** Reads only the last part of a long sheet (newest rows). */
function readRecentRows_(name, maxRows) {
  const sh = getSheet_(name);
  const headers = getHeaders_(sh);
  const lastRow = sh.getLastRow();
  if (lastRow < 2) return [];
  const start = Math.max(2, lastRow - maxRows + 1);
  return sh.getRange(start, 1, lastRow - start + 1, headers.length).getValues().map(function (r, i) {
    const o = { _row: start + i };
    headers.forEach(function (h, j) { if (h) o[h] = r[j]; });
    return o;
  });
}

function apiGetStock(token, group) {
  return run_(function () {
    const user = requireSession_(token);
    group = String(group || 'ALL').toUpperCase();
    const groups = group === 'ALL' ? INGREDIENT_GROUPS : [group, 'SHARED'];
    if (group === 'ALL' ? !(hasPerm_(user.role, '*') || hasPerm_(user.role, 'inventory.view')) : !canStock_(user, group, 'view')) {
      throw jayaError_('Akses ditolak. Role Anda tidak boleh melihat stok ini.', 'DENIED');
    }
    const list = ingredientsList_().filter(function (i) { return i.active && groups.indexOf(i.group) >= 0; });
    const ids = {};
    list.forEach(function (i) { ids[i.id] = true; });
    const movements = readRecentRows_('Inventory_Movements', 1500)
      .filter(function (m) { return ids[String(m.Ingredient_ID).trim()]; })
      .reverse().slice(0, 60)
      .map(function (m) {
        return { id: String(m.Movement_ID), when: cellText_(m.Timestamp), ingredient: String(m.Ingredient_Name || m.Ingredient_ID),
                 type: String(m.Movement_Type), qtyBase: numOr_(m.Quantity_Base, 0), unit: String(m.Unit || ''),
                 cost: moneyNum_(m.Total_Cost) || 0, ref: String(m.Reference_ID || ''), notes: String(m.Notes || '') };
      });
    return {
      group: group,
      ingredients: list.sort(function (a, b) { return a.name.localeCompare(b.name); }).map(function (i) {
        return { id: i.id, name: i.name, group: i.group, baseUnit: i.baseUnit, stock: i.stock, minStock: i.minStock,
                 cost: round4_(i.cost), value: Math.round(Math.max(0, i.stock) * i.cost), purchaseUnit: i.purchaseUnit,
                 purchaseToBase: i.purchaseToBase, low: i.minStock > 0 && i.stock < i.minStock,
                 canWaste: canStock_(user, i.group, 'waste') };
      }),
      movements: movements,
      canAdjust: hasPerm_(user.role, '*'),
      units: publicUnits_()
    };
  });
}

function apiRecordWaste(token, d) {
  return run_(function () {
    const user = requireSession_(token);
    d = d || {};
    return withLock_(function () {
      const ing = ingredientsList_().filter(function (i) { return i.id === String(d.ingredientId || ''); })[0];
      if (!ing) throw new Error('Bahan tidak ditemukan.');
      if (!canStock_(user, ing.group, 'waste')) throw jayaError_('Akses ditolak. Role Anda tidak boleh mencatat waste bahan ' + groupWord_(ing.group) + '.', 'DENIED');
      const qty = Number(d.qty);
      if (!isFinite(qty) || qty <= 0 || qty > 1000000) throw new Error('Jumlah harus di atas 0.');
      const unit = String(d.unit || ing.baseUnit).toLowerCase();
      const base = convertQty_(qty, unit, ing.baseUnit);
      const reason = cleanText_(d.reason, 120);
      if (!reason) throw new Error('Tulis alasan singkat (contoh: basi, jatuh, makan staf).');
      applyMovements_([{ ing: ing, type: 'WASTE', qty: -qty, unit: unit, baseQty: -base, unitCost: ing.cost, notes: reason }], user, {});
      audit_(user, 'STOCK_WASTE', 'Ingredient', ing.id, { name: ing.name, qty: qty, unit: unit, reason: reason, cost: Math.round(base * ing.cost) });
      return true;
    });
  });
}

/** Admin: set the counted stock (and optionally the cost) of an ingredient. */
function apiAdjustStock(token, d) {
  return run_(function () {
    const user = requirePerm_(token, 'inventory.adjust');
    d = d || {};
    return withLock_(function () {
      const ing = ingredientsList_().filter(function (i) { return i.id === String(d.ingredientId || ''); })[0];
      if (!ing) throw new Error('Bahan tidak ditemukan.');
      const counted = Number(d.countedQty);
      if (!isFinite(counted) || counted < 0 || counted > 100000000) throw new Error('Stok hasil hitung harus 0 atau lebih (dalam ' + ing.baseUnit + ').');
      const costUpdates = {};
      let cost = ing.cost;
      if (d.costPerPurchaseUnit !== null && d.costPerPurchaseUnit !== undefined && d.costPerPurchaseUnit !== '') {
        const cpu = Number(d.costPerPurchaseUnit);
        if (!isFinite(cpu) || cpu < 0) throw new Error('Harga pokok harus 0 atau lebih.');
        cost = cpu / ing.purchaseToBase;
        costUpdates[ing.id] = { cost: cost };
      }
      const delta = round4_(counted - ing.stock);
      const reason = cleanText_(d.reason, 120) || 'Stock opname';
      const type = ing.stock === 0 && ing.cost === 0 ? 'OPENING' : 'ADJUST';
      const moves = delta !== 0 ? [{ ing: ing, type: type, qty: delta, unit: ing.baseUnit, baseQty: delta, unitCost: cost, notes: reason }] : [];
      applyMovements_(moves, user, costUpdates);
      if (costUpdates[ing.id]) refreshProductCosts_();
      audit_(user, 'STOCK_ADJUST', 'Ingredient', ing.id, { name: ing.name, from: ing.stock, to: counted, costPerBase: round4_(cost), reason: reason });
      return true;
    });
  });
}

/**
 * Kitchen.gs
 * Kitchen and bar screens ("Layar Dapur" / "Layar Bar").
 *
 * A ticket is written to the Kitchen_Tickets sheet:
 *  - every time new items are saved on a table (one ticket per round: "Pesanan 2"),
 *  - when a takeaway order is paid,
 *  - when saved items are voided or a bill is voided (Kind VOID, shown in red as "BATAL").
 * Food (Recipe_Group FOOD) goes to the kitchen screen; drinks (BEVERAGE) and others (NONE) go to the bar.
 * Each station marks its part of the ticket "Selesai" independently.
 */

function stationOf_(grp) { return String(grp || '').toUpperCase() === 'FOOD' ? 'FOOD' : 'BAR'; }

/**
 * Writes one ticket. Never blocks the order that called it.
 * info: { orderId, tableName, guest, round, kind: 'ORDER' | 'VOID', reason, user }
 * lines: [{ id, name, qty, note, grp }]
 */
function createTicket_(info, lines, products) {
  try {
    if (!lines || !lines.length) return '';
    const items = lines.map(function (l) {
      let grp = l.grp;
      if (!grp) {
        products = products || productMap_();
        grp = products[l.id] ? products[l.id].recipeGroup : 'NONE';
      }
      return { name: String(l.name), qty: Number(l.qty) || 0, note: String(l.note || ''), st: stationOf_(grp),
               round: Number(l.round) || 0 };
    });
    const hasFood = items.some(function (i) { return i.st === 'FOOD'; });
    const hasBar = items.some(function (i) { return i.st === 'BAR'; });
    const now = new Date();
    const dateKey = fmt_(now, 'yyyyMMdd');
    const id = 'KT-' + dateKey + '-' + String(nextSeq_('KTSEQ_' + dateKey, 1) + 1).padStart(4, '0');
    appendObjects_('Kitchen_Tickets', [{
      Ticket_ID: id, Date: fmt_(now, 'yyyy-MM-dd'), Created_At: fmt_(now, 'yyyy-MM-dd HH:mm:ss'), Created_Ms: now.getTime(),
      Created_By: info.user ? info.user.name : '', Order_ID: info.orderId || '', Table_Name: info.tableName || '',
      Guest_Name: info.guest || '', Round: info.round || 0, Kind: info.kind || 'ORDER',
      Items_JSON: JSON.stringify({ items: items, reason: info.reason || '' }),
      Food_Status: hasFood ? 'NEW' : '', Food_Done_At: '', Bar_Status: hasBar ? 'NEW' : '', Bar_Done_At: ''
    }]);
    return id;
  } catch (e) {
    console.error('createTicket_ failed: ' + e);
    return '';
  }
}

function stationPerm_(station) {
  if (station === 'FOOD') return 'kitchen.food';
  if (station === 'BAR') return 'kitchen.bar';
  throw new Error('Layar tidak dikenal.');
}

function ticketFromRow_(r, station) {
  let data = { items: [], reason: '' };
  try { data = JSON.parse(String(r.Items_JSON || '{}')) || data; } catch (e) { /* broken cell */ }
  const statusCol = station === 'FOOD' ? 'Food_Status' : 'Bar_Status';
  const doneCol = station === 'FOOD' ? 'Food_Done_At' : 'Bar_Done_At';
  const created = cellText_(r.Created_At);
  return {
    row: r._row, id: String(r.Ticket_ID), orderId: String(r.Order_ID || ''), table: String(r.Table_Name || ''),
    guest: String(r.Guest_Name || ''), round: Number(r.Round) || 0, kind: String(r.Kind || 'ORDER'),
    createdMs: Number(r.Created_Ms) || 0, time: created.slice(11, 16), date: dateText_(r.Date), by: String(r.Created_By || ''),
    items: (data.items || []).filter(function (i) { return i.st === station; }),
    reason: String(data.reason || ''),
    status: String(r[statusCol] || ''), doneAt: cellText_(r[doneCol]).slice(11, 16)
  };
}

/** Open tickets for one station (oldest first) plus the last finished ones. */
function apiGetKitchen(token, station) {
  return run_(function () {
    station = String(station || '').toUpperCase();
    requirePerm_(token, stationPerm_(station));
    const today = todayStr_();
    const yesterday = addDays_(today, -1);
    const all = readRecentRows_('Kitchen_Tickets', 400).map(function (r) { return ticketFromRow_(r, station); })
      .filter(function (t) { return t.id && t.status && t.items.length && t.date >= yesterday; });
    const open = all.filter(function (t) { return t.status === 'NEW'; });
    const done = all.filter(function (t) { return t.status === 'DONE' && t.date === today; }).reverse().slice(0, 30);
    const strip = function (t) { delete t.row; return t; };
    return { station: station, serverNow: Date.now(), open: open.map(strip), done: done.map(strip) };
  });
}

/** Marks this station's part of a ticket as done (or back to open with undo = true). */
function apiKitchenDone(token, ticketId, station, undo) {
  return run_(function () {
    station = String(station || '').toUpperCase();
    const user = requirePerm_(token, stationPerm_(station));
    return withLock_(function () {
      const rows = rowsWhere_('Kitchen_Tickets', 'Ticket_ID', String(ticketId || ''));
      if (!rows.length) throw new Error('Tiket tidak ditemukan. Muat ulang layar.');
      const r = rows[0];
      const statusCol = station === 'FOOD' ? 'Food_Status' : 'Bar_Status';
      const doneCol = station === 'FOOD' ? 'Food_Done_At' : 'Bar_Done_At';
      if (!String(r[statusCol] || '')) throw new Error('Tiket ini tidak punya item untuk layar ini.');
      const fields = {};
      fields[statusCol] = undo ? 'NEW' : 'DONE';
      fields[doneCol] = undo ? '' : nowStamp_();
      updateRow_('Kitchen_Tickets', r._row, fields);
      if (undo) audit_(user, 'KITCHEN_UNDO', 'Ticket', String(ticketId), { station: station });
      return true;
    });
  });
}

/**
 * Pos.gs
 * Menu for the cashier, totals (item discount, bill discount, service, PB1, cash rounding),
 * split payments and saving a completed order.
 *
 * How the total is calculated (the phone shows the same numbers, the server checks them):
 *   line gross     = price x qty
 *   item discount  = % of the line, or a Rupiah amount for the whole line
 *   items net      = sum of (line gross - item discount)
 *   bill discount  = % of items net, or a Rupiah amount
 *   base           = items net - bill discount
 *   service        = base x Service_Percent         (if ticked)
 *   tax (PB1)      = (base + service) x Tax_Percent (if ticked)
 *   payment parts  = 1 part normally; "bagi rata" N = N equal parts (the last part takes the leftover Rupiah)
 *   rounding       = per part, only for CASH parts: rounded to Cash_Rounding (e.g. 1000)
 *   grand total    = base + service + tax + rounding of all parts
 *
 * Order lines: every line has its own id (lid) and an optional note for the kitchen ("Pedas", "Es pisah").
 * The same product can appear on several lines (different notes, or ordered in a later round).
 *
 * Safety rules in apiCompleteOrder:
 *  - Prices come from the Products sheet, never from the phone.
 *  - Discounts, service, tax and rounding are recalculated on the server.
 *  - If the total on the phone differs from the server's total, the order is refused.
 *  - A table bill is paid from the lines SAVED on the bill (the phone only says which lines / how many).
 *  - A lock makes sure two phones never get the same transaction number.
 *  - Each order carries a unique reference from the phone. If the same order is
 *    sent twice (e.g. internet dropped and cashier pressed again), it is saved ONCE.
 *  - When Require_Shift is TRUE, money can only be taken while a cash shift is open.
 */

/** Turns a Google Drive share link or file ID into a picture link that works in <img>. */
function normalizeImageUrl_(v) {
  const s = String(v == null ? '' : v).trim();
  if (!s) return '';
  let m = s.match(/\/file\/d\/([A-Za-z0-9_-]{20,})/) || s.match(/[?&]id=([A-Za-z0-9_-]{20,})/);
  if (m) return 'https://drive.google.com/thumbnail?id=' + m[1] + '&sz=w600';
  if (/^[A-Za-z0-9_-]{25,}$/.test(s)) return 'https://drive.google.com/thumbnail?id=' + s + '&sz=w600';
  if (/^https:\/\//i.test(s)) return s;
  return '';
}

function getActiveProducts_() {
  return readTable_('Products').rows.map(function (r) {
    const cost = moneyNum_(r.Cost);
    return {
      id: String(r.Product_ID).trim(),
      name: String(r.Product_Name).trim(),
      category: String(r.Category).trim() || 'Other',
      price: moneyNum_(r.Selling_Price),
      cost: isFinite(cost) ? cost : 0,
      active: isTrue_(r.Active),
      recipeGroup: String(r.Recipe_Group || '').trim().toUpperCase() || 'NONE',
      image: normalizeImageUrl_(r.Image_URL)
    };
  }).filter(function (p) { return p.active && p.id && p.name && isFinite(p.price) && p.price >= 0; });
}

function productMap_() {
  const m = {};
  getActiveProducts_().forEach(function (p) { m[p.id] = p; });
  return m;
}

function categoryOrder_() { return listSetting_('Category_Order'); }

function chargeSettings_() {
  const s = getSettingsMap_();
  const mode = String(s.Cash_Rounding_Mode || 'NEAREST').toUpperCase();
  return {
    servicePct: Math.max(0, Math.min(50, numOr_(s.Service_Percent, 0))),
    serviceLabel: s.Service_Label || 'Service',
    serviceOnTakeaway: isTrue_(s.Service_On_Takeaway),
    taxPct: Math.max(0, Math.min(50, numOr_(s.Tax_Percent, 0))),
    taxLabel: s.Tax_Label || 'PB1',
    taxOnTakeaway: String(s.Tax_On_Takeaway == null ? '' : s.Tax_On_Takeaway).trim() === '' ? true : isTrue_(s.Tax_On_Takeaway),
    cashRounding: Math.max(0, Math.round(numOr_(s.Cash_Rounding, 0))),
    roundingMode: ['NEAREST', 'DOWN', 'UP'].indexOf(mode) >= 0 ? mode : 'NEAREST'
  };
}

/** A discount from the phone: { type: 'PCT' | 'AMT', value }. Returns null for "no discount". */
function readDiscount_(d, what) {
  if (!d || typeof d !== 'object') return null;
  const type = String(d.type || '').toUpperCase();
  const value = Number(d.value);
  if (!value) return null;
  if (type === 'PCT') {
    if (!isFinite(value) || value <= 0 || value > 100) throw new Error('Diskon ' + what + ' dalam % harus antara 0 dan 100.');
    return { type: 'PCT', value: Math.round(value * 100) / 100 };
  }
  if (type === 'AMT') {
    if (!Number.isInteger(value) || value <= 0) throw new Error('Diskon ' + what + ' dalam Rupiah harus angka bulat.');
    return { type: 'AMT', value: value };
  }
  throw new Error('Jenis diskon ' + what + ' tidak dikenal.');
}

function discountAmount_(disc, base) {
  if (!disc) return 0;
  return disc.type === 'PCT' ? Math.round(base * disc.value / 100) : disc.value;
}

function discountInfo_(disc) {
  if (!disc) return '';
  return disc.type === 'PCT' ? String(disc.value).replace('.', ',') + '%' : 'Rp ' + disc.value;
}

/** Rounds a cash total to the Cash_Rounding step. Returns the rounding amount (+ or -). */
function cashRounding_(amount, ch) {
  if (!ch.cashRounding) return 0;
  const step = ch.cashRounding;
  let r;
  if (ch.roundingMode === 'DOWN') r = Math.floor(amount / step) * step;
  else if (ch.roundingMode === 'UP') r = Math.ceil(amount / step) * step;
  else r = Math.round(amount / step) * step;
  return r - amount;
}

/** Splits an amount into parts (one per payment method). Cash parts are rounded one by one. */
function splitParts_(before, methods, ch) {
  const n = methods.length;
  const each = Math.floor(before / n);
  return methods.map(function (m, i) {
    const amount = i === n - 1 ? before - each * (n - 1) : each;
    const rounding = m === 'CASH' ? cashRounding_(amount, ch) : 0;
    return { method: m, amount: amount, rounding: rounding, due: amount + rounding };
  });
}

/**
 * Full calculation of an order. lines need .total (gross) and .disc.
 * opts: { billDisc, applyService, applyTax, methods: ['CASH', 'QRIS', ...] }  (old: cash: true/false)
 */
function calcTotals_(lines, opts, ch) {
  let subtotal = 0, itemDiscount = 0;
  lines.forEach(function (l) {
    l.discount = Math.min(l.total, discountAmount_(l.disc, l.total));
    l.netTotal = l.total - l.discount;
    subtotal += l.total;
    itemDiscount += l.discount;
  });
  const itemsNet = subtotal - itemDiscount;
  const billDiscount = Math.min(itemsNet, discountAmount_(opts.billDisc, itemsNet));
  const base = itemsNet - billDiscount;
  const service = opts.applyService && ch.servicePct > 0 ? Math.round(base * ch.servicePct / 100) : 0;
  const tax = opts.applyTax && ch.taxPct > 0 ? Math.round((base + service) * ch.taxPct / 100) : 0;
  const beforeRounding = base + service + tax;
  const methods = opts.methods && opts.methods.length ? opts.methods : [opts.cash ? 'CASH' : 'OTHER'];
  const parts = splitParts_(beforeRounding, methods, ch);
  const rounding = parts.reduce(function (s, p) { return s + p.rounding; }, 0);
  return {
    subtotal: subtotal, itemDiscount: itemDiscount, itemsNet: itemsNet, billDiscount: billDiscount,
    discount: itemDiscount + billDiscount, base: base, service: service, tax: tax,
    beforeRounding: beforeRounding, rounding: rounding, grand: beforeRounding + rounding, parts: parts
  };
}

function cleanNote_(v) { return cleanText_(v, 100); }
function cleanLid_(v) {
  const s = String(v == null ? '' : v).trim();
  return /^[A-Za-z0-9_-]{2,24}$/.test(s) ? s : '';
}
function cleanGuest_(v) { return cleanText_(v, 40); }

/**
 * Validates order lines from the phone: [{ lid, productId, qty, disc, note }].
 * Lines are NOT merged: the same product may appear twice (e.g. one "pedas", one "tidak pedas").
 */
function parseLines_(items, allowEmpty) {
  if (!Array.isArray(items)) throw new Error('Data pesanan tidak lengkap.');
  if (!items.length && !allowEmpty) throw new Error('Keranjang masih kosong.');
  if (items.length > 150) throw new Error('Terlalu banyak baris dalam satu pesanan (maks. 150).');
  return items.map(function (it) {
    const id = String((it && it.productId) || '').trim();
    const q = Number(it && it.qty);
    if (!id) throw new Error('Ada item tanpa produk di keranjang.');
    if (!Number.isInteger(q) || q < 1 || q > 999) throw new Error('Jumlah item tidak valid (harus 1 sampai 999).');
    return { lid: cleanLid_(it.lid), productId: id, qty: q, disc: readDiscount_(it.disc, 'item'), note: cleanNote_(it.note) };
  });
}

/**
 * Prices each line with the CURRENT Products sheet price.
 * fallback (optional): { lid: storedLine } — lines already saved on a table keep their saved
 * name / price if the product was switched off later, so the bill can still be paid.
 */
function priceLines_(parsed, fallback, products) {
  products = products || productMap_();
  return parsed.map(function (l) {
    const p = products[l.productId];
    const old = fallback && l.lid ? fallback[l.lid] : null;
    if (!p && !old) throw jayaError_('Ada produk di keranjang yang sudah tidak tersedia (' + l.productId + '). Menu akan dimuat ulang.', 'PRICE_CHANGED');
    const price = p ? p.price : Number(old.price) || 0;
    const total = price * l.qty;
    const name = p ? p.name : old.name;
    if (l.disc && l.disc.type === 'AMT' && l.disc.value > total) throw new Error('Diskon untuk ' + name + ' lebih besar dari harganya.');
    return { lid: l.lid, productId: l.productId, name: name, category: p ? p.category : 'Other', qty: l.qty, price: price,
             cost: p ? p.cost : 0, total: total, disc: l.disc, note: l.note || '', group: p ? p.recipeGroup : (old.grp || 'NONE') };
  });
}

/** Cashiers may give at most Max_Discount_Percent of the order (admin: no limit). */
function checkDiscountAllowed_(user, tot, lines, billDisc) {
  const settings = getSettingsMap_();
  const isAdmin = hasPerm_(user.role, '*');
  const any = tot.discount > 0;
  if (any && !isAdmin && !isTrue_(settings.Allow_Discount)) throw new Error('Diskon dimatikan untuk kasir. Minta admin.');
  if (billDisc && billDisc.type === 'AMT' && billDisc.value > tot.itemsNet) throw new Error('Diskon bill lebih besar dari subtotal.');
  if (!any || isAdmin) return;
  const maxPct = Math.max(0, Math.min(100, numOr_(settings.Max_Discount_Percent, 100)));
  if (maxPct < 100 && tot.subtotal > 0 && tot.discount / tot.subtotal * 100 > maxPct + 1e-9) {
    throw new Error('Total diskon melebihi batas kasir (' + maxPct + '%). Minta admin.');
  }
}

function apiGetPosData(token) {
  return run_(function () {
    const user = requirePerm_(token, ['pos.sell', 'pos.order']);
    const s = getSettingsMap_();
    const isAdmin = hasPerm_(user.role, '*');
    const canPay = hasPerm_(user.role, 'pos.sell');
    let shiftOpen = false;
    try { shiftOpen = !!currentShift_(); } catch (e) { shiftOpen = false; }
    return {
      products: getActiveProducts_().map(function (p) {
        return { id: p.id, name: p.name, category: p.category, price: p.price, image: p.image, group: p.recipeGroup }; // cost is NOT sent
      }),
      categories: categoryOrder_(),
      allowDiscount: (isTrue_(s.Allow_Discount) || isAdmin) && canPay,
      maxDiscountPct: isAdmin ? 100 : Math.max(0, Math.min(100, numOr_(s.Max_Discount_Percent, 100))),
      showImages: isTrue_(s.Show_Product_Images),
      quickNotes: listSetting_('Quick_Notes').slice(0, 20),
      canPay: canPay,
      shift: { required: isTrue_(s.Require_Shift), open: shiftOpen, canManage: hasPerm_(user.role, 'shift.manage') },
      charges: chargeSettings_()
    };
  });
}

/** Payment parts from the phone: [{ method, amountPaid }]. Old phones send paymentMethod / amountPaid. */
function readPayments_(order) {
  let list = Array.isArray(order.payments) && order.payments.length ? order.payments
    : [{ method: order.paymentMethod, amountPaid: order.amountPaid }];
  if (list.length > 20) throw new Error('Bagi rata maksimal 20 bagian.');
  return list.map(function (p) {
    const m = String((p && p.method) || '');
    if (!PAYMENT_METHODS[m]) throw new Error('Pilih metode pembayaran' + (list.length > 1 ? ' untuk setiap bagian.' : '.'));
    return { method: m, amountPaid: p.amountPaid };
  });
}

/**
 * Lines of a table bill that are being paid now.
 * payLines: null = everything still on the bill, or [{ lid, qty }] for "split per item".
 * Returns { pay: [...], rest: [...] } — both in the stored line format.
 */
function pickPayLines_(stored, payLines) {
  if (!payLines) return { pay: stored.map(function (l) { return Object.assign({}, l); }), rest: [] };
  if (!Array.isArray(payLines) || !payLines.length) throw new Error('Pilih item yang mau dibayar.');
  const want = {};
  payLines.forEach(function (p) {
    const lid = cleanLid_(p && p.lid);
    const q = Number(p && p.qty);
    if (!lid || !Number.isInteger(q) || q < 0 || q > 999) throw new Error('Pilihan split bill tidak valid.');
    if (q > 0) want[lid] = (want[lid] || 0) + q;
  });
  const pay = [], rest = [];
  stored.forEach(function (l) {
    const q = want[l.lid] || 0;
    delete want[l.lid];
    if (q > l.qty) throw jayaError_('Jumlah ' + l.name + ' yang mau dibayar lebih banyak dari yang ada di bill. Bill sudah dimuat ulang.', 'STALE');
    if (!q) { rest.push(Object.assign({}, l)); return; }
    let payDisc = l.disc || null, restDisc = l.disc || null;
    if (l.disc && l.disc.type === 'AMT' && q < l.qty) {        // a Rupiah discount is shared by quantity
      const part = Math.round(l.disc.value * q / l.qty);
      payDisc = part > 0 ? { type: 'AMT', value: part } : null;
      restDisc = l.disc.value - part > 0 ? { type: 'AMT', value: l.disc.value - part } : null;
    }
    pay.push(Object.assign({}, l, { qty: q, disc: payDisc }));
    if (q < l.qty) rest.push(Object.assign({}, l, { qty: l.qty - q, disc: restDisc }));
  });
  if (Object.keys(want).length) throw jayaError_('Ada item yang sudah tidak ada di bill. Bill sudah dimuat ulang.', 'STALE');
  if (!pay.length) throw new Error('Pilih item yang mau dibayar.');
  return { pay: pay, rest: rest };
}

function apiCompleteOrder(token, order) {
  return run_(function () {
    const user = requirePerm_(token, 'pos.sell');
    const settings = getSettingsMap_();
    if (!order || typeof order !== 'object') throw new Error('Data pesanan tidak ada.');

    const clientRef = String(order.clientRef || '');
    if (!/^[A-Za-z0-9-]{10,64}$/.test(clientRef)) throw new Error('Referensi pesanan tidak valid. Muat ulang JayaPOS.');

    const payments = readPayments_(order);
    const methods = payments.map(function (p) { return p.method; });
    const openOrderId = String(order.openOrderId || '');
    const products = productMap_();
    const takeawayLines = openOrderId ? null : priceLines_(parseLines_(order.items, false), null, products);
    const ch = chargeSettings_();
    const billDisc = readDiscount_(order.billDiscount, 'bill');

    // COGS per serving from recipes (falls back to Products.Cost when a product has no recipe)
    let rdata = { recipes: {}, ingredients: {} };
    try { rdata = recipeDataCached_(); } catch (e) { console.error('recipe data: ' + e); }

    return withLock_(function () {
      const existingId = findTxIdByClientRef_(clientRef);
      if (existingId) {
        const r = buildReceipt_(existingId, settings);
        r.alreadySaved = true;
        return r;
      }

      const shift = shiftForPayment_(settings);

      let bill = null, lines, picked = null;
      if (openOrderId) {
        bill = getOpenOrder_(openOrderId);
        if (!bill) throw new Error('Bill meja ini tidak ditemukan. Kembali ke Meja dan buka lagi.');
        if (bill.status !== 'OPEN') throw jayaError_('Bill meja ini sudah ' + statusWord_(bill.status) + '.', 'STALE');
        if (bill.version !== Number(order.version)) {
          throw jayaError_('Bill ini baru diubah di HP lain (oleh ' + bill.updatedBy + '). Bill sudah dimuat ulang. Cek lagi lalu bayar.', 'STALE');
        }
        if (!bill.items.length) throw new Error('Bill ini masih kosong.');
        picked = pickPayLines_(bill.items, order.payLines || null);
        const fallback = {};
        bill.items.forEach(function (l) { fallback[l.lid] = l; });
        lines = priceLines_(picked.pay.map(function (l) {
          return { lid: l.lid, productId: l.id, qty: l.qty, disc: l.disc || null, note: l.note || '' };
        }), fallback, products);
      } else {
        lines = takeawayLines;
      }

      const tot = calcTotals_(lines, { billDisc: billDisc, applyService: order.applyService === true,
                                       applyTax: order.applyTax !== false, methods: methods }, ch);
      checkDiscountAllowed_(user, tot, lines, billDisc);

      if (order.expectedTotal !== undefined && Number(order.expectedTotal) !== tot.grand) {
        throw jayaError_('Harga atau pengaturan biaya berubah sejak menu dimuat. Menu sudah dimuat ulang. Cek totalnya lalu tekan tombol bayar lagi.', 'PRICE_CHANGED');
      }

      // money received, per part
      let paidTotal = 0, changeTotal = 0;
      tot.parts.forEach(function (part, i) {
        part.paid = part.due;
        part.change = 0;
        if (part.method === 'CASH') {
          const paid = Number(payments[i].amountPaid);
          const who = tot.parts.length > 1 ? ' (bagian ' + (i + 1) + ')' : '';
          if (!Number.isInteger(paid) || paid < 0) throw new Error('Isi jumlah uang tunai yang diterima' + who + '.');
          if (paid < part.due) throw new Error('Uang tunai kurang dari total' + who + '.');
          if (paid > part.due + 10000000) throw new Error('Jumlah uang tunai sepertinya salah' + who + '. Cek lagi.');
          part.paid = paid;
          part.change = paid - part.due;
        }
        paidTotal += part.paid;
        changeTotal += part.change;
      });
      const sameMethod = methods.every(function (m) { return m === methods[0]; });
      const method = sameMethod ? methods[0] : 'MIXED';

      lines.forEach(function (l) { if (rdata.recipes[l.productId]) l.cost = rdata.recipes[l.productId].perServing; });

      const now = new Date();
      const dateKey = fmt_(now, 'yyyyMMdd');
      const prefix = (String(settings.Tx_Prefix || 'JY').toUpperCase().replace(/[^A-Z]/g, '') || 'JY').slice(0, 5);
      const props = PropertiesService.getScriptProperties();
      const seqKey = 'TXSEQ_' + prefix + '_' + dateKey;
      let seq = Number(props.getProperty(seqKey) || 0);
      let txId;
      do {
        seq++;
        txId = prefix + '-' + dateKey + '-' + String(seq).padStart(4, '0');
      } while (getTransactionById_(txId)); // extra guard if the counter was ever reset
      props.setProperty(seqKey, String(seq));

      const priorPaid = bill ? bill.paidTx.length : 0;
      const partial = !!(picked && picked.rest.length);
      const split = [];
      if (bill && (partial || priorPaid)) split.push('Split bill ke-' + (priorPaid + 1));
      if (tot.parts.length > 1) split.push('Bagi rata ' + tot.parts.length);
      const guest = bill ? bill.guestName : cleanGuest_(order.guestName);

      const dateStr = fmt_(now, 'yyyy-MM-dd');
      const stamp = fmt_(now, 'yyyy-MM-dd HH:mm:ss');
      appendObjects_('Transaction_Details', lines.map(function (l, i) {
        return { Transaction_ID: txId, Line_No: i + 1, Product_ID: l.productId, Product_Name: l.name,
                 Category: l.category, Quantity: l.qty, Unit_Price: l.price, Total: l.total, Unit_Cost: l.cost,
                 Date: dateStr, Discount: l.discount, Discount_Info: discountInfo_(l.disc), Net_Total: l.netTotal, Note: l.note || '' };
      }));
      appendObjects_('Transactions', [{
        Transaction_ID: txId, Date: dateStr, Time: fmt_(now, 'HH:mm'), Cashier: user.name,
        Subtotal: tot.subtotal, Discount: tot.discount, Grand_Total: tot.grand, Payment_Method: method,
        Amount_Paid: paidTotal, Change: changeTotal, Status: 'COMPLETED', Cashier_ID: user.id,
        Timestamp: stamp, Client_Ref: clientRef, Outlet_ID: settings.Outlet_ID || '', Notes: '',
        Order_Type: bill ? 'DINE_IN' : 'TAKEAWAY', Table_Name: bill ? bill.tableName : '',
        Pax: bill ? (priorPaid ? 0 : bill.pax) : '',
        Service_Charge: tot.service, Tax: tot.tax, Order_ID: bill ? bill.id : '',
        Item_Discount: tot.itemDiscount, Bill_Discount: tot.billDiscount, Bill_Discount_Info: discountInfo_(billDisc),
        Rounding: tot.rounding, Void_Reason: '', Void_By: '', Void_At: '',
        Guest_Name: guest, Shift_ID: shift ? shift.id : '', Split_Info: split.join(' · '),
        Duration_Min: bill && bill.openedMs ? Math.max(0, Math.round((now.getTime() - bill.openedMs) / 60000)) : ''
      }]);
      appendObjects_('Payments', tot.parts.map(function (p, i) {
        return { Payment_ID: txId + '-' + (i + 1), Transaction_ID: txId, Seq: i + 1, Date: dateStr, Method: p.method,
                 Amount: p.due, Rounding: p.rounding, Paid: p.paid, Change: p.change, Shift_ID: shift ? shift.id : '',
                 Status: 'COMPLETED', Timestamp: stamp };
      }));

      let remaining = null;
      if (bill) {
        const paidTx = bill.paidTx.concat([txId]);
        if (picked.rest.length) {
          const restTotals = calcTotals_(picked.rest.map(function (l) { return { total: (Number(l.price) || 0) * l.qty, disc: l.disc }; }), {}, ch);
          updateRow_('Open_Orders', bill.row, {
            Items_JSON: JSON.stringify(picked.rest), Subtotal: restTotals.itemsNet, Paid_Transactions: paidTx.join(','),
            Updated_At: stamp, Updated_By: user.name, Version: bill.version + 1
          });
          remaining = publicOrder_(getOpenOrder_(bill.id));
        } else {
          updateRow_('Open_Orders', bill.row, {
            Status: 'PAID', Subtotal: 0, Transaction_ID: txId, Closed_At: stamp, Paid_Transactions: paidTx.join(','),
            Updated_At: stamp, Updated_By: user.name, Version: bill.version + 1
          });
        }
      }
      SpreadsheetApp.flush();
      CacheService.getScriptCache().put('ref_' + clientRef, txId, 21600);
      if (!bill) {
        createTicket_({ orderId: txId, tableName: 'Takeaway', guest: guest, round: 1, kind: 'ORDER', user: user },
                      lines.map(function (l) { return { id: l.productId, name: l.name, qty: l.qty, note: l.note, grp: l.group }; }), products);
      }
      try { inventoryOnSale_(txId, lines, user, rdata); }
      catch (e) { audit_(user, 'INVENTORY_ERROR', 'Transaction', txId, String(e && e.message || e)); }
      if (order.applyTax === false && ch.taxPct > 0) {
        audit_(user, 'TAX_REMOVED', 'Transaction', txId, { total: tot.grand });
      }
      if (split.length) audit_(user, 'SPLIT_BILL', 'Transaction', txId, { order: bill ? bill.id : '', info: split.join(' · '), total: tot.grand });

      const receipt = buildReceipt_(txId, settings);
      if (remaining) receipt.openOrder = remaining;
      if (shift && methods.indexOf('CASH') >= 0) {
        try { receipt.drawerFull = drawerFull_(shift, settings); } catch (e) { receipt.drawerFull = false; }
      }
      return receipt;
    });
  });
}

function statusWord_(s) {
  return { PAID: 'dibayar', CANCELLED: 'dibatalkan', VOID: 'di-void', OPEN: 'terbuka', COMPLETED: 'selesai',
           MERGED: 'digabung ke meja lain' }[s] || String(s).toLowerCase();
}

function methodLabel_(m) { return m === 'MIXED' ? MIXED_LABEL : (PAYMENT_METHODS[m] || m); }

function findTxIdByClientRef_(clientRef) {
  const cached = CacheService.getScriptCache().get('ref_' + clientRef);
  if (cached) return cached;
  const sh = getSheet_('Transactions');
  const headers = getHeaders_(sh);
  const rows = findRowNumbers_(sh, headers, 'Client_Ref', clientRef);
  if (!rows.length) return null;
  return String(rowObject_(sh, headers, rows[0]).Transaction_ID);
}

function getTransactionById_(txId) {
  const sh = getSheet_('Transactions');
  const headers = getHeaders_(sh);
  const rows = findRowNumbers_(sh, headers, 'Transaction_ID', txId);
  if (!rows.length) return null;
  const t = txFromRow_(rowObject_(sh, headers, rows[0]));
  t.row = rows[0];
  return t;
}

/** Rows of a sheet whose `header` equals value, read in one block. */
function rowsWhere_(name, header, value) {
  const sh = getSheet_(name);
  const headers = getHeaders_(sh);
  const rowNums = findRowNumbers_(sh, headers, header, value);
  if (!rowNums.length) return [];
  const min = Math.min.apply(null, rowNums);
  const max = Math.max.apply(null, rowNums);
  const values = sh.getRange(min, 1, max - min + 1, headers.length).getValues();
  return values.map(function (r, i) {
    const o = { _row: min + i };
    headers.forEach(function (h, j) { if (h) o[h] = r[j]; });
    return o;
  }).filter(function (o) { return String(o[header]) === String(value); });
}

function getTransactionDetails_(txId) {
  return rowsWhere_('Transaction_Details', 'Transaction_ID', txId)
    .sort(function (a, b) { return Number(a.Line_No) - Number(b.Line_No); })
    .map(function (o) {
      const total = moneyNum_(o.Total) || 0;
      const disc = moneyNum_(o.Discount) || 0;
      return { productId: String(o.Product_ID), name: String(o.Product_Name), category: String(o.Category),
               qty: Number(o.Quantity) || 0, price: moneyNum_(o.Unit_Price) || 0, total: total,
               discount: disc, discountInfo: String(o.Discount_Info || ''), netTotal: total - disc, note: String(o.Note || '') };
    });
}

function getPayments_(txId) {
  return rowsWhere_('Payments', 'Transaction_ID', txId)
    .sort(function (a, b) { return Number(a.Seq) - Number(b.Seq); })
    .map(function (o) {
      const m = String(o.Method || '');
      return { row: o._row, seq: Number(o.Seq) || 1, method: m, label: methodLabel_(m), amount: moneyNum_(o.Amount) || 0,
               rounding: moneyNum_(o.Rounding) || 0, paid: moneyNum_(o.Paid) || 0, change: moneyNum_(o.Change) || 0,
               status: String(o.Status || 'COMPLETED') };
    });
}

function txFromRow_(r) {
  const date = dateText_(r.Date);
  const method = String(r.Payment_Method || '').trim();
  return {
    id: String(r.Transaction_ID).trim(),
    date: date,
    dateLabel: dateLabel_(date),
    time: timeText_(r.Time),
    cashier: String(r.Cashier || ''),
    cashierId: String(r.Cashier_ID || ''),
    subtotal: moneyNum_(r.Subtotal) || 0,
    discount: moneyNum_(r.Discount) || 0,
    itemDiscount: moneyNum_(r.Item_Discount) || 0,
    billDiscount: isFinite(moneyNum_(r.Bill_Discount)) ? moneyNum_(r.Bill_Discount) : (moneyNum_(r.Discount) || 0),
    billDiscountInfo: String(r.Bill_Discount_Info || ''),
    service: moneyNum_(r.Service_Charge) || 0,
    tax: moneyNum_(r.Tax) || 0,
    rounding: moneyNum_(r.Rounding) || 0,
    total: moneyNum_(r.Grand_Total) || 0,
    method: method,
    methodLabel: methodLabel_(method),
    amountPaid: moneyNum_(r.Amount_Paid) || 0,
    change: moneyNum_(r.Change) || 0,
    status: String(r.Status || '').trim().toUpperCase() || 'COMPLETED',
    orderType: String(r.Order_Type || '').trim().toUpperCase() || 'TAKEAWAY',
    tableName: String(r.Table_Name || '').trim(),
    pax: Number(r.Pax) || 0,
    orderId: String(r.Order_ID || '').trim(),
    guestName: String(r.Guest_Name || '').trim(),
    shiftId: String(r.Shift_ID || '').trim(),
    splitInfo: String(r.Split_Info || '').trim(),
    durationMin: r.Duration_Min === '' || r.Duration_Min == null || !isFinite(Number(r.Duration_Min)) ? null : Number(r.Duration_Min),
    voidReason: String(r.Void_Reason || ''),
    voidBy: String(r.Void_By || ''),
    voidAt: cellText_(r.Void_At),
    stamp: cellText_(r.Timestamp) || (date + ' ' + timeText_(r.Time))
  };
}

function buildReceipt_(txId, settings) {
  settings = settings || getSettingsMap_();
  const t = getTransactionById_(txId);
  if (!t) throw new Error('Transaksi ' + txId + ' tidak ditemukan.');
  delete t.row;
  t.items = getTransactionDetails_(txId);
  let pays = [];
  try { pays = getPayments_(txId); } catch (e) { pays = []; }
  t.payments = pays.length ? pays.map(function (p) { delete p.row; return p; })
    : [{ seq: 1, method: t.method, label: t.methodLabel, amount: t.total, rounding: t.rounding, paid: t.amountPaid, change: t.change }];
  t.header = {
    business: settings.Business_Name || '',
    app: settings.App_Name || 'JayaPOS',
    address: settings.Receipt_Address || '',
    phone: settings.Receipt_Phone || '',
    footer: settings.Receipt_Footer || 'Terima Kasih',
    widthMm: String(settings.Receipt_Width_mm) === '80' ? 80 : 58,
    serviceLabel: settings.Service_Label || 'Service',
    taxLabel: settings.Tax_Label || 'PB1'
  };
  return t;
}

/**
 * Purchasing.gs  (Phase 3)
 * Suppliers, purchase orders, goods receiving and direct purchases.
 *
 * Flow:
 *  1. Purchase order (PO): supplier + ingredient lines with quantity in the ingredient's
 *     purchase unit and the agreed price per purchase unit. Status DRAFT or ORDERED.
 *  2. Goods receiving: type what actually arrived and the REAL price per unit on the invoice.
 *     Stock goes up, Cost_Per_Base_Unit is updated (weighted average or last price),
 *     and recipe COGS follow automatically. Status becomes PARTIAL or RECEIVED.
 *  3. Direct purchase (market / no PO): one step that creates and receives a PO.
 */

function poStatusWord_(s) {
  return { DRAFT: 'draft', ORDERED: 'dipesan', PARTIAL: 'diterima sebagian', RECEIVED: 'diterima', CANCELLED: 'dibatalkan' }[s] || String(s).toLowerCase();
}

// ---------------- Suppliers ----------------

function suppliersList_() {
  return readTable_('Suppliers').rows.map(function (r) {
    return {
      row: r._row, id: String(r.Supplier_ID).trim(), name: String(r.Supplier_Name).trim(),
      contact: String(r.Contact_Person || ''), phone: String(r.Phone || ''), address: String(r.Address || ''),
      notes: String(r.Notes || ''),
      active: String(r.Active_Status == null ? '' : r.Active_Status).trim() === '' ? true : isTrue_(r.Active_Status)
    };
  }).filter(function (s) { return s.id && s.name; });
}

function apiGetSuppliers(token) {
  return run_(function () {
    const user = requirePerm_(token, ['suppliers.manage', 'suppliers.view', 'purchasing.view', 'purchasing.manage']);
    const totals = {};
    readTable_('Purchase_Orders').rows.forEach(function (p) {
      const sid = String(p.Supplier_ID).trim();
      const t = totals[sid] = totals[sid] || { total: 0, count: 0, last: '' };
      const rec = moneyNum_(p.Received_Total) || 0;
      if (rec > 0) { t.total += rec; t.count++; }
      const d = dateText_(p.Received_Date);
      if (d > t.last) t.last = d;
    });
    return {
      canEdit: hasPerm_(user.role, 'suppliers.manage'),
      suppliers: suppliersList_().map(function (s) {
        const t = totals[s.id] || { total: 0, count: 0, last: '' };
        return { id: s.id, name: s.name, contact: s.contact, phone: s.phone, address: s.address, notes: s.notes, active: s.active,
                 purchased: t.total, receipts: t.count, lastPurchase: t.last ? dateLabel_(t.last) : '' };
      })
    };
  });
}

function apiSaveSupplier(token, d) {
  return run_(function () {
    const user = requirePerm_(token, 'suppliers.manage');
    d = d || {};
    const name = cleanText_(d.name, 80);
    if (!name) throw new Error('Nama supplier wajib diisi.');
    return withLock_(function () {
      const list = suppliersList_();
      if (list.some(function (s) { return s.name.toLowerCase() === name.toLowerCase() && s.id !== String(d.id || ''); })) {
        throw new Error('Supplier bernama "' + name + '" sudah ada.');
      }
      const fields = { Supplier_Name: name, Contact_Person: cleanText_(d.contact, 60), Phone: cleanText_(d.phone, 30),
                       Address: cleanText_(d.address, 150), Notes: cleanText_(d.notes, 200), Active_Status: d.active !== false,
                       Updated_At: nowStamp_() };
      let id = String(d.id || '');
      if (id) {
        const old = list.filter(function (s) { return s.id === id; })[0];
        if (!old) throw new Error('Supplier tidak ditemukan.');
        updateRow_('Suppliers', old.row, fields);
        audit_(user, 'SUPPLIER_UPDATE', 'Supplier', id, { name: name });
      } else {
        id = nextId_(list.map(function (s) { return s.id; }), 'S', 3);
        fields.Supplier_ID = id;
        appendObjects_('Suppliers', [fields]);
        audit_(user, 'SUPPLIER_CREATE', 'Supplier', id, { name: name });
      }
      return { id: id };
    });
  });
}

// ---------------- Purchase orders: reading ----------------

function poList_() {
  const sup = {};
  suppliersList_().forEach(function (s) { sup[s.id] = s; });
  const ings = {};
  ingredientsList_().forEach(function (i) { ings[i.id] = i; });
  const lines = {};
  readTable_('Purchase_Order_Details').rows.forEach(function (d) {
    const id = String(d.PO_ID).trim();
    const ing = ings[String(d.Ingredient_ID).trim()];
    (lines[id] = lines[id] || []).push({
      row: d._row, lineNo: Number(d.Line_No) || 0, ingredientId: String(d.Ingredient_ID).trim(),
      name: ing ? ing.name : String(d.Ingredient_ID), unit: String(d.Unit || ''), qty: numOr_(d.Quantity, 0),
      unitPrice: moneyNum_(d.Unit_Price) || 0, lineTotal: moneyNum_(d.Line_Total) || 0,
      qtyReceived: numOr_(d.Qty_Received, 0), receivedUnitPrice: moneyNum_(d.Received_Unit_Price) || 0,
      receivedTotal: moneyNum_(d.Received_Total) || 0,
      unitToBase: numOr_(d.Unit_To_Base, ing ? ing.purchaseToBase : 1) || 1, baseUnit: ing ? ing.baseUnit : ''
    });
  });
  return readTable_('Purchase_Orders').rows.map(function (p) {
    const id = String(p.PO_ID).trim();
    const sid = String(p.Supplier_ID).trim();
    return {
      row: p._row, id: id, date: dateText_(p.PO_Date), dateLabel: dateLabel_(dateText_(p.PO_Date)), supplierId: sid,
      supplierName: sup[sid] ? sup[sid].name : sid, status: String(p.Status || '').trim().toUpperCase(),
      type: String(p.Type || 'PO').trim().toUpperCase() || 'PO', total: moneyNum_(p.Total) || 0,
      receivedTotal: moneyNum_(p.Received_Total) || 0, createdBy: String(p.Created_By || ''),
      receivedDate: dateText_(p.Received_Date), receivedBy: String(p.Received_By || ''), invoiceNo: String(p.Invoice_No || ''),
      notes: String(p.Notes || ''),
      lines: (lines[id] || []).sort(function (a, b) { return a.lineNo - b.lineNo; })
    };
  }).filter(function (p) { return p.id; });
}

function publicPo_(p) {
  const o = {};
  Object.keys(p).forEach(function (k) { if (k !== 'row') o[k] = p[k]; });
  o.lines = p.lines.map(function (l) { const x = Object.assign({}, l); delete x.row; return x; });
  return o;
}

function apiGetPurchaseOrders(token, filter) {
  return run_(function () {
    const user = requirePerm_(token, ['purchasing.view', 'purchasing.manage']);
    filter = filter || {};
    const mode = String(filter.mode || 'open');
    let list = poList_();
    let range = null;
    if (mode === 'open') list = list.filter(function (p) { return ['DRAFT', 'ORDERED', 'PARTIAL'].indexOf(p.status) >= 0; });
    else if (mode === 'receiving') list = list.filter(function (p) { return ['ORDERED', 'PARTIAL', 'DRAFT'].indexOf(p.status) >= 0; });
    else {
      range = resolveRange_(filter);
      list = list.filter(function (p) {
        const d = p.receivedDate || p.date;
        return d >= range.from && d <= range.to && ['RECEIVED', 'PARTIAL', 'CANCELLED'].indexOf(p.status) >= 0;
      });
    }
    if (filter.supplierId) list = list.filter(function (p) { return p.supplierId === String(filter.supplierId); });
    list.sort(function (a, b) { return (b.receivedDate || b.date) < (a.receivedDate || a.date) ? -1 : 1; });
    const canManage = hasPerm_(user.role, 'purchasing.manage');
    return {
      mode: mode, from: range ? range.from : '', to: range ? range.to : '', canManage: canManage,
      orders: list.slice(0, 300).map(publicPo_),
      total: list.reduce(function (s, p) { return s + (mode === 'history' ? p.receivedTotal : p.total); }, 0),
      suppliers: suppliersList_().filter(function (s) { return s.active; }).map(function (s) { return { id: s.id, name: s.name }; }),
      ingredients: canManage ? ingredientsList_().filter(function (i) { return i.active; })
        .sort(function (a, b) { return a.name.localeCompare(b.name); })
        .map(function (i) { return { id: i.id, name: i.name, group: i.group, purchaseUnit: i.purchaseUnit, purchaseToBase: i.purchaseToBase,
                                      baseUnit: i.baseUnit, lastPrice: i.lastPrice, supplierId: i.supplierId,
                                      costPerPurchaseUnit: Math.round(i.cost * i.purchaseToBase) }; }) : []
    };
  });
}

// ---------------- Purchase orders: writing ----------------

function nextPoId_() {
  const dateKey = fmt_(new Date(), 'yyyyMMdd');
  const existing = {};
  readTable_('Purchase_Orders').rows.forEach(function (p) { existing[String(p.PO_ID).trim()] = true; });
  let n = nextSeq_('POSEQ_' + dateKey, 1);
  let id;
  do { n++; id = 'PO-' + dateKey + '-' + String(n).padStart(3, '0'); } while (existing[id]);
  PropertiesService.getScriptProperties().setProperty('POSEQ_' + dateKey, String(n));
  return id;
}

/** Checks PO lines from the phone. Returns lines with the ingredient attached. */
function checkPoLines_(lines) {
  if (!Array.isArray(lines) || !lines.length) throw new Error('Tambahkan minimal satu bahan.');
  if (lines.length > 100) throw new Error('Baris terlalu banyak (maks. 100).');
  const ings = {};
  ingredientsList_().forEach(function (i) { ings[i.id] = i; });
  return lines.map(function (l, idx) {
    const ing = ings[String(l && l.ingredientId || '')];
    if (!ing || !ing.active) throw new Error('Baris ' + (idx + 1) + ': pilih bahan.');
    const qty = Number(l.qty);
    if (!isFinite(qty) || qty <= 0 || qty > 1000000) throw new Error(ing.name + ': jumlah harus di atas 0.');
    const price = Number(l.unitPrice);
    if (!Number.isInteger(price) || price < 0 || price > 1000000000) throw new Error(ing.name + ': harga harus angka Rupiah bulat.');
    return { ing: ing, qty: round4_(qty), unitPrice: price, total: Math.round(qty * price) };
  });
}

/** Creates or replaces a PO (not yet received). Call inside withLock_. */
function savePo_(user, d, type) {
  const sid = String(d.supplierId || '');
  if (!suppliersList_().some(function (s) { return s.id === sid && s.active; })) throw new Error('Pilih supplier.');
  const date = isDateStr_(d.date) ? d.date : todayStr_();
  const status = String(d.status || 'ORDERED').toUpperCase();
  if (['DRAFT', 'ORDERED'].indexOf(status) < 0) throw new Error('Status tidak dikenal.');
  const lines = checkPoLines_(d.lines);
  const total = lines.reduce(function (s, l) { return s + l.total; }, 0);
  const stamp = nowStamp_();
  const header = { PO_Date: date, Supplier_ID: sid, Status: status, Total: total, Notes: cleanText_(d.notes, 200),
                   Type: type || 'PO', Updated_At: stamp };
  let id = String(d.poId || '');
  if (id) {
    const old = poList_().filter(function (p) { return p.id === id; })[0];
    if (!old) throw new Error('PO tidak ditemukan.');
    if (['DRAFT', 'ORDERED'].indexOf(old.status) < 0) throw new Error('PO ini sudah ' + poStatusWord_(old.status) + ' dan tidak bisa diubah lagi.');
    updateRow_('Purchase_Orders', old.row, header);
    deleteRowsWhere_('Purchase_Order_Details', 'PO_ID', id);
  } else {
    id = nextPoId_();
    header.PO_ID = id;
    header.Created_By = user.name;
    header.Received_Total = 0;
    appendObjects_('Purchase_Orders', [header]);
  }
  appendObjects_('Purchase_Order_Details', lines.map(function (l, i) {
    return { PO_ID: id, Line_No: i + 1, Ingredient_ID: l.ing.id, Quantity: l.qty, Unit: l.ing.purchaseUnit, Unit_Price: l.unitPrice,
             Line_Total: l.total, Qty_Received: 0, Received_Unit_Price: '', Received_Total: 0, Unit_To_Base: l.ing.purchaseToBase };
  }));
  return { id: id, total: total, lines: lines.length };
}

/** Receives goods on a PO. Call inside withLock_. */
function receivePo_(user, d) {
  const po = poList_().filter(function (p) { return p.id === String(d.poId || ''); })[0];
  if (!po) throw new Error('PO tidak ditemukan.');
  if (['DRAFT', 'ORDERED', 'PARTIAL'].indexOf(po.status) < 0) throw new Error('PO ini sudah ' + poStatusWord_(po.status) + '.');
  const input = {};
  (Array.isArray(d.lines) ? d.lines : []).forEach(function (l) { input[Number(l && l.lineNo)] = l; });
  const ings = {};
  ingredientsList_().forEach(function (i) { ings[i.id] = i; });
  const method = String(getSettingsMap_().Costing_Method || 'AVERAGE').toUpperCase();
  const state = {};   // running stock & cost per ingredient while we go through the lines
  const moves = [];
  const costUpdates = {};
  let received = 0;
  const invoice = cleanText_(d.invoiceNo, 40);

  po.lines.forEach(function (l) {
    const inp = input[l.lineNo];
    if (!inp) return;
    const qty = Number(inp.qty);
    if (!qty) return;
    if (!isFinite(qty) || qty < 0 || qty > 1000000) throw new Error(l.name + ': jumlah diterima tidak valid.');
    const price = Number(inp.unitPrice);
    if (!Number.isInteger(price) || price < 0 || price > 1000000000) throw new Error(l.name + ': harga harus angka Rupiah bulat.');
    const ing = ings[l.ingredientId];
    if (!ing) throw new Error('Bahan ' + l.ingredientId + ' sudah tidak ada.');
    const factor = l.unitToBase > 0 ? l.unitToBase : ing.purchaseToBase;
    const baseQty = qty * factor;
    const costPerBase = price / factor;
    const st = state[ing.id] = state[ing.id] || { stock: ing.stock, cost: ing.cost };
    if (method === 'LAST' || st.stock <= 0) st.cost = costPerBase;
    else st.cost = (st.stock * st.cost + baseQty * costPerBase) / (st.stock + baseQty);
    st.stock += baseQty;
    costUpdates[ing.id] = { cost: st.cost, lastPrice: Math.round(price * ing.purchaseToBase / factor) };
    moves.push({ ing: ing, type: 'PURCHASE', qty: qty, unit: l.unit, baseQty: baseQty, unitCost: costPerBase, ref: po.id,
                 supplierId: po.supplierId, notes: invoice ? 'Invoice ' + invoice : '' });
    const lineTotal = Math.round(qty * price);
    received += lineTotal;
    updateRow_('Purchase_Order_Details', l.row, { Qty_Received: round4_(l.qtyReceived + qty), Received_Unit_Price: price,
                                                   Received_Total: l.receivedTotal + lineTotal });
    l.qtyReceived += qty;
  });
  if (!moves.length && !d.close) throw new Error('Isi jumlah barang yang datang, minimal untuk satu baris.');
  if (!moves.length && d.close && po.receivedTotal === 0) throw new Error('Belum ada barang yang diterima untuk PO ini. Pakai "Batalkan PO" saja.');

  applyMovements_(moves, user, costUpdates);
  const complete = po.lines.every(function (l) { return l.qtyReceived >= l.qty - 1e-9; });
  const status = complete || d.close ? 'RECEIVED' : 'PARTIAL';
  const recDate = isDateStr_(d.date) ? d.date : todayStr_();
  updateRow_('Purchase_Orders', po.row, {
    Status: status, Received_Total: po.receivedTotal + received, Received_Date: recDate, Received_By: user.name,
    Invoice_No: invoice ? (po.invoiceNo ? po.invoiceNo + ', ' + invoice : invoice) : po.invoiceNo, Updated_At: nowStamp_()
  });
  if (moves.length) refreshProductCosts_();
  audit_(user, 'PURCHASE_RECEIVE', 'PurchaseOrder', po.id, { supplier: po.supplierName, lines: moves.length, total: received, status: status, invoice: invoice });
  return { id: po.id, status: status, received: received };
}

function apiSavePurchaseOrder(token, d) {
  return run_(function () {
    const user = requirePerm_(token, 'purchasing.manage');
    return withLock_(function () {
      const r = savePo_(user, d || {}, 'PO');
      audit_(user, d && d.poId ? 'PO_UPDATE' : 'PO_CREATE', 'PurchaseOrder', r.id, { total: r.total, lines: r.lines, status: d.status });
      return r;
    });
  });
}

function apiReceivePurchaseOrder(token, d) {
  return run_(function () {
    const user = requirePerm_(token, 'purchasing.manage');
    return withLock_(function () { return receivePo_(user, d || {}); });
  });
}

/** Market / no-PO purchase: creates the PO and receives everything in one step. */
function apiDirectPurchase(token, d) {
  return run_(function () {
    const user = requirePerm_(token, 'purchasing.manage');
    d = d || {};
    return withLock_(function () {
      const r = savePo_(user, { supplierId: d.supplierId, date: d.date, notes: d.notes, status: 'ORDERED', lines: d.lines }, 'DIRECT');
      const po = poList_().filter(function (p) { return p.id === r.id; })[0];
      return receivePo_(user, { poId: r.id, invoiceNo: d.invoiceNo, date: d.date,
        lines: po.lines.map(function (l) { return { lineNo: l.lineNo, qty: l.qty, unitPrice: l.unitPrice }; }) });
    });
  });
}

function apiCancelPurchaseOrder(token, poId) {
  return run_(function () {
    const user = requirePerm_(token, 'purchasing.manage');
    return withLock_(function () {
      const po = poList_().filter(function (p) { return p.id === String(poId || ''); })[0];
      if (!po) throw new Error('PO tidak ditemukan.');
      if (po.lines.some(function (l) { return l.qtyReceived > 0; })) throw new Error('Sudah ada barang yang diterima untuk PO ini, jadi tidak bisa dibatalkan. Tutup PO-nya dari Penerimaan Barang.');
      if (['DRAFT', 'ORDERED'].indexOf(po.status) < 0) throw new Error('PO ini sudah ' + poStatusWord_(po.status) + '.');
      updateRow_('Purchase_Orders', po.row, { Status: 'CANCELLED', Updated_At: nowStamp_() });
      audit_(user, 'PO_CANCEL', 'PurchaseOrder', po.id, { supplier: po.supplierName, total: po.total });
      return true;
    });
  });
}

/**
 * Reports.gs
 * Sales History, receipts, the Dashboard and the owner reports (Phase 4):
 * sales, COGS, profitability, purchasing and inventory.
 *
 * Definitions used everywhere:
 *  - Gross sales  = sum of item prices (Subtotal)
 *  - Net sales    = Gross sales - discounts   (service and tax are NOT revenue here)
 *  - COGS         = quantity x Unit_Cost saved at the moment of sale (recipe cost, or Products.Cost)
 *  - Gross profit = Net sales - COGS;  margin = Gross profit / Net sales
 *  - Per-product revenue is after item discounts, before the bill discount.
 *  - Voided transactions (Status VOID) are left out everywhere; the Sales report shows how many.
 */

function resolveRange_(filter) {
  filter = filter || {};
  const today = todayStr_();
  const range = String(filter.range || 'today');
  let from, to;
  if (range === 'today') { from = today; to = today; }
  else if (range === 'yesterday') { from = addDays_(today, -1); to = from; }
  else if (range === 'week') { from = addDays_(today, -((dayOfWeek_(today) + 6) % 7)); to = today; } // week starts Monday
  else if (range === 'month') { from = today.slice(0, 8) + '01'; to = today; }
  else if (range === 'custom') {
    if (!isDateStr_(filter.from)) throw new Error('Pilih tanggal mulai.');
    from = filter.from;
    to = isDateStr_(filter.to) ? filter.to : filter.from;
    if (from > to) { const x = from; from = to; to = x; }
  } else {
    throw new Error('Filter tanggal tidak dikenal.');
  }
  return { from: from, to: to };
}

/**
 * Reads only rows from `from` onwards (sheets are written in date order), so reports stay fast
 * as the sheets grow. Returns row objects like readTable_.
 */
function readSince_(name, dateHeader, from) {
  const sh = getSheet_(name);
  const headers = getHeaders_(sh);
  const c = headers.indexOf(dateHeader);
  const lastRow = sh.getLastRow();
  if (lastRow < 2) return [];
  if (c < 0) return readTable_(name).rows;
  const dates = sh.getRange(2, c + 1, lastRow - 1, 1).getValues();
  let i = 0;
  while (i < dates.length && dateText_(dates[i][0]) < from) i++;
  if (i >= dates.length) return [];
  return sh.getRange(2 + i, 1, lastRow - 1 - i, headers.length).getValues().map(function (r, k) {
    const o = { _row: 2 + i + k };
    headers.forEach(function (h, j) { if (h) o[h] = r[j]; });
    return o;
  }).filter(function (o) { return o[headers[0]] !== '' && o[headers[0]] !== null; });
}

/** Completed sales and their lines between two dates. */
function salesData_(from, to) {
  const all = readSince_('Transactions', 'Date', from).map(txFromRow_)
    .filter(function (t) { return t.id && t.date >= from && t.date <= to; });
  const txs = all.filter(function (t) { return t.status === 'COMPLETED'; });
  const voids = all.filter(function (t) { return t.status === 'VOID'; });
  const ids = {};
  txs.forEach(function (t) { ids[t.id] = t; });
  const lines = readSince_('Transaction_Details', 'Date', from).filter(function (d) { return ids[String(d.Transaction_ID)]; })
    .map(function (d) {
      const qty = Number(d.Quantity) || 0;
      const gross = moneyNum_(d.Total) || 0;
      const net = moneyNum_(d.Net_Total);
      const unitCost = moneyNum_(d.Unit_Cost) || 0;
      const t = ids[String(d.Transaction_ID)];
      return { txId: t.id, date: t.date, productId: String(d.Product_ID), name: String(d.Product_Name),
               category: String(d.Category || 'Other'), qty: qty, revenue: isFinite(net) ? net : gross,
               unitCost: unitCost, cogs: unitCost * qty };
    });
  return { txs: txs, lines: lines, voids: voids };
}

/**
 * Money received per payment method. A bill split equally over QRIS + cash counts in both
 * (from the Payments sheet); sales saved before v3 use the method on the transaction.
 */
function paymentsByMethod_(txs, from) {
  const ids = {};
  txs.forEach(function (t) { ids[t.id] = true; });
  const got = {};
  try {
    readSince_('Payments', 'Date', from).forEach(function (p) {
      const id = String(p.Transaction_ID);
      if (!ids[id]) return;
      (got[id] = got[id] || []).push({ method: String(p.Method), amount: moneyNum_(p.Amount) || 0 });
    });
  } catch (e) { /* no Payments sheet yet */ }
  const list = [];
  txs.forEach(function (t) {
    (got[t.id] || [{ method: t.method, amount: t.total }]).forEach(function (p) { list.push(p); });
  });
  return groupSum_(list, function (p) { return p.method; },
    function (p) { return { method: p.method, label: methodLabel_(p.method), total: 0, count: 0 }; },
    function (m, p) { m.total += p.amount; m.count++; }).sort(function (a, b) { return b.total - a.total; });
}

/** "yyyy-MM-dd HH:mm:ss" (Bali time, WITA = UTC+8) -> milliseconds. */
function stampMs_(s) {
  const m = String(s || '').match(/^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2})(?::(\d{2}))?/);
  if (!m) return NaN;
  return Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4] - 8, +m[5], +(m[6] || 0));
}

/**
 * How long dine-in guests stayed: from opening the table to this payment (minutes).
 * Sales saved before v3.0.1 have no Duration_Min; it is worked out from the table bill's opening time.
 */
function fillDurations_(txs) {
  const need = txs.filter(function (t) { return t.orderType === 'DINE_IN' && t.durationMin === null && t.orderId; });
  if (!need.length) return txs;
  const opened = {};
  try {
    readRecentRows_('Open_Orders', 3000).forEach(function (r) {
      const ms = Number(r.Opened_Ms) || stampMs_(cellText_(r.Opened_At));
      if (r.Order_ID && isFinite(ms)) opened[String(r.Order_ID).trim()] = ms;
    });
  } catch (e) { return txs; }
  need.forEach(function (t) {
    const o = opened[t.orderId];
    const paid = stampMs_(t.stamp);
    if (o && isFinite(paid) && paid >= o - 60000) t.durationMin = Math.max(0, Math.round((paid - o) / 60000));   // the paid time has whole seconds only
  });
  return txs;
}

/** Average stay per table bill (a split bill counts once, until its last payment). */
function avgDuration_(txs) {
  const byOrder = {};
  txs.forEach(function (t) {
    if (t.orderType !== 'DINE_IN' || t.durationMin === null) return;
    const k = t.orderId || t.id;
    byOrder[k] = Math.max(byOrder[k] || 0, t.durationMin);
  });
  const v = Object.keys(byOrder).map(function (k) { return byOrder[k]; });
  return v.length ? { avg: Math.round(v.reduce(function (a, b) { return a + b; }, 0) / v.length), max: Math.max.apply(null, v), bills: v.length } : null;
}

function daysBetween_(from, to) {
  const out = [];
  let d = from;
  while (d <= to && out.length < 400) { out.push(d); d = addDays_(d, 1); }
  return out;
}

function groupSum_(rows, keyFn, init, addFn) {
  const map = {};
  rows.forEach(function (r) {
    const k = keyFn(r);
    if (!map[k]) map[k] = init(r);
    addFn(map[k], r);
  });
  return Object.keys(map).map(function (k) { return map[k]; });
}

function pct_(a, b) { return b ? Math.round(a / b * 1000) / 10 : 0; }

/** Earliest date this user may see. Cashiers only see recent days. */
function historyStart_(user) {
  if (hasPerm_(user.role, 'history.view_all')) return '0000-00-00';
  const days = Math.max(1, parseInt(getSettingsMap_().Cashier_History_Days, 10) || 2);
  return addDays_(todayStr_(), -(days - 1));
}

function apiGetSalesHistory(token, filter) {
  return run_(function () {
    const user = requirePerm_(token, ['history.view_all', 'history.view_recent']);
    const r = resolveRange_(filter);
    const earliest = historyStart_(user);
    let limited = false;
    if (r.from < earliest) { r.from = earliest; limited = true; }
    const showTotals = hasPerm_(user.role, 'history.view_all');
    if (r.to < r.from) return { from: r.from, to: r.to, limited: true, count: 0, total: null, rows: [], truncated: false };

    const rows = readSince_('Transactions', 'Date', r.from).map(txFromRow_)
      .filter(function (t) { return t.id && t.date >= r.from && t.date <= r.to; })
      .sort(function (a, b) { return a.stamp < b.stamp ? 1 : (a.stamp > b.stamp ? -1 : 0); });
    fillDurations_(rows.slice(0, 500));
    const total = rows.filter(function (t) { return t.status === 'COMPLETED'; })
      .reduce(function (s, t) { return s + t.total; }, 0);

    return {
      from: r.from, to: r.to, limited: limited, count: rows.length,
      total: showTotals ? total : null,
      rows: rows.slice(0, 500).map(function (t) {
        return { id: t.id, date: t.date, dateLabel: t.dateLabel, time: t.time, cashier: t.cashier,
                 total: t.total, methodLabel: t.methodLabel, status: t.status,
                 orderType: t.orderType, tableName: t.tableName, pax: t.pax, guestName: t.guestName, splitInfo: t.splitInfo,
                 durationMin: t.durationMin };
      }),
      truncated: rows.length > 500
    };
  });
}

function apiGetReceipt(token, txId) {
  return run_(function () {
    const user = requirePerm_(token, 'receipt.view');
    txId = String(txId || '').trim();
    if (!/^[A-Z]{1,5}-\d{8}-\d{4,}$/.test(txId)) throw new Error('Nomor transaksi tidak valid.');
    const r = buildReceipt_(txId);
    if (r.date < historyStart_(user)) throw jayaError_('Akses ditolak. Transaksi ini terlalu lama untuk role Anda.', 'DENIED');
    r.canVoid = r.status === 'COMPLETED' && hasPerm_(user.role, 'pos.void') && r.date >= voidStart_(user);
    return r;
  });
}

function apiGetDashboard(token, filter) {
  return run_(function () {
    const user = requirePerm_(token, 'dashboard.view');
    const r = resolveRange_(filter);
    const d = salesData_(r.from, r.to);
    const txs = d.txs;
    const sum = function (f) { return txs.reduce(function (s, t) { return s + f(t); }, 0); };
    const sales = sum(function (t) { return t.total; });
    const net = sum(function (t) { return t.subtotal - t.discount; });
    const cogs = Math.round(d.lines.reduce(function (s, l) { return s + l.cogs; }, 0));
    const methods = paymentsByMethod_(txs, r.from);
    const top = groupSum_(d.lines, function (l) { return l.productId; },
      function (l) { return { id: l.productId, name: l.name, qty: 0, sales: 0 }; },
      function (p, l) { p.qty += l.qty; p.sales += l.revenue; })
      .sort(function (a, b) { return b.qty - a.qty || b.sales - a.sales; }).slice(0, 10);
    const dine = txs.filter(function (t) { return t.orderType === 'DINE_IN'; });
    const days = daysBetween_(r.from, r.to);
    const byDay = days.length > 1 ? days.map(function (day) {
      const dt = txs.filter(function (t) { return t.date === day; });
      const dn = dt.reduce(function (s, t) { return s + t.subtotal - t.discount; }, 0);
      const dc = Math.round(d.lines.filter(function (l) { return l.date === day; }).reduce(function (s, l) { return s + l.cogs; }, 0));
      return { date: day, label: dateLabel_(day).slice(0, 6), net: dn, gp: dn - dc, count: dt.length };
    }) : [];
    const s = getSettingsMap_();
    const showProfit = hasPerm_(user.role, 'reports.view');
    return {
      from: r.from, to: r.to,
      sales: sales,
      count: txs.length,
      average: txs.length ? Math.round(sales / txs.length) : 0,
      service: sum(function (t) { return t.service; }),
      tax: sum(function (t) { return t.tax; }),
      serviceLabel: s.Service_Label || 'Service',
      taxLabel: s.Tax_Label || 'Tax',
      dineIn: dine.length,
      guests: dine.reduce(function (a, t) { return a + t.pax; }, 0),
      takeaway: txs.length - dine.length,
      net: net,
      cogs: showProfit ? cogs : null,
      grossProfit: showProfit ? net - cogs : null,
      margin: showProfit ? pct_(net - cogs, net) : null,
      byDay: byDay,
      byMethod: methods,
      topProducts: top
    };
  });
}

// ---------------- Phase 4 reports ----------------

function apiGetReport(token, type, filter) {
  return run_(function () {
    type = String(type || '');
    requirePerm_(token, type === 'inventory' ? ['inventory.view'] : ['reports.view']);
    const r = resolveRange_(filter);
    if (type === 'sales') return salesReport_(r);
    if (type === 'cogs') return cogsReport_(r);
    if (type === 'profit') return profitReport_(r);
    if (type === 'purchasing') return purchasingReport_(r);
    if (type === 'inventory') return inventoryReport_(r);
    throw new Error('Laporan tidak dikenal.');
  });
}

function salesReport_(r) {
  const d = salesData_(r.from, r.to);
  const txs = fillDurations_(d.txs);
  const sum = function (f) { return txs.reduce(function (s, t) { return s + f(t); }, 0); };
  const gross = sum(function (t) { return t.subtotal; });
  const discount = sum(function (t) { return t.discount; });
  const itemDiscount = sum(function (t) { return t.itemDiscount; });
  const collected = sum(function (t) { return t.total; });
  const byDay = daysBetween_(r.from, r.to).map(function (day) {
    const dt = txs.filter(function (t) { return t.date === day; });
    return { date: day, label: dateLabel_(day), net: dt.reduce(function (s, t) { return s + t.subtotal - t.discount; }, 0), count: dt.length };
  });
  const byHour = groupSum_(txs, function (t) { return t.time.slice(0, 2); },
    function (t) { return { hour: t.time.slice(0, 2), net: 0, count: 0 }; },
    function (h, t) { h.net += t.subtotal - t.discount; h.count++; }).sort(function (a, b) { return a.hour < b.hour ? -1 : 1; });
  const byPayment = paymentsByMethod_(txs, r.from);
  const byType = groupSum_(txs, function (t) { return t.orderType; },
    function (t) { return { type: t.orderType === 'DINE_IN' ? 'Makan di tempat' : 'Takeaway', count: 0, net: 0, guests: 0 }; },
    function (m, t) { m.count++; m.net += t.subtotal - t.discount; m.guests += t.pax; });
  const products = groupSum_(d.lines, function (l) { return l.productId; },
    function (l) { return { name: l.name, category: l.category, qty: 0, revenue: 0 }; },
    function (p, l) { p.qty += l.qty; p.revenue += l.revenue; }).sort(function (a, b) { return b.revenue - a.revenue; });
  const categories = groupSum_(d.lines, function (l) { return l.category; },
    function (l) { return { name: l.category, qty: 0, revenue: 0 }; },
    function (c, l) { c.qty += l.qty; c.revenue += l.revenue; }).sort(function (a, b) { return b.revenue - a.revenue; });
  return {
    type: 'sales', from: r.from, to: r.to, count: txs.length, gross: gross, discount: discount, net: gross - discount,
    itemDiscount: itemDiscount, billDiscount: discount - itemDiscount,
    service: sum(function (t) { return t.service; }), tax: sum(function (t) { return t.tax; }),
    rounding: sum(function (t) { return t.rounding; }), collected: collected,
    voidCount: d.voids.length, voidTotal: d.voids.reduce(function (s, t) { return s + t.total; }, 0),
    voids: d.voids.map(function (t) { return { id: t.id, date: t.dateLabel, total: t.total, by: t.voidBy, reason: t.voidReason, cashier: t.cashier }; }),
    average: txs.length ? Math.round(collected / txs.length) : 0,
    stay: avgDuration_(txs),
    byDay: byDay, byHour: byHour, byPayment: byPayment, byType: byType, products: products.slice(0, 100), categories: categories
  };
}

function cogsReport_(r) {
  const d = salesData_(r.from, r.to);
  const net = d.txs.reduce(function (s, t) { return s + t.subtotal - t.discount; }, 0);
  const cogs = Math.round(d.lines.reduce(function (s, l) { return s + l.cogs; }, 0));
  const products = groupSum_(d.lines, function (l) { return l.productId; },
    function (l) { return { name: l.name, category: l.category, qty: 0, revenue: 0, cogs: 0, missing: false }; },
    function (p, l) { p.qty += l.qty; p.revenue += l.revenue; p.cogs += l.cogs; if (!l.unitCost) p.missing = true; })
    .map(function (p) { p.cogs = Math.round(p.cogs); p.unitCost = p.qty ? Math.round(p.cogs / p.qty) : 0; p.costPct = pct_(p.cogs, p.revenue); return p; })
    .sort(function (a, b) { return b.cogs - a.cogs; });
  const categories = groupSum_(products, function (p) { return p.category; },
    function (p) { return { name: p.category, revenue: 0, cogs: 0 }; },
    function (c, p) { c.revenue += p.revenue; c.cogs += p.cogs; })
    .map(function (c) { c.costPct = pct_(c.cogs, c.revenue); return c; }).sort(function (a, b) { return b.cogs - a.cogs; });
  return {
    type: 'cogs', from: r.from, to: r.to, net: net, cogs: cogs, cogsPct: pct_(cogs, net), products: products.slice(0, 100),
    categories: categories, missing: products.filter(function (p) { return p.missing; }).map(function (p) { return p.name; })
  };
}

function profitReport_(r) {
  const d = salesData_(r.from, r.to);
  const net = d.txs.reduce(function (s, t) { return s + t.subtotal - t.discount; }, 0);
  const cogs = Math.round(d.lines.reduce(function (s, l) { return s + l.cogs; }, 0));
  const byDay = daysBetween_(r.from, r.to).map(function (day) {
    const dn = d.txs.filter(function (t) { return t.date === day; }).reduce(function (s, t) { return s + t.subtotal - t.discount; }, 0);
    const dc = Math.round(d.lines.filter(function (l) { return l.date === day; }).reduce(function (s, l) { return s + l.cogs; }, 0));
    return { date: day, label: dateLabel_(day), net: dn, cogs: dc, gp: dn - dc };
  });
  const products = groupSum_(d.lines, function (l) { return l.productId; },
    function (l) { return { name: l.name, category: l.category, qty: 0, revenue: 0, cogs: 0 }; },
    function (p, l) { p.qty += l.qty; p.revenue += l.revenue; p.cogs += l.cogs; })
    .map(function (p) { p.cogs = Math.round(p.cogs); p.gp = p.revenue - p.cogs; p.margin = pct_(p.gp, p.revenue); return p; })
    .sort(function (a, b) { return b.gp - a.gp; });
  const categories = groupSum_(products, function (p) { return p.category; },
    function (p) { return { name: p.category, revenue: 0, cogs: 0, gp: 0 }; },
    function (c, p) { c.revenue += p.revenue; c.cogs += p.cogs; c.gp += p.gp; })
    .map(function (c) { c.margin = pct_(c.gp, c.revenue); return c; }).sort(function (a, b) { return b.gp - a.gp; });
  return {
    type: 'profit', from: r.from, to: r.to, net: net, cogs: cogs, gp: net - cogs, margin: pct_(net - cogs, net),
    discount: d.txs.reduce(function (s, t) { return s + t.discount; }, 0),
    byDay: byDay, products: products.slice(0, 100), categories: categories
  };
}

function purchasingReport_(r) {
  const sup = {};
  suppliersList_().forEach(function (s) { sup[s.id] = s.name; });
  const moves = readSince_('Inventory_Movements', 'Date', r.from).filter(function (m) {
    const d = dateText_(m.Date);
    return String(m.Movement_Type) === 'PURCHASE' && d >= r.from && d <= r.to;
  });
  const total = moves.reduce(function (s, m) { return s + (moneyNum_(m.Total_Cost) || 0); }, 0);
  const bySupplier = groupSum_(moves, function (m) { return String(m.Supplier_ID); },
    function (m) { return { name: sup[String(m.Supplier_ID)] || String(m.Supplier_ID || 'Tidak diketahui'), total: 0, refs: {} }; },
    function (s, m) { s.total += moneyNum_(m.Total_Cost) || 0; s.refs[String(m.Reference_ID)] = true; })
    .map(function (s) { return { name: s.name, total: s.total, receipts: Object.keys(s.refs).length }; })
    .sort(function (a, b) { return b.total - a.total; });
  const byIngredient = groupSum_(moves, function (m) { return String(m.Ingredient_ID); },
    function (m) { return { name: String(m.Ingredient_Name || m.Ingredient_ID), baseQty: 0, total: 0, unit: '' }; },
    function (i, m) { i.baseQty += numOr_(m.Quantity_Base, 0); i.total += moneyNum_(m.Total_Cost) || 0; })
    .sort(function (a, b) { return b.total - a.total; });
  const ings = {};
  ingredientsList_().forEach(function (i) { ings[i.name] = i; });
  byIngredient.forEach(function (i) {
    const ing = ings[i.name];
    i.unit = ing ? ing.baseUnit : '';
    i.baseQty = round4_(i.baseQty);
    i.avgPerPurchaseUnit = ing && i.baseQty ? Math.round(i.total / i.baseQty * ing.purchaseToBase) : 0;
    i.purchaseUnit = ing ? ing.purchaseUnit : '';
  });
  const receipts = groupSum_(moves, function (m) { return String(m.Reference_ID) + '|' + cellText_(m.Timestamp) + '|' + String(m.Notes || ''); },
    function (m) { return { po: String(m.Reference_ID), date: dateLabel_(dateText_(m.Date)), supplier: sup[String(m.Supplier_ID)] || '', total: 0, lines: 0 }; },
    function (x, m) { x.total += moneyNum_(m.Total_Cost) || 0; x.lines++; }).reverse();
  const open = poList_().filter(function (p) { return p.status === 'ORDERED' || p.status === 'PARTIAL'; });
  return {
    type: 'purchasing', from: r.from, to: r.to, total: total, bySupplier: bySupplier, byIngredient: byIngredient.slice(0, 100),
    receipts: receipts.slice(0, 100),
    openOrders: open.length,
    openValue: open.reduce(function (s, p) {
      return s + p.lines.reduce(function (a, l) { return a + Math.max(0, l.qty - l.qtyReceived) * l.unitPrice; }, 0);
    }, 0)
  };
}

function inventoryReport_(r) {
  const ings = ingredientsList_().filter(function (i) { return i.active; });
  const moves = readSince_('Inventory_Movements', 'Date', r.from).filter(function (m) {
    const d = dateText_(m.Date);
    return d >= r.from && d <= r.to;
  });
  const mv = {};
  moves.forEach(function (m) {
    const id = String(m.Ingredient_ID);
    const x = mv[id] = mv[id] || { PURCHASE: 0, SALE: 0, VOID: 0, WASTE: 0, ADJUST: 0, OPENING: 0, saleCost: 0, wasteCost: 0 };
    const t = String(m.Movement_Type);
    x[t] = (x[t] || 0) + numOr_(m.Quantity_Base, 0);
    if (t === 'SALE' || t === 'VOID') x.saleCost += -(moneyNum_(m.Total_Cost) || 0);
    if (t === 'WASTE') x.wasteCost += -(moneyNum_(m.Total_Cost) || 0);
  });
  const rows = ings.map(function (i) {
    const x = mv[i.id] || { PURCHASE: 0, SALE: 0, VOID: 0, WASTE: 0, ADJUST: 0, OPENING: 0, saleCost: 0, wasteCost: 0 };
    return {
      name: i.name, group: i.group, unit: i.baseUnit, stock: round4_(i.stock), minStock: i.minStock,
      costPerPurchaseUnit: Math.round(i.cost * i.purchaseToBase), purchaseUnit: i.purchaseUnit,
      value: Math.round(Math.max(0, i.stock) * i.cost), low: i.minStock > 0 && i.stock < i.minStock, negative: i.stock < 0,
      purchased: round4_(x.PURCHASE), used: round4_(-(x.SALE + x.VOID)), wasted: round4_(-x.WASTE), adjusted: round4_(x.ADJUST + x.OPENING),
      usedCost: Math.round(x.saleCost), wasteCost: Math.round(x.wasteCost)
    };
  }).sort(function (a, b) { return b.value - a.value; });
  const byGroup = groupSum_(rows, function (x) { return x.group; },
    function (x) { return { name: x.group, value: 0, items: 0 }; },
    function (g, x) { g.value += x.value; g.items++; });
  return {
    type: 'inventory', from: r.from, to: r.to,
    totalValue: rows.reduce(function (s, x) { return s + x.value; }, 0),
    usedCost: rows.reduce(function (s, x) { return s + x.usedCost; }, 0),
    wasteCost: rows.reduce(function (s, x) { return s + x.wasteCost; }, 0),
    lowCount: rows.filter(function (x) { return x.low; }).length,
    byGroup: byGroup, rows: rows
  };
}

/**
 * Shift.gs
 * Cash drawer ("Kas & Shift"): counting the opening cash, cash in / out, handing cash to the owner
 * ("setor"), and closing the shift with a BLIND count.
 *
 * How it prevents cheating:
 *  - Opening: the cashier counts every note/coin. If it differs from what the previous shift left in the
 *    drawer, the owner / admin gets a notification straight away.
 *  - While open: every Rupiah that leaves the drawer is a recorded movement with a name and a reason
 *    (Kas keluar). A "setor" stays PENDING until the owner / admin confirms they really received it
 *    (and the person who hands over cash cannot confirm it themselves).
 *  - Closing: the cashier counts the drawer WITHOUT seeing how much there should be. The system then
 *    compares: expected = opening + cash sales + cash in - cash out - setor. The difference is saved and
 *    sent to the owner / admin. Only owner / admin see the expected amount while the shift is open.
 *  - All payments are tied to the open shift (Payments.Shift_ID), so a sale cannot "disappear" from it;
 *    a voided sale is visible in the notifications.
 */

function shiftFromRow_(r) {
  return {
    row: r._row, id: String(r.Shift_ID || '').trim(), date: dateText_(r.Date), status: String(r.Status || '').trim().toUpperCase(),
    openedAt: cellText_(r.Opened_At), openedBy: String(r.Opened_By || ''), openedById: String(r.Opened_By_ID || ''),
    opening: moneyNum_(r.Opening_Cash) || 0, previousLeft: r.Previous_Left === '' || r.Previous_Left == null ? null : (moneyNum_(r.Previous_Left) || 0),
    openingDiff: moneyNum_(r.Opening_Diff) || 0,
    closedAt: cellText_(r.Closed_At), closedBy: String(r.Closed_By || ''),
    cashSales: moneyNum_(r.Cash_Sales) || 0, cashIn: moneyNum_(r.Cash_In) || 0, cashOut: moneyNum_(r.Cash_Out) || 0,
    setor: moneyNum_(r.Setor_Total) || 0, expected: moneyNum_(r.Expected_Cash) || 0, counted: moneyNum_(r.Counted_Cash) || 0,
    difference: moneyNum_(r.Difference) || 0, leftForNext: moneyNum_(r.Left_For_Next) || 0, finalSetor: moneyNum_(r.Final_Setor) || 0,
    txCount: Number(r.Tx_Count) || 0, notes: String(r.Notes || ''), nonCash: String(r.Non_Cash || '')
  };
}

/** The open shift, or null. */
function currentShift_() {
  const sh = getSheet_('Shifts');
  const headers = getHeaders_(sh);
  const rows = findRowNumbers_(sh, headers, 'Status', 'OPEN');
  if (!rows.length) return null;
  return shiftFromRow_(rowObject_(sh, headers, rows[rows.length - 1]));
}

function lastClosedShift_() {
  const rows = readRecentRows_('Shifts', 40).map(shiftFromRow_).filter(function (s) { return s.id && s.status === 'CLOSED'; });
  return rows.length ? rows[rows.length - 1] : null;
}

/** Called before taking money. Throws when a shift is required but none is open. */
function shiftForPayment_(settings) {
  const s = currentShift_();
  if (!s && isTrue_((settings || getSettingsMap_()).Require_Shift)) {
    throw jayaError_('Shift kas belum dibuka. Buka dulu di ☰ → Kas & Shift (hitung modal awal), lalu bayar lagi.', 'NO_SHIFT');
  }
  return s;
}

function moveFromRow_(r) {
  return {
    id: String(r.Movement_ID || ''), shiftId: String(r.Shift_ID || ''), when: cellText_(r.Timestamp), time: cellText_(r.Timestamp).slice(11, 16),
    type: String(r.Type || ''), amount: moneyNum_(r.Amount) || 0, reason: String(r.Reason || ''), user: String(r.User_Name || ''),
    userId: String(r.User_ID || ''), status: String(r.Status || ''), confirmedBy: String(r.Confirmed_By || ''),
    confirmedAt: cellText_(r.Confirmed_At), confirmNote: String(r.Confirm_Note || '')
  };
}

/** Live numbers of a shift, from the Payments and Cash_Movements sheets. */
function shiftNumbers_(shift) {
  const pays = readSince_('Payments', 'Date', shift.date).filter(function (p) {
    return String(p.Shift_ID) === shift.id && String(p.Status || 'COMPLETED') !== 'VOID';
  });
  const by = {};
  const tx = {};
  let cashSales = 0;
  pays.forEach(function (p) {
    const m = String(p.Method);
    const amt = moneyNum_(p.Amount) || 0;
    if (!by[m]) by[m] = { method: m, label: methodLabel_(m), total: 0, count: 0 };
    by[m].total += amt;
    by[m].count++;
    if (m === 'CASH') cashSales += amt;
    tx[String(p.Transaction_ID)] = true;
  });
  const moves = readSince_('Cash_Movements', 'Date', shift.date).map(moveFromRow_).filter(function (m) { return m.shiftId === shift.id; });
  const sum = function (type, ok) {
    return moves.filter(function (m) { return m.type === type && ok(m); }).reduce(function (s, m) { return s + m.amount; }, 0);
  };
  const all = function () { return true; };
  const cashIn = sum('CASH_IN', all);
  const cashOut = sum('CASH_OUT', all);
  const setor = sum('SETOR', function (m) { return m.status !== 'REJECTED'; });
  const setorPending = sum('SETOR', function (m) { return m.status === 'PENDING'; });
  return {
    cashSales: cashSales, cashIn: cashIn, cashOut: cashOut, setor: setor, setorPending: setorPending,
    expected: shift.opening + cashSales + cashIn - cashOut - setor,
    byMethod: PAYMENT_ORDER.filter(function (k) { return by[k]; }).map(function (k) { return by[k]; }),
    txCount: Object.keys(tx).length, moves: moves
  };
}

function drawerFull_(shift, settings) {
  const max = Math.max(0, numOr_((settings || getSettingsMap_()).Max_Cash_In_Drawer, 0));
  if (!max) return false;
  return shiftNumbers_(shift).expected > max;
}

/** Validates a count { "100000": 3, "50000": 2, ... } and returns its total. */
function readCount_(count) {
  if (!count || typeof count !== 'object') throw new Error('Isi hitungan uang di laci.');
  let total = 0;
  const clean = {};
  CASH_DENOMS.forEach(function (d) {
    const v = count[d] === undefined || count[d] === null || count[d] === '' ? 0 : Number(count[d]);
    if (!Number.isInteger(v) || v < 0 || v > 100000) throw new Error('Jumlah lembar/keping Rp ' + d + ' tidak valid.');
    if (v) { clean[d] = v; total += d * v; }
  });
  return { total: total, json: JSON.stringify(clean) };
}

function shiftState_(user) {
  const canView = hasPerm_(user.role, 'shift.view');
  const canManage = hasPerm_(user.role, 'shift.manage');
  const canConfirm = hasPerm_(user.role, 'cash.confirm');
  const s = getSettingsMap_();
  const cur = currentShift_();
  const last = lastClosedShift_();
  let shift = null;
  if (cur) {
    const n = shiftNumbers_(cur);
    shift = {
      id: cur.id, openedAt: cur.openedAt, openedBy: cur.openedBy, opening: cur.opening, previousLeft: cur.previousLeft,
      openingDiff: cur.openingDiff, txCount: n.txCount,
      moves: n.moves.map(function (m) { delete m.userId; return m; }).reverse(),
      nonCash: n.byMethod.filter(function (m) { return m.method !== 'CASH'; }),
      drawerFull: Math.max(0, numOr_(s.Max_Cash_In_Drawer, 0)) > 0 && n.expected > numOr_(s.Max_Cash_In_Drawer, 0)
    };
    if (canView) {    // blind count: only owner / admin see what SHOULD be in the drawer
      shift.cashSales = n.cashSales; shift.cashIn = n.cashIn; shift.cashOut = n.cashOut; shift.setor = n.setor;
      shift.setorPending = n.setorPending; shift.expected = n.expected; shift.byMethod = n.byMethod;
    }
  }
  let pending = [];
  if (canConfirm) {
    pending = readRecentRows_('Cash_Movements', 400).map(moveFromRow_)
      .filter(function (m) { return m.type === 'SETOR' && m.status === 'PENDING'; }).reverse()
      .map(function (m) { m.mine = m.userId === user.id; delete m.userId; return m; });
  }
  let history = [];
  if (canView) {
    history = readRecentRows_('Shifts', 60).map(shiftFromRow_).filter(function (x) { return x.id && x.status === 'CLOSED'; })
      .reverse().slice(0, 30).map(function (x) { delete x.row; return x; });
  }
  return {
    shift: shift,
    lastClosed: last ? { id: last.id, closedAt: last.closedAt, closedBy: last.closedBy, leftForNext: last.leftForNext } : null,
    denoms: CASH_DENOMS, canManage: canManage, canView: canView, canConfirm: canConfirm,
    required: isTrue_(s.Require_Shift), tolerance: Math.max(0, numOr_(s.Cash_Diff_Tolerance, 0)),
    openBills: (function () { try { return openOrders_().length; } catch (e) { return 0; } })(),
    pending: pending, history: history
  };
}

function apiGetShift(token) {
  return run_(function () {
    return shiftState_(requirePerm_(token, ['shift.manage', 'shift.view', 'cash.confirm']));
  });
}

/** Open a shift: data = { count: { denom: n }, note } */
function apiOpenShift(token, data) {
  return run_(function () {
    const user = requirePerm_(token, 'shift.manage');
    data = data || {};
    const c = readCount_(data.count);
    const note = cleanText_(data.note, 150);
    return withLock_(function () {
      const cur = currentShift_();
      if (cur) throw new Error('Shift sudah dibuka oleh ' + cur.openedBy + ' (' + cur.openedAt.slice(11, 16) + '). Tutup dulu sebelum membuka yang baru.');
      const last = lastClosedShift_();
      const prev = last ? last.leftForNext : null;
      const diff = prev === null ? 0 : c.total - prev;
      const now = new Date();
      const dateKey = fmt_(now, 'yyyyMMdd');
      const id = 'SH-' + dateKey + '-' + String(nextSeq_('SHSEQ_' + dateKey, 1) + 1).padStart(2, '0');
      const stamp = fmt_(now, 'yyyy-MM-dd HH:mm:ss');
      appendObjects_('Shifts', [{
        Shift_ID: id, Date: fmt_(now, 'yyyy-MM-dd'), Status: 'OPEN', Opened_At: stamp, Opened_By: user.name, Opened_By_ID: user.id,
        Opening_Cash: c.total, Opening_Count: c.json, Previous_Left: prev === null ? '' : prev, Opening_Diff: diff,
        Notes: note, Outlet_ID: getSettingsMap_().Outlet_ID || ''
      }]);
      audit_(user, 'SHIFT_OPEN', 'Shift', id, { opening: c.total, previousLeft: prev, diff: diff });
      if (diff !== 0) {
        notify_(user, 'SHIFT_OPEN_DIFF', id, '', diff, note,
                'Modal awal dihitung ' + rpText_(c.total) + ', yang ditinggal shift sebelumnya (' + last.closedBy + ') ' + rpText_(prev) +
                '. Selisih ' + rpText_(diff) + (diff < 0 ? ' (KURANG)' : ' (LEBIH)'));
      }
      return shiftState_(user);
    });
  });
}

function rpText_(n) {
  n = Math.round(Number(n) || 0);
  return (n < 0 ? '-Rp ' : 'Rp ') + String(Math.abs(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}

const CASH_MOVE_WORDS = { CASH_IN: 'Kas masuk', CASH_OUT: 'Kas keluar', SETOR: 'Setor tunai' };

/** Cash in / cash out / setor during the shift: data = { type, amount, reason } */
function apiCashMove(token, data) {
  return run_(function () {
    const user = requirePerm_(token, 'shift.manage');
    data = data || {};
    const type = String(data.type || '');
    if (CASH_MOVE_TYPES.indexOf(type) < 0) throw new Error('Jenis kas tidak dikenal.');
    const amount = Number(data.amount);
    if (!Number.isInteger(amount) || amount <= 0 || amount > 100000000) throw new Error('Isi jumlah uang (angka bulat lebih dari 0).');
    const reason = cleanText_(data.reason, 150);
    if (type === 'CASH_OUT' && reason.length < 3) throw jayaError_('Tulis untuk apa uangnya (contoh: beli es batu, bayar parkir).', 'REASON_NEEDED');
    return withLock_(function () {
      const cur = currentShift_();
      if (!cur) throw jayaError_('Shift kas belum dibuka.', 'NO_SHIFT');
      if (type !== 'CASH_IN' && amount > shiftNumbers_(cur).expected) {
        throw new Error('Jumlahnya lebih besar dari uang tunai yang seharusnya ada di laci. Cek lagi.');
      }
      const now = new Date();
      const dateKey = fmt_(now, 'yyyyMMdd');
      const id = 'CM-' + dateKey + '-' + String(nextSeq_('CMSEQ_' + dateKey, 1) + 1).padStart(4, '0');
      appendObjects_('Cash_Movements', [{
        Movement_ID: id, Shift_ID: cur.id, Timestamp: fmt_(now, 'yyyy-MM-dd HH:mm:ss'), Date: fmt_(now, 'yyyy-MM-dd'), Type: type,
        Amount: amount, Reason: reason || (type === 'CASH_IN' ? 'Tambah modal' : type === 'SETOR' ? 'Setor tunai' : ''),
        User_ID: user.id, User_Name: user.name, Status: type === 'SETOR' ? 'PENDING' : 'OK', Confirmed_By: '', Confirmed_At: '',
        Confirm_Note: '', Count: ''
      }]);
      audit_(user, 'CASH_' + type, 'Shift', cur.id, { id: id, amount: amount, reason: reason });
      notify_(user, type, id, '', amount, reason, CASH_MOVE_WORDS[type] + ' ' + rpText_(amount) +
              (type === 'SETOR' ? ' — menunggu konfirmasi diterima' : ''));
      return shiftState_(user);
    });
  });
}

/** Owner / admin confirm (accept = true) or reject a setor. */
function apiConfirmSetor(token, movementId, accept, note) {
  return run_(function () {
    const user = requirePerm_(token, 'cash.confirm');
    const why = cleanText_(note, 150);
    if (!accept && why.length < 3) throw jayaError_('Tulis alasan menolak setor (contoh: uang kurang Rp 50.000).', 'REASON_NEEDED');
    return withLock_(function () {
      const rows = rowsWhere_('Cash_Movements', 'Movement_ID', String(movementId || ''));
      if (!rows.length) throw new Error('Setor tidak ditemukan.');
      const m = moveFromRow_(rows[0]);
      if (m.type !== 'SETOR' || m.status !== 'PENDING') throw new Error('Setor ini sudah dikonfirmasi.');
      if (m.userId === user.id) throw jayaError_('Setor harus dikonfirmasi oleh orang lain yang menerima uangnya (owner/admin lain).', 'DENIED');
      updateRow_('Cash_Movements', rows[0]._row, { Status: accept ? 'RECEIVED' : 'REJECTED', Confirmed_By: user.name,
                                                   Confirmed_At: nowStamp_(), Confirm_Note: why });
      audit_(user, accept ? 'SETOR_RECEIVED' : 'SETOR_REJECTED', 'Cash', m.id, { amount: m.amount, from: m.user, note: why });
      return shiftState_(user);
    });
  });
}

/**
 * Close the shift with a blind count. data = { count, leave, note }
 *  leave = cash left in the drawer as modal for the next shift; the rest is a final setor (PENDING).
 */
function apiCloseShift(token, data) {
  return run_(function () {
    const user = requirePerm_(token, 'shift.manage');
    data = data || {};
    const c = readCount_(data.count);
    const leave = Number(data.leave);
    if (!Number.isInteger(leave) || leave < 0) throw new Error('Isi modal yang ditinggal di laci untuk shift berikutnya (boleh 0).');
    if (leave > c.total) throw new Error('Modal yang ditinggal lebih besar dari uang yang dihitung.');
    const note = cleanText_(data.note, 150);
    return withLock_(function () {
      const cur = currentShift_();
      if (!cur) throw new Error('Tidak ada shift yang terbuka.');
      const n = shiftNumbers_(cur);
      const diff = c.total - n.expected;
      const finalSetor = c.total - leave;
      const now = new Date();
      const stamp = fmt_(now, 'yyyy-MM-dd HH:mm:ss');
      updateRow_('Shifts', cur.row, {
        Status: 'CLOSED', Closed_At: stamp, Closed_By: user.name, Closed_By_ID: user.id, Cash_Sales: n.cashSales, Cash_In: n.cashIn,
        Cash_Out: n.cashOut, Setor_Total: n.setor, Expected_Cash: n.expected, Counted_Cash: c.total, Difference: diff,
        Closing_Count: c.json, Left_For_Next: leave, Final_Setor: finalSetor, Tx_Count: n.txCount,
        Non_Cash: JSON.stringify(n.byMethod.map(function (m) { return { m: m.method, t: m.total, n: m.count }; })),
        Notes: [cur.notes, note].filter(String).join(' | ').slice(0, 300)
      });
      if (finalSetor > 0) {
        const dateKey = fmt_(now, 'yyyyMMdd');
        appendObjects_('Cash_Movements', [{
          Movement_ID: 'CM-' + dateKey + '-' + String(nextSeq_('CMSEQ_' + dateKey, 1) + 1).padStart(4, '0'), Shift_ID: cur.id,
          Timestamp: stamp, Date: fmt_(now, 'yyyy-MM-dd'), Type: 'SETOR', Amount: finalSetor, Reason: 'Setor tutup shift',
          User_ID: user.id, User_Name: user.name, Status: 'PENDING', Confirmed_By: '', Confirmed_At: '', Confirm_Note: '', Count: ''
        }]);
      }
      const tol = Math.max(0, numOr_(getSettingsMap_().Cash_Diff_Tolerance, 0));
      const flagged = Math.abs(diff) > tol;
      audit_(user, 'SHIFT_CLOSE', 'Shift', cur.id, { expected: n.expected, counted: c.total, diff: diff, leave: leave, setor: finalSetor });
      notify_(user, flagged ? 'SHIFT_DIFF' : 'SHIFT_CLOSED', cur.id, '', diff, note,
              'Uang dihitung ' + rpText_(c.total) + ', seharusnya ' + rpText_(n.expected) + ' → selisih ' + rpText_(diff) +
              (diff < 0 ? ' (KURANG)' : diff > 0 ? ' (LEBIH)' : '') + '. Setor ' + rpText_(finalSetor) + ' (menunggu konfirmasi), modal ditinggal ' +
              rpText_(leave) + '. ' + n.txCount + ' transaksi.');
      const state = shiftState_(user);
      state.closed = { id: cur.id, expected: n.expected, counted: c.total, difference: diff, finalSetor: finalSetor, leave: leave,
                       flagged: flagged, cashSales: n.cashSales, txCount: n.txCount };
      return state;
    });
  });
}

/** Full detail of one shift (owner / admin). */
function apiGetShiftDetail(token, shiftId) {
  return run_(function () {
    requirePerm_(token, 'shift.view');
    const rows = rowsWhere_('Shifts', 'Shift_ID', String(shiftId || ''));
    if (!rows.length) throw new Error('Shift tidak ditemukan.');
    const s = shiftFromRow_(rows[0]);
    const n = shiftNumbers_(s);
    delete s.row;
    s.byMethod = n.byMethod;
    if (s.status === 'OPEN') {
      s.cashSales = n.cashSales; s.cashIn = n.cashIn; s.cashOut = n.cashOut; s.setor = n.setor; s.expected = n.expected; s.txCount = n.txCount;
    }
    s.moves = n.moves.map(function (m) { delete m.userId; return m; });
    let open = {}, close = {};
    try { open = JSON.parse(String(rows[0].Opening_Count || '{}')); } catch (e) { open = {}; }
    try { close = JSON.parse(String(rows[0].Closing_Count || '{}')); } catch (e) { close = {}; }
    s.openingCount = open;
    s.closingCount = close;
    return s;
  });
}

/**
 * Tables.gs
 * Floor plan, table layout editing, and open table bills (dine-in).
 *
 * How a table bill works:
 *  1. Staff taps a free table, types the pax and (optionally) the guest's name -> a bill is opened
 *     (Open_Orders, Status OPEN).
 *  2. Items are added and "Simpan ke meja" stores them on the bill. Every save that adds items is a new
 *     ROUND ("Pesanan 1", "Pesanan 2", ...) with its time and who took it, and is sent to the kitchen / bar
 *     screens as a new ticket. Saved lines are never mixed with new ones.
 *  3. Saved lines can only be REDUCED (= void item, needs a reason + note to the admin / owner).
 *     More of the same product is always a new line in a new round.
 *  4. "Bayar" completes the sale. A bill can be paid in parts ("split per item") or shared equally
 *     ("bagi rata", see Pos.gs). Two bills can be merged into one ("Gabung bill").
 * Every bill has a Version number. If two phones edit the same bill, the second save is
 * refused and reloaded, so nobody overwrites someone else's items.
 *
 * A saved line (Items_JSON): { lid, id, name, qty, price, disc, note, grp, round, at, by, from }
 *   lid = line id, grp = FOOD / BEVERAGE / NONE (kitchen or bar), round = order round,
 *   at = time ordered, by = who took the order, from = table it came from after "Gabung bill".
 */

function tablesList_() {
  return readTable_('Tables').rows.map(function (r) {
    const shape = String(r.Shape || 'SQUARE').trim().toUpperCase();
    return {
      row: r._row,
      id: String(r.Table_ID).trim(),
      name: String(r.Table_Name).trim(),
      area: String(r.Area || '').trim() || 'Indoor',
      seats: Math.max(0, parseInt(r.Seats, 10) || 0),
      shape: TABLE_SHAPES.indexOf(shape) >= 0 ? shape : 'SQUARE',
      x: clamp_(numOr_(r.Pos_X, 5), 0, 95),
      y: clamp_(numOr_(r.Pos_Y, 5), 0, 95),
      w: clamp_(numOr_(r.Width, 18), 6, 60),
      h: clamp_(numOr_(r.Height, 18), 6, 60),
      active: isTrue_(r.Active)
    };
  }).filter(function (t) { return t.id && t.name; });
}

function clamp_(n, lo, hi) { return Math.max(lo, Math.min(hi, n)); }

/** Makes stored lines complete (bills saved by v2 have no line id / round). */
function normalizeLines_(items) {
  const seen = {};
  return (Array.isArray(items) ? items : []).map(function (i, k) {
    let lid = cleanLid_(i && i.lid) || ('OLD' + k);
    while (seen[lid]) lid = lid + 'x';
    seen[lid] = true;
    return {
      lid: lid, id: String(i.id || ''), name: String(i.name || ''), qty: Number(i.qty) || 0, price: Number(i.price) || 0,
      disc: i.disc && i.disc.value ? i.disc : null, note: String(i.note || ''), grp: String(i.grp || ''),
      round: Number(i.round) || 1, at: String(i.at || ''), by: String(i.by || ''), from: String(i.from || '')
    };
  }).filter(function (i) { return i.id && i.qty > 0; });
}

function orderFromRow_(r) {
  let items = [];
  try { items = JSON.parse(String(r.Items_JSON || '[]')) || []; } catch (e) { items = []; }
  const paid = String(r.Paid_Transactions || '').split(',').map(function (x) { return x.trim(); }).filter(String);
  return {
    row: r._row,
    id: String(r.Order_ID).trim(),
    tableId: String(r.Table_ID).trim(),
    tableName: String(r.Table_Name).trim(),
    pax: Number(r.Pax) || 0,
    guestName: String(r.Guest_Name || '').trim(),
    status: String(r.Status || '').trim().toUpperCase(),
    items: normalizeLines_(items),
    subtotal: moneyNum_(r.Subtotal) || 0,
    openedAt: cellText_(r.Opened_At),
    openedMs: Number(r.Opened_Ms) || 0,
    openedBy: String(r.Opened_By || ''),
    updatedBy: String(r.Updated_By || ''),
    version: Number(r.Version) || 0,
    transactionId: String(r.Transaction_ID || ''),
    paidTx: paid,
    mergedInto: String(r.Merged_Into || '')
  };
}

function openOrders_() {
  const sh = getSheet_('Open_Orders');
  const headers = getHeaders_(sh);
  return findRowNumbers_(sh, headers, 'Status', 'OPEN').map(function (n) { return orderFromRow_(rowObject_(sh, headers, n)); });
}

function getOpenOrder_(orderId) {
  const sh = getSheet_('Open_Orders');
  const headers = getHeaders_(sh);
  const rows = findRowNumbers_(sh, headers, 'Order_ID', String(orderId || ''));
  return rows.length ? orderFromRow_(rowObject_(sh, headers, rows[0])) : null;
}

/** What the phone needs to show a bill. */
function publicOrder_(o) {
  return { id: o.id, tableId: o.tableId, tableName: o.tableName, pax: o.pax, guestName: o.guestName, status: o.status,
           items: o.items, subtotal: o.subtotal, openedAt: o.openedAt, openedMs: o.openedMs, openedBy: o.openedBy,
           updatedBy: o.updatedBy, version: o.version, paidCount: o.paidTx.length };
}

function floorData_(user) {
  const tables = tablesList_().filter(function (t) { return t.active; });
  const open = {};
  openOrders_().forEach(function (o) {
    if (!open[o.tableId]) {
      open[o.tableId] = { orderId: o.id, pax: o.pax, guest: o.guestName, subtotal: o.subtotal,
                          items: o.items.reduce(function (s, i) { return s + (Number(i.qty) || 0); }, 0),
                          rounds: o.items.reduce(function (m, i) { return Math.max(m, i.round); }, 0), paidCount: o.paidTx.length,
                          openedMs: o.openedMs, openedBy: o.openedBy, version: o.version, tableName: o.tableName };
    }
  });
  const areas = listSetting_('Table_Areas');
  tables.forEach(function (t) { if (areas.indexOf(t.area) < 0) areas.push(t.area); });
  return {
    areas: areas,
    tables: tables.map(function (t) {
      return { id: t.id, name: t.name, area: t.area, seats: t.seats, shape: t.shape, x: t.x, y: t.y, w: t.w, h: t.h };
    }),
    open: open,
    canServe: hasPerm_(user.role, 'tables.serve'),
    canEditLayout: hasPerm_(user.role, 'tables.layout'),
    serverNow: Date.now()
  };
}

function apiGetFloor(token) {
  return run_(function () {
    return floorData_(requirePerm_(token, ['tables.serve', 'tables.layout']));
  });
}

function checkPax_(pax) {
  const p = Number(pax);
  if (!Number.isInteger(p) || p < 1 || p > 99) throw new Error('Jumlah tamu (pax) harus angka 1 sampai 99.');
  return p;
}

function nextOrderId_() {
  const dateKey = fmt_(new Date(), 'yyyyMMdd');
  const props = PropertiesService.getScriptProperties();
  const key = 'ORDSEQ_' + dateKey;
  let seq = Number(props.getProperty(key) || 0);
  let id;
  do { seq++; id = 'ORD-' + dateKey + '-' + String(seq).padStart(3, '0'); } while (getOpenOrder_(id));
  props.setProperty(key, String(seq));
  return id;
}

/** Opens a bill on a free table, or returns the bill already open on it. */
function apiOpenTable(token, tableId, pax, guestName) {
  return run_(function () {
    const user = requirePerm_(token, 'tables.serve');
    const p = checkPax_(pax);
    const guest = cleanGuest_(guestName);
    return withLock_(function () {
      const table = tablesList_().filter(function (t) { return t.id === String(tableId) && t.active; })[0];
      if (!table) throw new Error('Meja ini sudah tidak ada. Muat ulang layar Meja.');
      const existing = openOrders_().filter(function (o) { return o.tableId === table.id; })[0];
      if (existing) {
        const r = publicOrder_(existing);
        r.alreadyOpen = true;
        return r;
      }
      const now = new Date();
      const stamp = fmt_(now, 'yyyy-MM-dd HH:mm:ss');
      const id = nextOrderId_();
      appendObjects_('Open_Orders', [{
        Order_ID: id, Table_ID: table.id, Table_Name: table.name, Pax: p, Status: 'OPEN', Items_JSON: '[]',
        Subtotal: 0, Opened_At: stamp, Opened_Ms: now.getTime(), Opened_By: user.name, Updated_At: stamp,
        Updated_By: user.name, Version: 1, Transaction_ID: '', Closed_At: '', Guest_Name: guest, Paid_Transactions: '',
        Merged_Into: ''
      }]);
      audit_(user, 'TABLE_OPEN', 'Order', id, { table: table.name, pax: p, guest: guest });
      return publicOrder_(getOpenOrder_(id));
    });
  });
}

function apiGetOpenOrder(token, orderId) {
  return run_(function () {
    requirePerm_(token, 'tables.serve');
    const o = getOpenOrder_(orderId);
    if (!o) throw new Error('Bill tidak ditemukan. Muat ulang layar Meja.');
    if (o.status !== 'OPEN') throw new Error('Bill ini sudah ' + statusWord_(o.status) + '.');
    return publicOrder_(o);
  });
}

function checkReason_(reason) {
  const r = cleanText_(reason, 150);
  if (r.length < 3) throw jayaError_('Tulis alasan void (contoh: salah input, tamu batal, makanan rusak).', 'REASON_NEEDED');
  return r;
}

function linesValue_(lines) {
  return lines.reduce(function (s, l) {
    const gross = (Number(l.price) || 0) * l.qty;
    return s + gross - Math.min(gross, discountAmount_(l.disc, gross));
  }, 0);
}

/**
 * Saves a table bill ("Simpan ke meja").
 * data: { orderId, version, pax, guestName, voidReason, lines: [{ lid, productId, qty, disc, note }] }
 *  - lines already on the bill keep their round / time / note; their qty may only go DOWN (void, needs reason)
 *  - lines with a new lid are a new round: sent to the kitchen / bar screens
 */
function apiSaveOpenOrder(token, data) {
  return run_(function () {
    const user = requirePerm_(token, 'tables.serve');
    data = data || {};
    const p = checkPax_(data.pax);
    const guest = cleanGuest_(data.guestName);
    const incoming = parseLines_(data.lines || data.items || [], true);
    const products = productMap_();
    const canDiscount = hasPerm_(user.role, 'pos.sell');
    return withLock_(function () {
      const o = getOpenOrder_(data.orderId);
      if (!o) throw new Error('Bill tidak ditemukan. Muat ulang layar Meja.');
      if (o.status !== 'OPEN') throw jayaError_('Bill ini sudah ' + statusWord_(o.status) + '.', 'STALE');
      if (o.version !== Number(data.version)) {
        throw jayaError_('Bill ini baru diubah di HP lain (oleh ' + o.updatedBy + '). Bill sudah dimuat ulang. Cek lagi lalu simpan.', 'STALE');
      }
      const inByLid = {};
      incoming.forEach(function (l) {
        if (!l.lid) throw new Error('Data baris pesanan tidak lengkap. Muat ulang JayaPOS.');
        if (inByLid[l.lid]) throw new Error('Ada baris pesanan ganda. Muat ulang JayaPOS.');
        inByLid[l.lid] = l;
      });
      const storedByLid = {};
      o.items.forEach(function (s) { storedByLid[s.lid] = s; });

      const now = new Date();
      const out = [], removed = [], added = [];
      o.items.forEach(function (s) {
        const inc = inByLid[s.lid];
        if (!inc) { removed.push(Object.assign({}, s)); return; }
        if (inc.productId !== s.id) throw jayaError_('Data bill tidak cocok. Bill sudah dimuat ulang.', 'STALE');
        if (inc.qty > s.qty) {
          throw jayaError_('Untuk menambah ' + s.name + ', ketuk produknya lagi supaya masuk sebagai pesanan baru (dapur perlu tahu).', 'STALE');
        }
        if (inc.qty < s.qty) removed.push(Object.assign({}, s, { qty: s.qty - inc.qty }));
        const prod = products[s.id];
        const line = Object.assign({}, s, { qty: inc.qty, price: prod ? prod.price : s.price, grp: s.grp || (prod ? prod.recipeGroup : 'NONE') });
        if (canDiscount) line.disc = inc.disc;
        out.push(line);
      });
      const round = o.items.reduce(function (m, i) { return Math.max(m, i.round); }, 0) + 1;
      incoming.forEach(function (l) {
        if (storedByLid[l.lid]) return;
        const prod = products[l.productId];
        if (!prod) throw jayaError_('Ada produk di keranjang yang sudah tidak tersedia (' + l.productId + '). Menu akan dimuat ulang.', 'PRICE_CHANGED');
        const line = { lid: l.lid, id: prod.id, name: prod.name, qty: l.qty, price: prod.price, disc: canDiscount ? l.disc : null,
                       note: l.note, grp: prod.recipeGroup, round: round, at: fmt_(now, 'HH:mm'), by: user.name, from: '' };
        out.push(line);
        added.push(line);
      });

      out.forEach(function (l) {
        if (l.disc && l.disc.type === 'AMT' && l.disc.value > l.price * l.qty) throw new Error('Diskon untuk ' + l.name + ' lebih besar dari harganya.');
      });
      const priced = out.map(function (l) { return { total: l.price * l.qty, disc: l.disc }; });
      const tot = calcTotals_(priced, {}, chargeSettings_());
      checkDiscountAllowed_(user, tot, priced, null);

      const reason = removed.length ? checkReason_(data.voidReason) : '';
      const stamp = fmt_(now, 'yyyy-MM-dd HH:mm:ss');
      updateRow_('Open_Orders', o.row, {
        Items_JSON: JSON.stringify(out), Subtotal: tot.itemsNet, Pax: p, Guest_Name: guest,
        Updated_At: stamp, Updated_By: user.name, Version: o.version + 1
      });
      const info = { orderId: o.id, tableName: o.tableName, guest: guest, user: user };
      if (added.length) createTicket_(Object.assign({ round: round, kind: 'ORDER' }, info), added, products);
      if (removed.length) {
        createTicket_(Object.assign({ round: 0, kind: 'VOID', reason: reason }, info), removed, products);
        const amount = linesValue_(removed);
        audit_(user, 'VOID_ITEM', 'Order', o.id, { table: o.tableName, items: removed.map(function (x) { return { name: x.name, qty: x.qty, round: x.round }; }), reason: reason });
        notify_(user, 'VOID_ITEM', o.id, o.tableName, amount, reason,
                removed.map(function (x) { return x.qty + 'x ' + x.name + ' (pesanan ' + x.round + ')'; }).join(', '));
      }
      if (p !== o.pax) audit_(user, 'ORDER_PAX_CHANGE', 'Order', o.id, { table: o.tableName, from: o.pax, to: p });
      const res = publicOrder_(getOpenOrder_(o.id));
      res.addedRound = added.length ? round : 0;
      return res;
    });
  });
}

/**
 * Closes a bill without payment.
 *  - Empty bill (no items): just frees the table.
 *  - Bill with items = VOID BILL: needs a reason and sends a note to the admin / owner (and a "BATAL" to the kitchen).
 */
function apiCancelOpenOrder(token, orderId, version, reason) {
  return run_(function () {
    const user = requirePerm_(token, 'tables.serve');
    return withLock_(function () {
      const o = getOpenOrder_(orderId);
      if (!o || o.status !== 'OPEN') throw new Error('Bill ini sudah tidak terbuka.');
      if (o.version !== Number(version)) throw jayaError_('Bill ini baru diubah di HP lain. Bill sudah dimuat ulang.', 'STALE');
      const hasItems = o.items.length > 0;
      const why = hasItems ? checkReason_(reason) : '';
      const stamp = nowStamp_();
      updateRow_('Open_Orders', o.row, { Status: 'CANCELLED', Closed_At: stamp, Updated_At: stamp, Updated_By: user.name,
                                         Version: o.version + 1 });
      audit_(user, hasItems ? 'VOID_BILL' : 'ORDER_CANCEL', 'Order', o.id, { table: o.tableName, items: o.items, reason: why });
      if (hasItems) {
        createTicket_({ orderId: o.id, tableName: o.tableName, guest: o.guestName, user: user, round: 0, kind: 'VOID', reason: why }, o.items);
        notify_(user, 'VOID_BILL', o.id, o.tableName, linesValue_(o.items), why,
                o.items.map(function (i) { return i.qty + 'x ' + i.name; }).join(', ') + ' · ' + o.pax + ' pax' +
                (o.guestName ? ' · ' + o.guestName : ''));
      }
      return true;
    });
  });
}

/** Moves a bill to another free table. */
function apiMoveOpenOrder(token, orderId, version, newTableId) {
  return run_(function () {
    const user = requirePerm_(token, 'tables.serve');
    return withLock_(function () {
      const o = getOpenOrder_(orderId);
      if (!o || o.status !== 'OPEN') throw new Error('Bill ini sudah tidak terbuka.');
      if (o.version !== Number(version)) throw jayaError_('Bill ini baru diubah di HP lain. Bill sudah dimuat ulang.', 'STALE');
      const table = tablesList_().filter(function (t) { return t.id === String(newTableId) && t.active; })[0];
      if (!table) throw new Error('Meja itu tidak ada.');
      if (openOrders_().some(function (x) { return x.tableId === table.id; })) throw new Error(table.name + ' sudah punya bill terbuka. Pakai "Gabung bill" kalau mau digabung.');
      updateRow_('Open_Orders', o.row, { Table_ID: table.id, Table_Name: table.name, Updated_At: nowStamp_(),
                                         Updated_By: user.name, Version: o.version + 1 });
      audit_(user, 'ORDER_MOVE_TABLE', 'Order', o.id, { from: o.tableName, to: table.name });
      return publicOrder_(getOpenOrder_(o.id));
    });
  });
}

/**
 * Gabung bill: moves every line of the SOURCE bill into the TARGET bill (the one open on the phone).
 * The source table becomes free. Pax are added up, guest names joined, each line remembers its table.
 */
function apiMergeOrders(token, targetId, targetVersion, sourceId) {
  return run_(function () {
    const user = requirePerm_(token, 'tables.serve');
    return withLock_(function () {
      const t = getOpenOrder_(targetId);
      const s = getOpenOrder_(sourceId);
      if (!t || t.status !== 'OPEN') throw new Error('Bill ini sudah tidak terbuka.');
      if (!s || s.status !== 'OPEN') throw jayaError_('Bill meja yang mau digabung sudah tidak terbuka. Muat ulang.', 'STALE');
      if (t.id === s.id) throw new Error('Pilih meja lain untuk digabung.');
      if (t.version !== Number(targetVersion)) throw jayaError_('Bill ini baru diubah di HP lain. Bill sudah dimuat ulang.', 'STALE');
      const used = {};
      t.items.forEach(function (i) { used[i.lid] = true; });
      const moved = s.items.map(function (i) {
        let lid = i.lid;
        while (used[lid]) lid = ('M' + Utilities.getUuid().replace(/-/g, '')).slice(0, 12);
        used[lid] = true;
        return Object.assign({}, i, { lid: lid, from: i.from || s.tableName });
      });
      const items = t.items.concat(moved);
      const guests = [t.guestName, s.guestName].filter(String);
      const pax = Math.min(99, t.pax + s.pax);
      const stamp = nowStamp_();
      updateRow_('Open_Orders', t.row, {
        Items_JSON: JSON.stringify(items), Subtotal: linesValue_(items), Pax: pax, Guest_Name: guests.join(' + ').slice(0, 80),
        Paid_Transactions: t.paidTx.concat(s.paidTx).join(','), Updated_At: stamp, Updated_By: user.name, Version: t.version + 1
      });
      updateRow_('Open_Orders', s.row, { Status: 'MERGED', Merged_Into: t.id, Closed_At: stamp, Updated_At: stamp,
                                         Updated_By: user.name, Version: s.version + 1 });
      audit_(user, 'ORDER_MERGE', 'Order', t.id, { into: t.tableName, from: s.tableName, fromOrder: s.id, items: s.items.length });
      return publicOrder_(getOpenOrder_(t.id));
    });
  });
}

/** Saves the whole floor plan from the layout editor (admin). */
function apiSaveLayout(token, list) {
  return run_(function () {
    const user = requirePerm_(token, 'tables.layout');
    if (!Array.isArray(list) || list.length > 200) throw new Error('Data denah tidak valid.');
    const clean = list.map(function (t) {
      const name = cleanText_(t && t.name, 20);
      if (!name) throw new Error('Setiap meja harus punya nama.');
      const shape = String(t.shape || 'SQUARE').toUpperCase();
      if (TABLE_SHAPES.indexOf(shape) < 0) throw new Error('Bentuk meja ' + name + ' tidak dikenal.');
      const seats = Number(t.seats);
      if (!Number.isInteger(seats) || seats < 1 || seats > 50) throw new Error('Jumlah kursi ' + name + ' harus 1 sampai 50.');
      return {
        id: String(t.id || '').trim(), name: name, area: cleanText_(t.area, 30) || 'Indoor', seats: seats, shape: shape,
        w: Math.round(clamp_(numOr_(t.w, 18), 6, 60)), h: Math.round(clamp_(numOr_(t.h, 18), 6, 60)),
        x: 0, y: 0, rawX: numOr_(t.x, 5), rawY: numOr_(t.y, 5)
      };
    });
    clean.forEach(function (t) {
      t.x = Math.round(clamp_(t.rawX, 0, 100 - t.w));
      t.y = Math.round(clamp_(t.rawY, 0, 100 - t.h));
    });
    const seen = {};
    clean.forEach(function (t) {
      const k = t.area.toLowerCase() + '|' + t.name.toLowerCase();
      if (seen[k]) throw new Error('Ada dua meja bernama "' + t.name + '" di ' + t.area + '.');
      seen[k] = true;
    });

    return withLock_(function () {
      const existing = tablesList_();
      const byId = {};
      existing.forEach(function (t) { byId[t.id] = t; });
      const busy = {};
      openOrders_().forEach(function (o) { busy[o.tableId] = true; });
      const keep = {};
      clean.forEach(function (t) { if (t.id && byId[t.id]) keep[t.id] = true; });
      const removed = [];
      existing.forEach(function (t) {
        if (t.active && !keep[t.id]) {
          if (busy[t.id]) throw new Error('Meja ' + t.name + ' masih punya bill terbuka, jadi tidak bisa dihapus. Bayar atau void bill-nya dulu.');
          removed.push(t);
        }
      });

      const stamp = nowStamp_();
      const ids = existing.map(function (t) { return t.id; });
      const added = [];
      clean.forEach(function (t) {
        const fields = { Table_Name: t.name, Area: t.area, Seats: t.seats, Shape: t.shape, Pos_X: t.x, Pos_Y: t.y,
                         Width: t.w, Height: t.h, Active: true, Updated_At: stamp };
        const old = t.id && byId[t.id];
        if (old) {
          const same = old.name === t.name && old.area === t.area && old.seats === t.seats && old.shape === t.shape &&
                       Math.round(old.x) === t.x && Math.round(old.y) === t.y && Math.round(old.w) === t.w &&
                       Math.round(old.h) === t.h && old.active;
          if (!same) updateRow_('Tables', old.row, fields);
          if (old.name !== t.name && busy[old.id]) {
            const o = openOrders_().filter(function (x) { return x.tableId === old.id; })[0];
            if (o) updateRow_('Open_Orders', o.row, { Table_Name: t.name });
          }
        } else {
          const id = nextId_(ids, 'T', 2);
          ids.push(id);
          fields.Table_ID = id;
          appendObjects_('Tables', [fields]);
          added.push(t.name);
        }
      });
      removed.forEach(function (t) { updateRow_('Tables', t.row, { Active: false, Updated_At: stamp }); });
      audit_(user, 'TABLE_LAYOUT_SAVE', 'Tables', '', { tables: clean.length, added: added, removed: removed.map(function (t) { return t.name; }) });
      return floorData_(user);
    });
  });
}

/**
 * Updater.gs
 * Installs a new JayaPOS version without copy-pasting files:
 *  - in the app: ☰ → Pengaturan → "Cek update" → "Update sekarang" (admin, works from a phone), or
 *  - in the Sheet: JayaPOS → 4. Update aplikasi.
 *
 * How it works:
 *  1. A new version is ONE file (update bundle). It is taken from the newest of:
 *     - GitHub: the address in the setting Update_Source (the owner's own repository), and
 *     - Google Drive: files named  JayaPOS-update-<version>.json  in the folder "JayaPOS Updates".
 *  2. The updater shows the version and notes and asks for confirmation.
 *  3. It saves a backup of the current code in the same folder (JayaPOS-backup-<version>-<time>.json),
 *     replaces the code through the Google Apps Script API, makes a new version, and points the web app
 *     link (/exec) at it. The link does not change.
 *  4. New sheets / columns are added automatically the first time the new version opens (autoMigrate_).
 *  "5. Kembalikan ke backup terakhir" puts the previous code back if something goes wrong.
 *
 * One-time requirement: turn ON "Google Apps Script API" at https://script.google.com/home/usersettings
 * (with the same Google account that owns the Sheet).
 *
 * Update file format: { app: 'JayaPOS', version: '3.1.0', notes: '...', mode: 'partial' | 'full',
 *   files: [{ name: 'Pos', type: 'SERVER_JS' | 'HTML' | 'JSON', source: '...' }], remove: ['OldFile'] }
 *   partial = only the listed files change; full = the project becomes exactly the listed files.
 */

const UPDATE_FOLDER_NAME = 'JayaPOS Updates';
const UPDATE_PREFIX = 'JayaPOS-update-';
const BACKUP_PREFIX = 'JayaPOS-backup-';
const MUST_HAVE_FILES = ['appsscript', 'Code', 'Config', 'Updater'];
/** Used when the Settings sheet has no Update_Source row yet (first install of the updater). */
const DEFAULT_UPDATE_SOURCE = 'https://raw.githubusercontent.com/odeliasabrina24-byte/jayapos/main/update.json';

function versionNum_(v) {
  const p = String(v || '0').split('.').map(function (x) { return parseInt(x, 10) || 0; });
  return (p[0] || 0) * 1000000 + (p[1] || 0) * 1000 + (p[2] || 0);
}

function updateFolder_(create) {
  const it = DriveApp.getFoldersByName(UPDATE_FOLDER_NAME);
  if (it.hasNext()) return it.next();
  return create ? DriveApp.createFolder(UPDATE_FOLDER_NAME) : null;
}

/** Reads every update (or backup) file in the folder. Returns [{ file, name, bundle }], newest version first. */
function listBundles_(prefix) {
  const folder = updateFolder_(false);
  if (!folder) return [];
  const out = [];
  const files = folder.getFiles();
  while (files.hasNext()) {
    const f = files.next();
    const name = f.getName();
    if (name.indexOf(prefix) !== 0 || !/\.json$/i.test(name) || f.isTrashed()) continue;
    let bundle = null;
    try { bundle = JSON.parse(f.getBlob().getDataAsString('UTF-8')); } catch (e) { continue; }
    if (!bundle || bundle.app !== 'JayaPOS' || !Array.isArray(bundle.files)) continue;
    out.push({ file: f, name: name, bundle: bundle, time: f.getDateCreated().getTime() });
  }
  out.sort(function (a, b) { return versionNum_(b.bundle.version) - versionNum_(a.bundle.version) || b.time - a.time; });
  return out;
}

function checkBundle_(b) {
  if (!b || b.app !== 'JayaPOS' || !Array.isArray(b.files) || !/^\d+\.\d+\.\d+$/.test(String(b.version || ''))) {
    throw new Error('File update tidak valid.');
  }
  return b;
}

/** The update bundle on GitHub (Update_Source), or null when not set / not reachable. */
function githubBundle_() {
  const set = getSettingsMap_().Update_Source;
  const url = String(set === undefined ? DEFAULT_UPDATE_SOURCE : set || '').trim();
  if (!url) return null;
  if (!/^https:\/\/raw\.githubusercontent\.com\//.test(url)) throw new Error('Sumber update harus alamat raw.githubusercontent.com.');
  const res = UrlFetchApp.fetch(url + (url.indexOf('?') >= 0 ? '&' : '?') + 't=' + Date.now(), { muteHttpExceptions: true });
  if (res.getResponseCode() === 404) return null;
  if (res.getResponseCode() !== 200) throw new Error('GitHub tidak bisa dibuka (' + res.getResponseCode() + ').');
  return checkBundle_(JSON.parse(res.getContentText('UTF-8')));
}

/** Newest update from GitHub or the Drive folder: { bundle, source } or null. */
function latestUpdate_() {
  const found = [];
  let ghError = '';
  try { const g = githubBundle_(); if (g) found.push({ bundle: g, source: 'GitHub' }); }
  catch (e) { ghError = String(e && e.message || e); }
  try { const d = listBundles_(UPDATE_PREFIX)[0]; if (d) found.push({ bundle: d.bundle, source: 'Drive: ' + d.name }); }
  catch (e) { /* no Drive folder */ }
  found.sort(function (a, b) { return versionNum_(b.bundle.version) - versionNum_(a.bundle.version); });
  if (!found.length && ghError) throw new Error(ghError);
  return found[0] || null;
}

/** Runs the database setup once after a new version is installed (new sheets, columns, settings). */
function autoMigrate_() {
  const props = PropertiesService.getScriptProperties();
  if (props.getProperty('SCHEMA_VERSION') === APP_VERSION) return false;
  if (!props.getProperty('SPREADSHEET_ID')) return false;    // never set up: the owner runs Setup from the Sheet
  return withLock_(function () {
    if (props.getProperty('SCHEMA_VERSION') === APP_VERSION) return false;
    setupDatabase_();
    return true;
  });
}

/** Calls the Apps Script API with the owner's login. */
function scriptApi_(method, path, body) {
  const res = UrlFetchApp.fetch('https://script.googleapis.com/v1/projects/' + ScriptApp.getScriptId() + path, {
    method: method,
    contentType: 'application/json',
    headers: { Authorization: 'Bearer ' + ScriptApp.getOAuthToken() },
    payload: body ? JSON.stringify(body) : undefined,
    muteHttpExceptions: true
  });
  const code = res.getResponseCode();
  const text = res.getContentText();
  if (code >= 200 && code < 300) return text ? JSON.parse(text) : {};
  let msg = text;
  try { msg = JSON.parse(text).error.message; } catch (e) { /* not JSON */ }
  if (/Apps Script API|has not been used|is disabled|not enabled/i.test(msg)) {
    throw new Error('Google Apps Script API belum dinyalakan. Buka https://script.google.com/home/usersettings , ' +
                    'nyalakan "Google Apps Script API", tunggu 1 menit, lalu coba lagi.');
  }
  throw new Error('Google menolak (' + code + '): ' + msg);
}

function checkBundleFiles_(files) {
  files.forEach(function (f) {
    if (!/^[A-Za-z0-9_]{1,60}$/.test(String(f.name || ''))) throw new Error('Nama file tidak valid di update: ' + f.name);
    if (['SERVER_JS', 'HTML', 'JSON'].indexOf(f.type) < 0) throw new Error('Jenis file tidak valid: ' + f.name);
    if (typeof f.source !== 'string' || !f.source.length) throw new Error('File kosong di update: ' + f.name);
    if (f.type === 'JSON' && f.name !== 'appsscript') throw new Error('Hanya appsscript boleh berjenis JSON.');
  });
}

/** Merges the update into the current files and checks the result can still update itself. */
function mergeFiles_(current, bundle) {
  checkBundleFiles_(bundle.files);
  let out = bundle.mode === 'full' ? [] : current.map(function (f) { return { name: f.name, type: f.type, source: f.source }; });
  const remove = Array.isArray(bundle.remove) ? bundle.remove.map(String) : [];
  out = out.filter(function (f) { return remove.indexOf(f.name) < 0 || MUST_HAVE_FILES.indexOf(f.name) >= 0; });
  bundle.files.forEach(function (nf) {
    const i = out.map(function (f) { return f.name; }).indexOf(nf.name);
    const copy = { name: nf.name, type: nf.type, source: nf.source };
    if (i >= 0) out[i] = copy; else out.push(copy);
  });
  MUST_HAVE_FILES.forEach(function (n) {
    if (!out.some(function (f) { return f.name === n; })) throw new Error('Update ini tidak lengkap (tidak ada ' + n + '). Tidak dipasang.');
  });
  const manifest = out.filter(function (f) { return f.name === 'appsscript'; })[0];
  let m;
  try { m = JSON.parse(manifest.source); } catch (e) { throw new Error('appsscript.json di update rusak. Tidak dipasang.'); }
  const scopes = m.oauthScopes || [];
  if (scopes.indexOf('https://www.googleapis.com/auth/script.projects') < 0 || scopes.indexOf('https://www.googleapis.com/auth/script.deployments') < 0) {
    throw new Error('appsscript.json di update tidak mengizinkan update otomatis berikutnya. Tidak dipasang.');
  }
  return out;
}

/** Installs a bundle. Returns a short summary. */
function applyBundle_(bundle, isRollback) {
  const current = scriptApi_('get', '/content').files || [];
  const files = mergeFiles_(current, bundle);
  const stamp = fmt_(new Date(), 'yyyyMMdd-HHmm');
  // backup first, so it can always be undone
  const backup = { app: 'JayaPOS', version: APP_VERSION, notes: 'Backup otomatis sebelum ' + (isRollback ? 'rollback' : 'update ke ' + bundle.version),
                   mode: 'full', files: current.map(function (f) { return { name: f.name, type: f.type, source: f.source }; }) };
  updateFolder_(true).createFile(BACKUP_PREFIX + APP_VERSION + '-' + stamp + '.json', JSON.stringify(backup), 'application/json');

  scriptApi_('put', '/content', { files: files });
  const ver = scriptApi_('post', '/versions', { description: 'JayaPOS ' + bundle.version + (isRollback ? ' (rollback)' : '') });
  const deps = (scriptApi_('get', '/deployments').deployments || []).filter(function (d) {
    const web = (d.entryPoints || []).some(function (e) { return e.entryPointType === 'WEB_APP'; });
    return web && d.deploymentConfig && d.deploymentConfig.versionNumber;   // skip the editor's "HEAD" test deployment
  });
  deps.forEach(function (d) {
    scriptApi_('put', '/deployments/' + d.deploymentId, { deploymentConfig: {
      scriptId: ScriptApp.getScriptId(), versionNumber: ver.versionNumber, manifestFileName: 'appsscript',
      description: 'JayaPOS ' + bundle.version } });
  });
  try { audit_(null, isRollback ? 'APP_ROLLBACK' : 'APP_UPDATE', 'System', String(bundle.version), { from: APP_VERSION, files: bundle.files.length, deployments: deps.length, version: ver.versionNumber }); }
  catch (e) { /* audit is optional */ }
  return { version: bundle.version, files: bundle.files.length, deployments: deps.length, versionNumber: ver.versionNumber };
}

function updateResultText_(r) {
  return 'JayaPOS ' + r.version + ' terpasang (' + r.files + ' file, versi Apps Script #' + r.versionNumber + ').\n' +
    (r.deployments ? 'Link aplikasi sudah diarahkan ke versi baru (link tetap sama).\n'
                   : 'PERHATIAN: tidak ada deployment web app yang ditemukan. Buat lewat Deploy → New deployment.\n') +
    '\nSheet baru / kolom baru dibuat otomatis saat JayaPOS dibuka pertama kali.\n' +
    'Di setiap HP, tutup JayaPOS lalu buka lagi.';
}

/** Menu: JayaPOS → 4. Update aplikasi */
function menuUpdate() {
  const ui = sheetUi_();
  try {
    const u = latestUpdate_();
    if (!u) {
      updateFolder_(true);
      ui.alert('Update aplikasi', 'Belum ada versi baru di GitHub maupun di folder Drive "' + UPDATE_FOLDER_NAME + '".', ui.ButtonSet.OK);
      return;
    }
    u.name = u.source;
    const same = versionNum_(u.bundle.version) <= versionNum_(APP_VERSION);
    const ok = ui.alert('Update JayaPOS',
      'Versi sekarang: ' + APP_VERSION + '\nVersi di file: ' + u.bundle.version + ' (' + u.name + ')\n\n' +
      (u.bundle.notes ? String(u.bundle.notes).slice(0, 600) + '\n\n' : '') +
      (same ? 'Versi ini TIDAK lebih baru. Pasang ulang?' : 'Pasang sekarang? Kode lama disimpan sebagai backup.') +
      '\nJangan dipakai saat kasir sedang menerima pembayaran.', ui.ButtonSet.YES_NO);
    if (ok !== ui.Button.YES) return;
    ui.alert('Update selesai', updateResultText_(applyBundle_(u.bundle, false)), ui.ButtonSet.OK);
  } catch (e) {
    ui.alert('Update gagal', String(e && e.message || e) + '\n\nTidak ada yang berubah kecuali disebutkan di atas.', ui.ButtonSet.OK);
  }
}

/** Menu: JayaPOS → 5. Kembalikan ke backup terakhir */
function menuRollback() {
  const ui = sheetUi_();
  try {
    const list = listBundles_(BACKUP_PREFIX).sort(function (a, b) { return b.time - a.time; });
    if (!list.length) { ui.alert('Belum ada backup.'); return; }
    const b = list[0];
    const ok = ui.alert('Kembalikan versi sebelumnya', 'Pasang kembali ' + b.name + ' (JayaPOS ' + b.bundle.version + ')?', ui.ButtonSet.YES_NO);
    if (ok !== ui.Button.YES) return;
    ui.alert('Selesai', updateResultText_(applyBundle_(b.bundle, true)), ui.ButtonSet.OK);
  } catch (e) {
    ui.alert('Gagal', String(e && e.message || e), ui.ButtonSet.OK);
  }
}

/**
 * For the FIRST install (or when the Sheet menu is not available): in the Apps Script editor choose
 * jalankanUpdate in the function list and press Run. Progress is shown in the Execution log.
 */
function jalankanUpdate() {
  const u = latestUpdate_();
  if (!u) throw new Error('Tidak ada update di GitHub maupun di folder Drive "' + UPDATE_FOLDER_NAME + '".');
  console.log('Memasang JayaPOS ' + u.bundle.version + ' dari ' + u.source + ' …');
  console.log(updateResultText_(applyBundle_(u.bundle, false)));
}

// ---------------- In the app (admin, also from a phone) ----------------

function apiCheckUpdate(token) {
  return run_(function () {
    requirePerm_(token, 'settings.manage');
    const u = latestUpdate_();
    return {
      current: APP_VERSION,
      latest: u ? u.bundle.version : null,
      notes: u ? String(u.bundle.notes || '').slice(0, 1500) : '',
      source: u ? u.source : '',
      newer: !!u && versionNum_(u.bundle.version) > versionNum_(APP_VERSION),
      backups: (function () { try { return listBundles_(BACKUP_PREFIX).length; } catch (e) { return 0; } })()
    };
  });
}

function apiInstallUpdate(token, version) {
  return run_(function () {
    const user = requirePerm_(token, 'settings.manage');
    return withLock_(function () {
      const u = latestUpdate_();
      if (!u || u.bundle.version !== String(version)) throw new Error('Versi update berubah. Tekan "Cek update" lagi.');
      const r = applyBundle_(u.bundle, false);
      audit_(user, 'APP_UPDATE_FROM_APP', 'System', r.version, { source: u.source });
      return r;
    });
  });
}

function apiRollbackUpdate(token) {
  return run_(function () {
    const user = requirePerm_(token, 'settings.manage');
    return withLock_(function () {
      const list = listBundles_(BACKUP_PREFIX).sort(function (a, b) { return b.time - a.time; });
      if (!list.length) throw new Error('Belum ada backup.');
      const r = applyBundle_(list[0].bundle, true);
      PropertiesService.getScriptProperties().deleteProperty('SCHEMA_VERSION');
      audit_(user, 'APP_ROLLBACK_FROM_APP', 'System', r.version, { backup: list[0].name });
      return r;
    });
  });
}

/**
 * Void.gs
 * Void (batal) and the notes ("Notifikasi") that go to the admin / owner.
 *
 *  - Void item  : items removed from a table bill that was already saved   -> Tables.gs (apiSaveOpenOrder)
 *  - Void bill  : a table bill with items closed without payment          -> Tables.gs (apiCancelOpenOrder)
 *  - Void paid  : a transaction that was ALREADY PAID is cancelled         -> apiVoidTransaction (below)
 *                 The sale stays in the sheet with Status VOID (nothing disappears), it is left out
 *                 of every report, and the recipe ingredients go back into stock.
 *  Every void needs a reason. Each one writes a row to the Notifications sheet; admin and owner
 *  see it under the bell icon in the app until they mark it as read.
 */

const NOTIFY_TITLES = {
  VOID_ITEM: 'Void item',
  VOID_BILL: 'Void bill (belum dibayar)',
  VOID_PAID: 'Void transaksi (sudah dibayar)',
  SHIFT_OPEN_DIFF: 'Modal awal tidak sama',
  CASH_IN: 'Kas masuk',
  CASH_OUT: 'Kas keluar',
  SETOR: 'Setor tunai (perlu konfirmasi)',
  SHIFT_CLOSED: 'Shift ditutup',
  SHIFT_DIFF: 'Shift ditutup — SELISIH KAS'
};

/** Writes one note for the admin / owner. Never blocks the action that called it. */
function notify_(user, type, refId, tableName, amount, reason, details) {
  try {
    const now = new Date();
    const who = user ? user.name : 'Sistem';
    const where = tableName ? ' di meja ' + tableName : '';
    const msg = who + ' — ' + (details || '') + where;
    const start = nextSeq_('NTSEQ_' + fmt_(now, 'yyyyMMdd'), 1);
    appendObjects_('Notifications', [{
      Notification_ID: 'NT-' + fmt_(now, 'yyyyMMdd') + '-' + String(start + 1).padStart(4, '0'),
      Timestamp: fmt_(now, 'yyyy-MM-dd HH:mm:ss'), Type: type, Title: NOTIFY_TITLES[type] || type,
      Message: String(msg).slice(0, 500), Reference_ID: refId || '', Table_Name: tableName || '',
      Amount: Math.round(amount || 0), Reason: reason || '', User_ID: user ? user.id : '', User_Name: who,
      Role: user ? user.role : '', Read_At: '', Read_By: ''
    }]);
  } catch (e) {
    console.error('notify_ failed: ' + e);
  }
}

/** Earliest date a user may void a paid transaction. */
function voidStart_(user) {
  if (hasPerm_(user.role, '*')) return '0000-00-00';
  const days = Math.max(1, parseInt(getSettingsMap_().Cashier_Void_Days, 10) || 1);
  return addDays_(todayStr_(), -(days - 1));
}

/** Void a transaction that was already paid. */
function apiVoidTransaction(token, txId, reason) {
  return run_(function () {
    const user = requirePerm_(token, 'pos.void');
    txId = String(txId || '').trim();
    if (!/^[A-Z]{1,5}-\d{8}-\d{4,}$/.test(txId)) throw new Error('Nomor transaksi tidak valid.');
    const why = checkReason_(reason);
    return withLock_(function () {
      const t = getTransactionById_(txId);
      if (!t) throw new Error('Transaksi ' + txId + ' tidak ditemukan.');
      if (t.status !== 'COMPLETED') throw new Error('Transaksi ini sudah ' + statusWord_(t.status) + '.');
      if (t.date < voidStart_(user)) {
        throw jayaError_('Kasir hanya boleh void transaksi hari ini. Transaksi yang lebih lama hanya bisa di-void oleh admin.', 'DENIED');
      }
      const stamp = nowStamp_();
      updateRow_('Transactions', t.row, { Status: 'VOID', Void_Reason: why, Void_By: user.name, Void_At: stamp });
      try {   // payments of a voided sale no longer count in the cash drawer / reports
        const upd = {};
        getPayments_(txId).forEach(function (p) { upd[p.row] = 'VOID'; });
        setColumnValues_('Payments', 'Status', upd);
      } catch (e) { console.error('void payments: ' + e); }
      let stockNote = '';
      try { stockNote = reverseSaleStock_(txId, user); }
      catch (e) { audit_(user, 'INVENTORY_ERROR', 'Transaction', txId, 'Void: ' + String(e && e.message || e)); }
      const items = getTransactionDetails_(txId);
      audit_(user, 'VOID_PAID', 'Transaction', txId, { total: t.total, method: t.method, reason: why, stock: stockNote });
      notify_(user, 'VOID_PAID', txId, t.tableName, t.total, why,
              items.map(function (i) { return i.qty + 'x ' + i.name; }).join(', ') + ' · ' + methodLabel_(t.method) +
              (t.shiftId ? ' · shift ' + t.shiftId : ''));
      return buildReceipt_(txId);
    });
  });
}

/** Puts back into stock what a sale took out. Returns a short note. */
function reverseSaleStock_(txId, user) {
  const sh = getSheet_('Inventory_Movements');
  const headers = getHeaders_(sh);
  const rows = findRowNumbers_(sh, headers, 'Reference_ID', txId);
  if (!rows.length) return 'no stock movements';
  const ings = {};
  ingredientsList_().forEach(function (i) { ings[i.id] = i; });
  const moves = [];
  rows.forEach(function (n) {
    const m = rowObject_(sh, headers, n);
    if (String(m.Movement_Type) !== 'SALE') return;
    const ing = ings[String(m.Ingredient_ID).trim()];
    if (!ing) return;
    const back = -numOr_(m.Quantity_Base, 0);
    if (back <= 0) return;
    moves.push({ ing: ing, type: 'VOID', qty: back, unit: ing.baseUnit, baseQty: back,
                 unitCost: numOr_(m.Unit_Cost_Base, ing.cost), ref: txId, notes: 'Void transaksi' });
  });
  applyMovements_(moves, user, {});
  return moves.length + ' ingredient(s) returned';
}

// ---------------- Notifications ----------------

function notifFromRow_(r) {
  return {
    id: String(r.Notification_ID), when: cellText_(r.Timestamp), type: String(r.Type), title: String(r.Title || r.Type),
    message: String(r.Message || ''), ref: String(r.Reference_ID || ''), table: String(r.Table_Name || ''),
    amount: moneyNum_(r.Amount) || 0, reason: String(r.Reason || ''), user: String(r.User_Name || ''),
    role: ROLE_LABELS[String(r.Role || '')] || String(r.Role || ''), read: !!String(r.Read_At || '').trim(),
    readBy: String(r.Read_By || ''), readAt: cellText_(r.Read_At)
  };
}

/** Number of unread notes (reads only the Read_At column). */
function notifUnreadCount_() {
  const sh = getSheet_('Notifications');
  const headers = getHeaders_(sh);
  const c = headers.indexOf('Read_At');
  const idc = headers.indexOf('Notification_ID');
  const lastRow = sh.getLastRow();
  if (c < 0 || lastRow < 2) return 0;
  const reads = sh.getRange(2, c + 1, lastRow - 1, 1).getValues();
  const ids = sh.getRange(2, idc + 1, lastRow - 1, 1).getValues();
  let n = 0;
  for (let i = 0; i < reads.length; i++) {
    if (String(ids[i][0]).trim() && !String(reads[i][0]).trim()) n++;
  }
  return n;
}

function apiGetNotifications(token, filter) {
  return run_(function () {
    requirePerm_(token, 'notifications.view');
    filter = filter || {};
    let list = readRecentRows_('Notifications', 500).map(notifFromRow_).filter(function (n) { return n.id; }).reverse();
    if (filter.unreadOnly) list = list.filter(function (n) { return !n.read; });
    return { unread: notifUnreadCount_(), items: list.slice(0, 200) };
  });
}

function apiNotificationCount(token) {
  return run_(function () {
    const user = requireSession_(token);
    if (!hasPerm_(user.role, 'notifications.view')) return { unread: 0 };
    return { unread: notifUnreadCount_() };
  });
}

/** ids: array of Notification_IDs, or 'ALL'. */
function apiMarkNotificationsRead(token, ids) {
  return run_(function () {
    const user = requirePerm_(token, 'notifications.view');
    return withLock_(function () {
      const all = ids === 'ALL';
      const want = {};
      if (!all) {
        if (!Array.isArray(ids) || ids.length > 500) throw new Error('Pilih notifikasi yang mau ditandai.');
        ids.forEach(function (id) { want[String(id)] = true; });
      }
      const stamp = nowStamp_();
      const readAt = {}, readBy = {};
      readTable_('Notifications').rows.forEach(function (r) {
        const id = String(r.Notification_ID || '').trim();
        if (!id || String(r.Read_At || '').trim()) return;
        if (all || want[id]) { readAt[r._row] = stamp; readBy[r._row] = user.name; }
      });
      setColumnValues_('Notifications', 'Read_At', readAt);
      setColumnValues_('Notifications', 'Read_By', readBy);
      return { marked: Object.keys(readAt).length, unread: notifUnreadCount_() };
    });
  });
}
